/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040930-14","meetingId":"h16-cm09","date":"2004年9月30日","dateIso":"2004-09-30","committee":"行財政改革特別委員会","time":"午前１０時０４分～午前１１時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"行財政改革に関することのうち、有料施設の有効活用に関すること","agenda":"行財政改革に関することのうち、有料施設の有効活用に関すること","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"一つ気になったのが、視覚障害者の方の対応とか、それから高齢者、文字のサイズが小さく感じましたので、特に集会所施設系ですか、こちらのほうの予約される方の中には、高齢者の方は多いと思われますので、そういう単純なところですけど、文字のサイズの対応とか、それから音声案内、声の案内ですね、これがなかったと思いますので、そのことの対応はどうなっているかということ。","respondent":"田中情報システム課長、榎本行財政改革担当課長","answer":"当然いろいろ政府のほうも検討してきた上で決まったものですから、これに当然障害者や高齢者の人たちが拡大文字も含めて、文字表示も含めて対応していかなければいけないというふうに思っていますので。その考え方は、税とか国民健康保険とかの窓口払いから口座振替に変えたときにも、口座振替の手数料というのは区が負担しているという考え方と統一的な考え方でやっているです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"音声案内はすぐにはできないと思いますけど、ぜひ対処していっていただきたいと考えていますので、よろしくお願いいたします。それから引き落としのほうでもう一つお伺いしたいのは、７円３５銭、逆に品川区がメリットがあるということであるならば、逆に言えば、これをした結果として、７円３５銭以上もうかっているわけですね、変な言い方だけど。その金額はどれぐらいでしょうか。","respondent":"榎本行財政改革担当課長","answer":"ちょっと引き落としの金額の件はデータ等がありませんので、ちょっと申しわけございません、ありません。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"引き落としの件は、そうすると、ほかのところも同じような考え方であるというふうに考えてよろしいですよね。いかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"はい、引き落としにつきましては、現在はその区の手数の部分を代替したということでの手数料という形ですけども、事務当たりの手数料というのはそれぞれ違いがありまして、そこの適正価格についてはそれぞれ引き落とされる、業者側ですとか。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問・要望","question":"無所属の会で出された意見の中で、「４０、５０人で使える広いスペースなのに、利用者が５、６人しか使っていない現状を何カ所も見ましたが、とても有効な使い方とは思えません。これについては、２５人の部屋があいていない場合に、料金は高くても、その日にどうしても会合をしなくちゃならない。やはり、広いところも確保しておいていただきたいというのが区民要望です。ちょっと申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"今後のこのまとめ方についての考えを、今日施設予約システムを見て新たに追加して全部出そろうというのはわかるんですが、今後どういうふうにこれをまとめていくのか、ちょっと今正副委員長でというふうな話があったので、全体像を示していただけますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"今日午後も時間をとっていると冒頭言われたので、午後各会派が今出ているあれについて説明があって、その説明を受けて、これは私の思いですけど、一致する点と一致しない点、整理した上で例えば正副委員長で、こんなのでどうでしょうかという第１次案みたいなのが出て、それに基づいてまた全体で検討してみるペースだったのかなと思うんだけども、そう急ぐこともないことは事実なんですけど、先ほどですと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"ところが、今回は会派の個別意見が今出ています。沢田委員の発言にも重なりますけど、要は、そこを今度は委員会としてどう調整をとっていくんですかということ。それについて全体的な調査をした後、会派の意見を出すというのが普通の手順でありますけれど、たまたま今日そうなったかもしれませんが、これからの取り組みとか取りまとめの仕方の確認をもう一度お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"すみません、もう一つだけ確認したいんですが、ということは、１２月までにもう一度各会派で個別意見を出すんでしょうか。それじゃなくて、例えば私たちが１１月に千葉の市川市に行く、そういうような発言の内容とか、それからいろんな、これから開かれるであろう行財政改革特別委員会での議論を正副委員長でまとめてくださるのか。意味、わかりますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その二つ、大きな違いがあるんですよ。そのことの確認をぜひここでいただきたいんです。これからどうしていくかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"確認","question":"確認なんですけど、そうすると、１２月には正副委員長のまとめた案が出てくると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"それはいつごろまでとか、そういうのを言ってもらったほうがいいんじゃないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"その中身は、スポーツ施設については平成１５年度でしたか、集会所施設のほうは今年度、こういう施設の予約システムを導入したという先ほどご説明がありましたので、お尋ねをしたいのは、要するにこういうインターネット等を利用して、こういう施設予約システムを導入した以降、以前、要するに今日は行財政改革特別委員会ですから、改革がどの程度進んだのかということですね。これなんかも非常に便利ですね。","respondent":"榎本行財政改革担当課長","answer":"ただ、集会所施設系のほうにつきましては、まだ利用が少なくて、やはり集会所施設系のほうの利用の実態から申しますと、定例的に利用される団体が多いので、１回利用したときに次の予約をとっていくというようなスタイルがありまして。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"市川市役所について、もし、こんな点を特に注目していきたいんだというのがあれば、教えていただけるとありがたいんですが。","respondent":"田中情報システム課長","answer":"そこの特に部長は全国的にも有名な人で、あちこち講演等をやっておられるという自治体です。どうもうまく説明できなくて申しわけありません。大体概要はそんなところです。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167584?Template=document&Id=5762#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":12692,"voices":48}},{"id":"h16-20041004-4","meetingId":"h16-c-settlement","date":"2004年10月4日","dateIso":"2004-10-04","committee":"決算特別委員会","time":"午前１０時０５分～午後５時５０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を138件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内副委員長","kind":"質問・要望","question":"第１項理事および理事会の設置についてです。閉会予定時間は区役所の執務時間と同じく、午後５時１５分を目途といたします。１人当たりの質問時間は答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。経過時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値についての説明が終わりました。 それでは、平成１５年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値についての説明が終わりました。 それでは、平成１５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"歳入のところでもご説明いただいたように、一般財源と特定財源の構成比率のことについてお伺いしたいと思いますが、一般財源というのは、ご案内のとおり、使途が特定されていない財源で、特定財源は、逆に特定されているということで、区の独自性を発揮するという観点からすると、本当は特定財源よりも一般財源のほうの構成比率が大きくなるほうがいいかと思われますが、ここ数年の傾向を見ますと。","respondent":"市岡企画財政課長","answer":"一般財源のほうは、平成１５年度の決算につきましては、区税が若干マイナスですが、財調が最後の再調整と申しますが、年度末にきて算定残が将来の起債償還経費に充当するという形で追加交付された、こういうことで一般財源が伸びているという状況です。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"当初から言っているように、独自性を発揮するという観点から言うと、一般財源をより確保していくということが、我々区民にとってはプラスになると思いますので、一般財源確保のためのご努力、知恵、工夫が今までどのような観点でなされてきたのか、ちょっと将来的な話になりますが、法定外目的税といいますか、新税ということも。","respondent":"市岡企画財政課長","answer":"独自課税の問題ですが、昨今豊島区の自転車税で話題になりましたけれども、これまでご答弁申し上げているとおり、一般的な意味で言えば、区の独自課税というのは、豊島区の例は納税義務者を鉄道事業者にしましたけれども、一般的には区民に対する増税という形をとりますので。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと別の切り口でお伺いしてまいりたいと思いますが、当初予算がありまして、決算を迎えるにあたりましては、その年度の途中で最終的な補正予算があって、決算を迎えるという、こういう手順になっております。ないということは、特定財源が、当初から一般財源であれば補正を組む必要はないというように思えるんですが、その辺の観点からの補正予算の考え方をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"さまざまなものがありますでしょうが、例えば９月補正の場合、今回も、平成１５年度の場合も、それぞれ年度途中で生じた事情に的確に対応するために、特に特定財源を中心とした補正を行ってあります。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、その地域住民が都民であるよりも区民であるほうがいいんだということを思ってもらうためには、区の施策がよりきめ細かくということで言うと、特定財源よりも一般財源を増やしていくことのほうがいいのではないかというふうな思われ方をします。そういった観点から、区民に向けて分かりやすく、なぜ今改革を行っているのかをお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"例えばパンフレットをつくる、あるいはいろいろなところでご説明をする、こういう一面的なやり方ではなかなかご理解がいただけないので、あらゆる場で説明ができるような体制をとって、今後も広く財政自主権の確立ということが、区財政。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"最後に要望として、これを区民がどう見るかですが、ややもすると、今の制度改革の動きというのは、一つのある特定の税金を東京都と区が取り合っている、あるいは国と区が取り合っているというようなふうにしか見えないという声も少しあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"若林委員","kind":"提案","question":"委員会等でも、また予算要望等でもさまざまな議会側からの提案、要望、また政策提言という形で出されていると思いますが、このような議会からのシグナル、提言が、大ざっぱな話ですが、例えばどこに、だれが、どのような形で、このような数々の要望をストックをして、どういう場面で内部において検討をされるのか、ここをまず出発にあたってちょっとお聞きしたいなと思います。","respondent":"市岡企画財政課長","answer":"今事業部編成枠方式でそれぞれの事業部が自主的に予算を編成する権限というのも増えてまいりましたので、これらを各事業部長を中心にして、それぞれ予算編成の会議等をやってありますが、その中で十分検討をしている、このような状況です。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"私たち議会側からのさまざまな要望、提言というのはオープンな形で、公式にされております。一方、１回投げたボールというのは、今の助役の通達等々で内部においてしっかりとストックをし、またこねて実現していく。この１点だけ、これからのさまざまな予算編成に向けての、私たちからのボールについてどのような透明性を確保していかれるお考えか、この点だけお答えをお願いいたします。","respondent":"市岡企画財政課長","answer":"これらについては誠意を持って一つずつご回答を申し上げておりますし、それから、予算編成の中で、これは一つずつご要望に対してお答えするというよりは、予算編成の結果がいろいろなご要望の形を、編成の考え方を含めてよく分かるように。","id":"exchange-008"},{"speaker":"若林委員","kind":"意見","question":"本題のほうに入ります。１０４ページの放置自転車の保管料のことです。当初予算、予算現額と決算の対照比較をお聞かせ願いたいと考えています。それと同時に、当然これまでの放置自転車対策、その成果、併せて、来年度に向けての今後の放置自転車対策、考え方をお聞かせ願えればというふうに思っております。","respondent":"山口交通安全担当課長","answer":"台数については、プラス１,０９８台となっております。対策につきましては、本年度から撤去時間の延長、また保管返還時間等の延長を実施していますので、さらなる対策の強化に努めてまいりたいと思います。","id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"今後のことですが、当初予算の考え方と、決算が、台数、決算額においてはほぼ予想どおりというふうに理解をしております。これからの放置自転車対策、撤去と同時に、新たなさらなる努力が非常に大切になってくるなというふうに思います。そこで、現状は禁止区域を設けられておりますけれども、禁止区域の拡大の考え方、そこら辺をお聞かせ願えればと思います。","respondent":"山口交通安全担当課長","answer":"撤去台数も、先ほど申しましたとおり、クリアな状況になるように努力させていただきたいと思います。先ほど質問が１点漏れましたが、決算と予算の関係ですが、さらに努力を重ねて、収入と申しますか、撤去台数の増加に基づいた財源等の増加に努めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続き努力をいただきたいと思います。それから、９４ページの緊急地域雇用対策の収入についてです。緊急地域雇用特別交付金です。これは国の事業と聞いておりますけれども、率直にこれの雇用に対する評価を、区としてのお考えをお聞かせ願えればと思います。","respondent":"榎本行財政改革担当課長","answer":"平成１６年度は計画中です。そういった意味で、それぞれ地域の実情に合った緊急的な新規雇用に向けた施策が実施できたというふうに考えております。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"国の事業を活用しながら、品川区としても３年間で６９８人の雇用があったという評価だと思います。それでも継続的に、また緊急的に品川区として今まで行った７つの事業がありますけれども、これをスパッと切れるかどうか、国のお金が入らなくなったので、雇用の考え方はここでスパッと切ってしまう。この考え方をお聞かせ願えればと思います。","respondent":"榎本行財政改革担当課長","answer":"ただし、中には幾つか継続して効果を図ったほうがいいという事業もありまして、その点につきましては、今所管と検討をしまして、一般財源であっても継続したほうがよいというものであれば、それは継続していきたいという考えでおります。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"大半は臨時的ということでございましたが、平成１５年度の決算を見ているわけですけれども、成果報告書の１８ページに７項目載っております。２つお尋ねいたします。それ含めた７つ、どれが臨時的で、今これから検討をされるということですが、どうしてもこれは品川区として必要なのだ、継続する必要があるんだと。今のお考えの中で方向性を示していただければ、お出ししていただきたいと思います。","respondent":"日下部産業振興課長、榎本行財政改革担当課長","answer":"緊急雇用の補助金のうちにぎわい商店街のクリニック事業に関するご質問ですけれども、これにつきましては、国のほうともいろいろ調整をした経過の中で、雇用の補助金について、さらに拡大をして。継続したほうがいいというふうな形で、今検討をしておりますのは、この７つのもので言いますと、２番目のひとり親家庭パソコン教室、３番目の新就業システム推進事業。","id":"exchange-013"},{"speaker":"大西委員","kind":"質問・要望","question":"私のほうからは、特別区区民税の推移と、４０ページ、自転車駐車場使用料ならびに区営住宅、区民住宅使用料等について、４２ページ、歴史館使用料についてお尋ねいたします。それと、自転車駐車場の使用料についてですけれども、現在どれぐらいの有料駐輪場の利用率がありますでしょうか。しかしながら、小さな子どもたち、せめて小学生のときに社会科で大森貝塚とか、いろいろな勉強をしていきます。","respondent":"榎本行財政改革担当課長、山口交通安全担当課長、阿部住宅課長、上川内生涯学習課長","answer":"１点目の、難しい質問ですけれども、どのような施策をしているかですけれども、人口のほうの大まかな流れを言いますと。委員ご質問の有料駐輪場の利用率の関係からご説明をします。大変恐縮ですが、トータル的な数字はございませんが、個別にお答えします。滞納の件ですけれども、区民住宅につきましては、平成１３年度からとってありますけれども、平成１３年度が９８９万円余です。","id":"exchange-014"},{"speaker":"大西委員","kind":"質問","question":"今、特別区民税の中でお伺いしたところで、非常に難しい質問であると言われましたが、お答えの中で、いろいろな施策を組み合わせていく必要があるということですけれども、具体的にどういう施策を行えば、そういう方々が多く品川区に入ってきてくれるか、例えば港区であれば、昨今であれば、プロ野球球団を欲しいと言っているライブドアの社長などは賃貸ですけれども、六本木ヒルズにお住まいだと。","respondent":"榎本行財政改革担当課長、山口交通安全担当課長、上川内生涯学習課長","answer":"その結果として、その施策に魅力があれば、その魅力を感じた人が外から入ってくるというような形であるというように考えております。個別的には天王洲アイル等は低いんですが、チラシ等で自転車駐車場の所在、利用できるというＰＲ関係を鋭意これから努めていきたいと。品川歴史館につきましては、授業で先生が引率するときも無料ですが、子どもだけで宿題とか。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"私からは２点お伺いをします。３年ばかりずっと税収が上がっていたということでありますけれども、今回の決算書を見てみますと、普通徴収分についても、特別徴収分についても、昨年度と比べますと、若干ながら落ち込んでいるというふうになっていますけれども、普通徴収分、特別徴収分に分けた、その辺の背景、理由というのを教えていただきたいと思います。","respondent":"太田税務課長、黒田保険年金課長","answer":"収納率につきましては、苦しいながらもお支払いをいただいて、平成１４年度はわずかですが、上回って、９１.５５％ということで、約０.０８％ですが、収納率は向上したです。収納率は分母が増えてありますので、どうしても下がってありますので、現在、資格証、短期証等の発行につきまして、適正な収納をしていただくよう努力しているところと、あと、ＰＲ、その他、口座振替の促進。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"先ほども大西委員の質問に答弁が出ておりましたけれども、中堅所得層が増加をすることで、特別徴収分について言えば、平成１３年度、平成１４年度についてはかなりアップをしていったという話がありましたけれども、今のお話ですと、経済状態が悪いんだということですけれども、実際にまちへ行ってみますと、これまでと同様に、かなり大型の集合住宅の建設が相変わらず進んでいまして。","respondent":"太田税務課長、黒田保険年金課長","answer":"１点目のご質問にお答え申し上げます。私が先ほど申し上げましたのは、平成１５年の決算ですので、平成１５年度の調定額については平成１４年の収入に対してかけるんだというお話を申し上げたわけです。短期証の中でも、２割まではお支払いいただいた中では、資格証ではなく、短期証の継続ということで、ご相談に応じてあります。納めていただく、これが基本ですので、どのようにしたら納めていただけるかというご相談に応じてあります。","id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"国民健康保険ですけれども、今１５０万円の収入というお話をされていましたけれども、１５０万円の収入で、実際に支払うことができるのかというと、生活状況そのものはかなり厳しいものになるんじゃないかというふうに思うんです。","respondent":"黒田保険年金課長","answer":"お一方２０万円から３０万円というような方ということで、中には完納されたとか、やはり働きかけの問題だという、こちらの側は〔時間切れにより。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に歳入全般の中、今朝ほど収入役からご説明いただいた中で、ちょっと確認と、わからなかった点がありまして、単年度収支額が２億２,９００万円ぐらいの赤字になったと。ここら辺がどう絡んでくるのか。それから、前年度から繰り越す分が、これも随分数字が違うような感じがするんですが、当然会計上の問題ということになってくるんですが、そこら辺を先に確認をさせてください。","respondent":"市岡企画財政課長","answer":"例えば繰り越しにつきましては、収入役が申し上げたとおり、自治法の公会計では繰り越しは３つしか認められないんですが、旧正田邸の用地の打ち切り再計上は事業繰り越しとして決算統計上は認められている。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"まだ全体ちょっと分かりにくいところがあるんですけれども、３億円の分は理由は分かりますけれども、品川区として単年度赤字になってくるというのが、もうちょっと何か、決算の資料の中に分かりやすくしておいたほうがいいのではないのかなと思います。寄附金のほうですけれども、決算状況一覧表の中で、款別の数字と随分違いが出ているんですよね。ここら辺の理由はどうなっているのかを教えてください。","respondent":"市岡企画財政課長","answer":"これは国土交通省の補助金の残りを地元の開発事業者が品川区のまちづくりに賛同して拠出していただいているわけですので、割り当て的寄附でも何でもありませんで、正々堂々ともらえばいいんですが、予算書、決算書にまともにそれを出しますと。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川区の事業に賛同してということの都市基盤整備の分、なるべくうまくその辺も処理上の問題になると思うんですけれども、ぜひうまく進めていただければと思います。会計上の関係で、もう1点、減価償却というのは当然ない分ですよね。そこら辺の運営コストにおいて、品川区の中でどういうふうに考えていらっしゃるのかということを教えてください。","respondent":"市岡企画財政課長","answer":"それで、公会計にはこういうものの考え方そのものがありませんので、予算書、決算書上はそのまま出てきませんけれども、現在行っている事務事業評価、あるいはバランスシートの作成の上では、コストの中に減価償却費というのを一定の計算式で入れてあります。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"企業会計という問題とか、今の企業会計手法の問題もかなり意識を持っていって、無駄なものは削減できるように、考え方としての分をひとつよろしくお願いしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"本田委員","kind":"意見","question":"今月７日の都議会本会議でそれが承認されるという動きを都政新報で知りまして、これはどういうことになっているのか、特別委員会では区長会は知事のみならず、都議会議長および各会派に区の要請行動を行ったという報告も受けているところでありますけれども、それとは違った動き、いわば東京都の主張を応援するような内容の報告がまとめられたやに受けているんですけれども。","respondent":"市岡企画財政課長","answer":"内容は２点ございまして、１点は、東京都の持てる力を引き出す上で有効にこの財調制度が機能しているか検討をする必要がある。それから、大都市経営の観点から、都区間の財政調整制度というものを大都市行政の統一性、一体性の観点から、もう少し深めた議論をする必要がある。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"これに対して、今のようなご見解はそれはそれとして理解できますけれども、都議会、各会派を含めて要請をしていたことが十分理解されないというふうに思わざるを得ないのでありますけれども、区長会の中で重要な役割を果たしている品川区長の立場としましても、本当に２３区民、８００万人の願いというものをどう受け止めているのかというふうに。","respondent":"高橋区長","answer":"しかしながら、都区の一体性の問題、都区の一体性も重要ですが、その前に、やはり都区間で仕事の役割分担をはっきり決め、それで一体性を確保するような方法を考える。そういうふうな道筋が私は必要ではないかと考えています。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問","question":"ですから、区長会が先頭に立っているわけでありますけれども、今区長のご答弁をいただきましたが、もっと区民、都民への宣伝と同時に、各会派、都議会に対するアプローチの仕方というのは研究をすべきではないか。時間的にも大変差し迫った時期にきているわけですから、もっと積極的に対応をしていくべきではないかというふうに思いますが、もう一度ご見解をお尋ねします。","respondent":"高橋区長","answer":"そういう意味で、東京都と２３区を見つめ直していただいて、東京都の財源をより区のほうに、こういう主張は今回の三位一体論に何ら反するものではなく、また、東京都の主張に反するものではないと考えています。","id":"exchange-025"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうからは、７２ページの総務使用料の庁舎使用料に関連してと、１０３ページの庁舎の駐車場利用料に関連して３点お伺いをします。初めに、庁舎駐車場の利用料ですが、これを見ますと、１万９,２７３台で１,０００万円を超える収入が、ご利用をいただいているですが、まず初めに、１万９,２７３台の内容といいますか、駐車場をオープンしている時間等を教えていただきたいと思います。","respondent":"鷹倉経理課長","answer":"私ども今スイッチで付けるか、消すかという仕組みになってありますので、どの部分をどういう形で付けていけば一番安全に快適に使っていただけるか、この辺を少し調査をしながら、ご指摘について前向きに検討をしていきたい、このように考えてあります。","id":"exchange-026"},{"speaker":"嶋委員","kind":"質問・要望","question":"昼間も庁舎を利用されている方も含めて夜間と思いますが、普通民間の駐車場は夜間になると割引とか、また、お酒を飲んでしまうと置いていかなければいけないことがありますが、そういう場合は夜間割引というのは最大限１,８００円とか２,０００円とか安く減額をして、一般の駐車場はしておりますので、品川区の役所に関しても、近隣に駐車場がない、今回広町ができましたけれども、そういう意味で。","respondent":"鷹倉経理課長","answer":"委員のご指摘等も以前にもございまして、たしか平成１１年か１２年だったと思いますけれども、半額にしています。１台２００円、超過に従って１００円というような形に現状進めしています。","id":"exchange-027"},{"speaker":"嶋委員","kind":"質問・要望","question":"７階に確かに個室がございまして、その個室のお部屋は今までどのように使用されていらしたのか、また、授乳室に関して、だれでもトイレという形で、物を置いたりとか、お子さんと一緒にトイレに入るということでは、皆様から喜びの声を聞かせていただいておりますが、授乳室に関して、品川区としてどのように考えていらっしゃるか、お聞かせいただきたいと思います。","respondent":"鷹倉経理課長","answer":"この休憩室、ベビーベッドの置いてあるところで授乳をされている場合もあるのかなというふうに理解しているわけですけれども、ご指摘のとおり、明確に位置づけているわけではございませんので、その点、授乳される方について。","id":"exchange-028"},{"speaker":"嶋委員","kind":"質問・要望","question":"今のところを使われるですが、要望にさせていただきたいと思いますが、やはり授乳室というのは、お母さんはゆっくりとお子さんと一緒に過ごす時間ですので、できましたら、大変すばらしいしながわ中央公園がありますので、ぜひしながわ中央公園を眺めながらそういうお部屋が確保できたらと思います。","respondent":"鷹倉経理課長","answer":"いずれにいたしましても、いろいろ検討、あるいは研究をさせていただきながら、区民の方々が区役所に来やすいような状況を生み出していきたいと考えています。","id":"exchange-029"},{"speaker":"本多委員","kind":"質問・要望","question":"９８ページの財産貸付収入、職員住宅利用料、教職員住宅利用料、それと１７０ページの職員費に関連しましてお伺いいたします。今の状況と、それに伴う財産管理について、どのような状況か教えていただきたいと思います。","respondent":"桑村人事課長","answer":"これは一つは、職員の住宅事情がよくなってきたというのが一つの大きな理由だろうと考えています。それに併せて、どの程度の職員住宅が必要なのかということを内部的に検討をしてまいりました。","id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"数年前の課題がほとんど払拭されてきたということで、それぞれいろいろな工夫はされてきたと思います。今断る状態ということで、そうなのかと思って、教えていただきました。地方公務員法との係わりですとか、他区の職員との整合性ですとか、その辺の対応とか、検討というのは、どのように進めてきたのか教えていただきたいと思います。","respondent":"桑村人事課長","answer":"自治法等の改正等もございまして、今後はいわゆる職員と教職員との垣根をどういうふうになくしていくか、あるいは転用等をやっていくかということが一つの課題なんだろうと思います。今後とも庶務課を含めまして、教育委員会と十分協議をしてまいりたいというふうに思います。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問・要望","question":"職員全体に対してどのくらいの割合で待機寮とか必要かという、いろいろな観点から見まして、執務時間を入れたり、執務時間外とか、いろいろなことを含めまして、どのくらい構成比率で必要なものか、また、全体を通してどのくらいの割合で、いろいろ対応するために区内在住というのが望ましいのか、ちょっと考え方をお聞かせいただきたいと思います。","respondent":"桑村人事課長","answer":"その意味で、区内在住が非常に少なくなってくるような状態であれば、さらにそれなりの考え方を出さなければいけないと思ってありますけれども、今のところ現状で大丈夫だろうというふうに思ってあります。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問","question":"決算の全体を見まして、人件費の構成比率が毎年下がってきているということで、それは確かに行財政改革ということでいろいろと努力されているのが数字に反映されていると思うんですが、過日、任期付職員の採用に関する法改正ということで、この辺、現行の非常勤ですとか、再任用とか、いろいろと制度を活用されておりますけれども、どのようにお考えか、教えてください。","respondent":"桑村人事課長","answer":"必要なことを検討してまいりまして、今後条例化等が必要ですので、必要であれば条例化をお願いして、ご議論をしていただきたいというふうに思ってあります。","id":"exchange-033"},{"speaker":"本多委員","kind":"質問・要望","question":"まさに今検討をされ始めたというところでしょうから、難しいかもしれませんけれども、例えば長期的かどうかわかりませんが、中期的、短期的、いろいろな施策の転換とかで、専門性の方を制度で活用するとか、これからの話だと思いますけれども、例えば具体的にどのような施策で、どのような部署でそういったものが対象になっていくか、現状で今のところの考え方を教えていただきたいと思います。","respondent":"桑村人事課長","answer":"その意味でもう少し研究をさせていただいて、ほかの部署ですと、今まで専門的なものですと、ＩＴの活用をやるためにここ数年で何人かの人が必要だとか、あるいは新規の図書館なり、歴史館なり、そういった施設をつくるときに、先ほど言いましたとおり。","id":"exchange-034"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ検討ということですけれども、当然民間の活力を生かせる場合には、そういった方向でしっかり考えていただいて、施策の内容によっては制度があったり、十分その辺はめりはりと言いますか、配慮をして進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"歳入全般というか、少子化対策への姿勢をお伺いしたいと思います。区の進捗状況を教えていただきたいのと、２３区を見ますと、平成１５年度の補正予算においてニーズ調査の予算が補正で組まれて、ほとんどのところが調査が行われているというところにおいて、品川区がなぜニーズ調査を省いているのか、その理由をお聞かせいただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それと、次世代育成の協議会の進行のほうですけれども、８月４日に第１回目の協議会を開いておりまして、行動計画に向けての議論をスタートしたところです。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区の場合は子育てのモデルに選ばれて、先進的にやっているので、既にニーズが把握できているといったお答えと受け止めていいのでしょうか。次世代育成支援対策推進法は今までの少子化対策と比べると、子育て家庭の支援から、さらに広げて、子育ての社会化といったところまで広げられているというところでは、幅広いニーズを調べることから始まっていくのではないかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"協議会の中身なんですが、先日、議事録をいただきたいと言ったらば、協議会の皆さんにお諮りしないと出せないと言ったところなので、なぜ区民の代表、公募委員が中に入って行われているのに、話し合われた中身の記事録を一つひとつ断らないと出てこないのかというところでは、もっと透明性を高めていただきたいなと思っているんですが、いかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"実際にニーズ調査につきましては、国のほうである程度モデルを出して調査をするようにという、モデル調査表がありましたけれども、その中では子育て支援策と、あとは就学後のモデルということで、いろいろ出されておりまして、そういういろいろな調査につきましては。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新宿区と世田谷区は先行しているということですけれども、それは重々承知です。さっきの質問の中で、区民の意見の表明の機会をきちんと設けてほしいということは、これは今後のことなんですけれども、この点についてお答えをいただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"意見の表明の関係ですけれども、今後の次世代育成の案をそれぞれパブリックコメントということで議会にまずご報告をいたしまして、その後区民に聞いていくという手順を今のところ予定しております。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"品川区は特定事業主となってるわけですけれども、この部分の計画について中身を伺いたいんですが、特に今女性が働きやすい職場となるために品川区が率先をして行っていく役割は重要かと思うんですが、その点を１点お伺いをしたい。財源について、今、国の補助金の削減がいろいろ出されている中で、次世代育成支援を実際行っていく上での財源がどのようになっているか、教えてください。","respondent":"桑村人事課長、榎本行財政改革担当課長","answer":"特定事業主行動計画の品川区ということでお聞きになられたんだと思って、私のほうでお答え申し上げます。品川区も特定事業主の計画ということで、本年度中につくるということで計画をしています。ただ、今回、子育て支援のモデル事業のほうで次世代計画を含めて、そちらでも考えていいということなので、その辺の財源も有効に使って、この行動計画の中身を子育て支援の計画のほうにも反映させていきたいというふうに考えております。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区のところは今職員の意識調査も行われているということですけれども、この辺で一番には働きやすい社会をつくっていくという意味では、男性の理解、また、アンケートなどでは、職場の上司の理解とかという書き方もしているわけですけれども、この辺で、従来のやり方では変わっていかないということで、新たに示していかれる方向というのがあるのかどうか、その辺を聞かせていただきたい。","respondent":"桑村人事課長","answer":"従来のやり方もそんなに間違っていたとは思ってございませんけれども、ただ、それについてはもう少し制度周知なり、あるいはとりやすい環境といったもの、それから、もう一つは、男性の育児に関する関心というんでしょうか。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"私からは、成果報告書の６７ページの一般会計歳入全般と、１７０ページの職員費について伺います。２００３年度の一般会計の歳入全体で収入未済額と不納欠損額が出ていますけれども、これを今までの経過も含めて、どのように評価をしているのかお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"不納欠損についても、これは平成１５年度の決算について特別な状況はありませんが、不納欠損は、ご案内のとおり、法令で定められた、例えば時効の完成とか、債権の消滅とか、債権管理上限定的な理由がある場合のみに限られる特殊な会計処理の方法ですので。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"今日配付された資料にも、不納欠損内訳資料というのがあるんですけれども、ここで少しお伺いしたいんですが、時効完成分と執行停止分、執行停止即時消滅分というのは、どういうものなのか、少しご説明いただければと思います。","respondent":"太田税務課長","answer":"不納欠損の関係についてご説明申し上げます。地方税ですので、税ということでお話をさせていただければと思います。地方税法の中で、それぞれ要件が決まっております。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"毎年、前年度の調定額が決まって、税金になるわけですが、そういう方たちは継続してそういう状態になってしまうのか、もうそこでそのままずっとほかの生活保護に行かれたりとか、いろいろな状況、その年で終わってしまうのか、継続するのかというのは、いかがでしょうか。","respondent":"太田税務課長","answer":"収入が継続してなくて、生活保護基準以下であれば、ご本人が申請して、生活保護ということになるでしょうし、徴収税がかかって、またその年にお支払いができないという理由があれば。","id":"exchange-044"},{"speaker":"井上委員","kind":"確認","question":"もう一つ確認という感じになってしまうんですけれども、国庫補助金で調定額が決まっていながら、収入未済額が発生しているんですけれども、こういう補助金とか、委託金とか、そういうときにはそういうものはないような気がしていたんですけれども、実際にこのケースの場合には何がそういう状況になっているか、教えてください。","respondent":"市岡企画財政課長","answer":"国庫補助金の６億５,０００万円ほど収入未済になっておりますのは、確定的に入らなかったわけではなくて、繰越明許費、つまり予算成立後、性質上の理由、あるいは特別な理由で入らないことがあらかじめ分かっていて。","id":"exchange-045"},{"speaker":"井上委員","kind":"意見","question":"今回特別区債が４６億円という非常に大きなものになっていると思うんですけれども、自治体としてこういった債権にあたるような、実際借金にあたるようなものだと思うんですけれども、歳入の構成比で、本来適正な構成比というのはどのぐらいというふうに考えたらいいのか、お答えください。","respondent":"市岡企画財政課長","answer":"それに対して品川区の場合は、どうしても必要な起債に限って、後年度の負担を過大にしないように、一つずつの起債の性質を勘案してやっているところでございまして、私は個人的には５０億円ぐらいの起債というのは全く財政構造にとって影響を与えないばかりか。","id":"exchange-046"},{"speaker":"井上委員","kind":"意見","question":"３.７％というのが大きいのかなと思ったら、まだ５０億円ぐらい大丈夫ということで、国債もそうですけれども、結局は、次世代に残す負債であるわけで、これからの学校建築とか、そういったところでも、国からのお金だったりするかもしれないんですけれども、事実上ずっとそういう状況になるとは限らないわけで、２５年間かけて返済計画も出ていますけれども。","respondent":"市岡企画財政課長","answer":"今品川区の公債費比率は６.８％というのを決算の冒頭の説明で申し上げましたけれども、これは非常に少ない数字でございまして、後年度に対する負担は極めて良好な状態にあるということが言えようかと思います。","id":"exchange-047"},{"speaker":"井上委員","kind":"意見","question":"これからも健全な財政運営というものをしてほしいと思います。職員費のほうですけれども、保育園の調理代行が３７園で完了したわけですけれども、この中に入っています教育職員費と学校職員費というのは、教諭は入っていないと思うんですけれども、どういう人たちをここに括っているのか、ちょっとお願いします。","respondent":"桑村人事課長","answer":"教育職員費は、その以外の教育委員会事務局に属している職員ということに区分けしているものでごす。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"戻るんですけれども、３７園で保育園の調理代行が完了したわけですけれども、調理員として働いていらした方たちはどういうふうな異動とか、どういったところに配属されているのでしょうか。","respondent":"桑村人事課長","answer":"基本は調理全体の退職がありますので、保育園で調理代行のあった人間がすべてほかのところに動いているわけでございませんけれども、調理としてお勤めの場合は学校へ基本的に動いてあります。そのほか用務等にも動いた職員もあります。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"今後小学校でも改築校、また中学校にも改築校がありまして、調理代行に移行するというお話は既にあるわけですが、退職不補充の方たちもいるかと思いますけれども、今後どのような予定をされているのかお伺いします。","respondent":"桑村人事課長","answer":"そういう意味で、退職不補充の方針は変えるつもりはございませんので、その中で必要なところへ配属していくというような考え方です。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"いろいろな職員の方も適材適所という、自分の技術を持った中で働いていかれることが最適だと思いますので、そういった適材適所で異動してほしいということと、こういった計画を当事者にもきちんと説明をした上で、広く透明な、迅速な情報公開をしながら、計画を進めていってほしいということを要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"私のほうからは、成果報告書の７ページの勤怠庶務管理システムに関連して、職員費に関連して質問をいたします。それから、事項別明細書４１ページ、午前中も質問が出ましたが、区営住宅使用料、区民住宅使用料等について質問をいたします。先に勤怠庶務管理システムのほうでありますが、これは簡単にお伺いいたします。導入の効果はどうあったかということが一つ。","respondent":"桑村人事課長","answer":"今回システムが入ったことによって、個々人がそれぞれのデータを申請する、またそれが課長等の決済が終われば、そのまま人事課のほうのシステムに回ってまいりますので、まず間違いなく入れればそのまま普通に計算できるということが１点あります。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"確認","question":"ここにある収入未済が、それぞれ内容はもう出ましたので、重ならないようにしますけれども、ただ、結果としてこれだけの金額が出ているということで確認したいのが、こういう状況に至ったときに、速やかな法的な対応をなさったらどうかということをずっと言い続けてきましたが、具体的にどのような法的な対応をされていらっしゃるかということをお聞かせください。","respondent":"阿部住宅課長","answer":"これにつきましても、宅建管理センターの方とこれからも連携をしながら、滞納が出ないような形で素早い対応をしていきたいというふうに思ってあります。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問","question":"では具体的にこれからどうしていくんですかということを最後にお伺いしたいんです。と言いますのは、民間の皆さんが大変苦労なさっているわけですね。そういうすばらしいノウハウを導入されたわけですから、それを今後さらにどういうふうに展開していくかということ。それから、収入未済にならないための努力はどうしていくかということをお伺いしましたので、もう少し答弁をいただければと思います。","respondent":"阿部住宅課長","answer":"今の件、確かに未済はあります。ただ、宅建管理センターの方と連携をしながらやってきた結果の一つとしまして、現年度分につきましては、おかげさまで収納率は９９.３％までいってあります。","id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問","question":"いろいろこれも勉強していきますと、法律の問題がありますね。非常に難しいことを質問しながら言うんですけれども、せっかく宅建管理センターというノウハウを導入したわけですから、もう一歩さらに突っ込んだ入居時の対応をしていきませんと、こういう問題は根本から解決しない可能性があると思われますので、研究についてはいかがでしょうか。答弁をお願いいたします。","respondent":"阿部住宅課長","answer":"私どもとしては、先ほど申し上げたとおり、行政の公平性の観点からなかなかそういうことはできませんけれども、入居なさった方の滞納がないように早め早めの対応を宅建管理センターと連携をしながらやっていくというふうに考えてあります。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"意見","question":"これは２０００年の検討でございまして、その後の具体的な検討状況をお聞かせいただければと考えています。それは低廉な家賃で入れるということがあるわけですけれども、逆に、こういう根本的なところに手を付けていきませんと、この問題は解決できないと私たちは思っておりますので、東京構想２０００に関するその後の検討、それから品川区の内部の対応方をお聞かせくださればと思います。","respondent":"阿部住宅課長","answer":"私どもとすれば、国の法改正の方向がどういう形で出るのか、その辺を注視していきたいというふうに思ってあります。区民住宅の件ですけれども、確かに委員おっしゃるとおり、その辺を考えていかないとなかなか対応が難しい場合もあります。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、例えば減価償却費とか、支払い利息、単にそういうものがある。となれば、そういう最も根本の公営住宅のあり方とか、家賃設定のあり方とか、東京構想２０００についてはまだ先かもしれませんけれども、公営住宅の本来のあり方というものを見直す時期にかかっていると考えていますので、そのことについての大きな将来構想、検討の方向性を教えていただければと考えていますが、いかがでしょうか。","respondent":"阿部住宅課長","answer":"先ほど申し上げましたとおり、法律も大きく変わろうというふうな状況ですので、それを含めまして、私どもとして公営住宅、区営住宅、区民住宅を含めまして、どういうふうな住宅政策をしていくのかというのが大事だというふうに思ってありますので。","id":"exchange-057"},{"speaker":"山村委員","kind":"質問・要望","question":"私のほうからは、事項別明細書の４０ページ、土木使用料、自転車駐車場使用料と、産業経済使用料の賃貸工場アパート使用料および成果報告書１７０ページ、職員費について質問をします。職員費から質問をします。退職手当１４０人とのことですが、新規採用が今年は何人いらっしゃったのかということと、中途採用や、再任用職員が何人いらっしゃったのか教えていただきたいと思います。","respondent":"桑村人事課長","answer":"平成１６年度の新規採用ですけれども、４８人です。途中採用は今のところございません。平成１５年度が２７人です。これはすべて４月の採用です。それから、再任用職員ですけれども、平成１５年度が５６人です。","id":"exchange-058"},{"speaker":"山村委員","kind":"質問・要望","question":"中途採用は今年度０人ということですが、中途採用をもしされた場合の職員の給与や昇進というのは、品川区においては正規職員との差があるのか、ないのかというのを教えていただきたいと思います。","respondent":"桑村人事課長","answer":"ただし、昇任に必要な期間の２分の１までというふうに見てありますので、非常に年齢の高い職員が採用になった場合で、非常に経験が多かったというような場合については、一定の、いわゆる新規で入った者についての若干昇進の遅れがあるというふうに思ってあります。","id":"exchange-059"},{"speaker":"山村委員","kind":"質問・要望","question":"民間活力の導入ということを考えると、今、経験者採用ということをおっしゃっておりましたが、そういうのをもっと枠を拡大すべきじゃないかと私は思うんですが、経験者採用、現状では３５歳ぐらいまでということでよろしいんでしょうか。その年齢をもうちょっと引き上げるようなことは品川区独自でやれるのかどうか教えていただきたいと思います。","respondent":"桑村人事課長","answer":"その意味では、相当の努力が必要になってくるんじゃないかというふうに思ってあります。今回初めて私どもについても１人採ろうと思ってありますので、その効果を見て、また引き続き進めてまいりたいというふうに思ってあります。","id":"exchange-060"},{"speaker":"山村委員","kind":"質問・要望","question":"先ほど質問をした中で、年齢の引き上げが品川区独自でできるのかどうか、お答えいただいていないので、教えていただきたいと思います。","respondent":"桑村人事課長","answer":"私ども事務系の職員、あるいは技術系の職員は、特別区の人事委員会がやっている試験の中でやってあります。品川区として一定のそういった職員がどの程度の年齢で必要かというようなことの話をしていく必要があるんだろうというふうに思ってあります。","id":"exchange-061"},{"speaker":"山村委員","kind":"質問・要望","question":"千代田区は新人の採用を３年間ほどされていないと。言い方が分かりにくいんですが、即戦力を多く入れるのか、それとも新人から育てたほうがいいのか、そこら辺はどのように考えていらっしゃるのか、教えていただきたいと思います。","respondent":"桑村人事課長","answer":"これは正直言って、区によっていろいろな考え方があろうかと思います。私どものほうは、先ほど退職の人数と採用の人数を申し上げたとおり、１００人ぐらい人数が落ちてあります。","id":"exchange-062"},{"speaker":"山村委員","kind":"質問・要望","question":"職員のことでお聞きしたいんですが、現在の全職員数が大体２,８９５人ぐらいたと思うんですが、今後ＩＴ化というのを進められていると思うんですが、このＩＴ化によって職員数というのは減らせるものなのか、それとも職員数は現行のままＩＴ化だけされて、ほかの部署に職員を回すおつもりなのか、そこら辺のことを教えていただきたいと思います。","respondent":"桑村人事課長","answer":"その意味では、これによっての一定の効果というのは職員数の減になるというふうに私どもは考えているものです。","id":"exchange-063"},{"speaker":"山村委員","kind":"質問","question":"事項別明細書の４０ページの土木使用料の自転車駐車場使用料のことで聞かせていただきますが、先ほど駐輪場は１５カ所あるというふうにお伺いしたんですけれども、監視カメラが設置されているのは何カ所ぐらいあるのか教えていただけますでしょうか。","respondent":"山口交通安全担当課長","answer":"現在、整備センターのほうから引き継ぎました駐輪場をリニューアルしまして、６カ所等で１１月１日から防犯カメラ等を設置する予定です。","id":"exchange-064"},{"speaker":"山村委員","kind":"質問","question":"現在６カ所ということですが、今後は全箇所監視カメラを付けるおつもりなのか、教えていただければと思います。","respondent":"山口交通安全担当課長","answer":"大変失礼しました。現在１５カ所全部設置しております。","id":"exchange-065"},{"speaker":"山村委員","kind":"質問・要望","question":"１５カ所全部付いているということで、私は、付いていないところがあるかと思って質問を考えていたものですから、それで終わってしまいますので、次にいかせていただきたいと思います。","respondent":"日下部産業振興課長","answer":"全体で住宅工場の組み合わせで８セットですが、残念ながら、今年に入りまして、１戸退去ということで、現在７戸の入居という状況です。","id":"exchange-066"},{"speaker":"山村委員","kind":"質問・要望","question":"収入未済額が６６１万４,３００円ですが、今７戸というと、ほとんどが払われていないのか、ちょっとわからないんですけれども、収入未済額の内訳を教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"収入未済額６６０万円余ありますけれども、この内訳です。実はこのうち約５３０万円ほどにつきましては、平成４年から平成１４年度までの間の収入未済の滞納があった金額です。それから、平成１5年度に入りまして一部滞納が出てまいりました。","id":"exchange-067"},{"speaker":"山村委員","kind":"質問・要望","question":"収入未済額を今後どのように解決していくのか、教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"したがいまして、平成１５年度分の未収分につきましては２４万円ほどですので、これにつきましても引き続き納入に努めていきたい、このように考えております。","id":"exchange-068"},{"speaker":"山村委員","kind":"質問・要望","question":"最近は中小企業のほうに特に景気の後退のあおりがひどく当たっているようですが、賃貸工場ですとか、アパートというもの自体は、今後は続けて発展させていくのか、それとも消滅させていくのか、そこら辺のことを教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"したがいまして、そういった意味では、当初の平成４年、十数年前と大分状況が変わってきておりますので、そういった点を踏まえて、今の工場アパートについては少なくとも継続をする必要があるというふうには考えておりますが、今後それを発展させるとか。","id":"exchange-069"},{"speaker":"山村委員","kind":"質問・要望","question":"今後はこのような賃貸工場アパートというものはあり得ないということで理解をします。これは区営みたいな感じでやられていたのかなと思うんですが、その分の補助を別に中小企業に回すというか、そういうようなこともできるかとは思うんですが、賃貸工場アパートに代わるような施策というか、何か考えていらっしゃったら教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"この工場アパートにつきましては、設置をしまして、今賃労収入もしっかり見込んで運営をしているわけでありますけれども、特に現時点でこれについての特別な補助という形はとってございません。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"この職員費の中を見ますと、９の退職手当の動向なんですが、昨年度、平成１４年度は１２２人、平成１５年が１４０人という形で出ているんですが、平成１４年度と比べますと、４億円弱でしょうか、増えているわけですが、職員費全体の割合にしてみても、約１割ぐらいの金額が占めているという現状がありますが、今後の推移がどういうふうに変化していくのかということ。","respondent":"桑村人事課長","answer":"本年度の定年退職予定者が７６人、その次が５３人、その次が８７人、その後がいわゆる団塊の世代が入ってまいりまして、いわゆる４年後からは１４４人、１１７人、１２７人、１２９人と、１２０人ぐらい、特に４年後は１４０人という、定年退職の数が非常に多くなってまいります。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"ただ、事業の内容によっては、当然人が必要になってくる部分もありますので、そこら辺の考え方、長期にわたっての考え方と、それから事業に対する適切な人材の数、配置というのをどいうふうに考えられているのか、お考えをお聞きしたいと思います。","respondent":"桑村人事課長","answer":"この時点で退職手当が相当出るというのは見込んですので、そういう意味では財政当局のほうできちっとその形で、その中で事業をどう展開していくかというようなことで考えているです。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"確かに時代の流れによっていろいろな手法を使い、民間活力を使うということはそれは当然やっていく必要があるかと思いますけれども、しかしながら、今まで培ってきたものを後世にどういうふうに伝えていって、品川区の今後の発展に役立てていくか、途中で切れてしまうのが一番悪いことではないかなというふうに思いますので、今までのやってきたこと、反省点も多いかと思いますが。","respondent":"桑村人事課長","answer":"その意味では、一たんそういったものの技術なり、あるいは経験なりが途切れるということになりますと、なかなかそれを回復するには相当時間がかかります。その意味では、それをうまく仕事の中で工夫しながら、各仕事、あるいは職場の中で進めていきたいと思ってあります。","id":"exchange-073"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと、財産収入も多少減少しているというようなこともありまして、あと自主財源にしては、使用料及び手数料が２億円増加したということは、受益者負担を高めたということで、効果があったというふうに思うんですが、あくまでも依存財源が増えてくると、先ほども質問がありましたけれども、特別区債が２５億円増えたということで、先ほどの話ですと、５０億円ぐらいまでは大丈夫だよということなので。","respondent":"市岡企画財政課長","answer":"そういう意味では、自主財源のほうが各地方公共団体の自助努力によって収入の確保が図れる財源ですので、財政自主権の確立にとってはこれが多いほうが望ましいということは確かなんですが、私どもの場合、例えば財調の交付金などというのは、先ほど来も議論が出ておりますが。","id":"exchange-074"},{"speaker":"築舘委員","kind":"質問・要望","question":"財産収入のところにおいて、財政調整基金という、利子と減債基金利子、それから、公共施設の整備基金利子、それとあと、義務教育の施設整備基金利子というのは取り崩すことができるということで、あとの基金の場合は取り崩すことができないで、利子だけがこういった形で運用されていくということですけれども、今は銀行に預けていても利子が多くないということもありますし、その辺のことの預金、国債。","respondent":"小野副収入役","answer":"基金の運用につきましては、収入役室のほうでやっているわけですけれども、この間ペイオフとかございまして、今までのように定期預金等では運用できないということもございまして、できるだけ分散管理をしていくということもございまして、ここのところ元本保証である国債。","id":"exchange-075"},{"speaker":"築舘委員","kind":"意見","question":"寄附金のところに予算現額では９３８万円ぐらいしかないんですけれども、決算額で２,８７１万４,４２５円ということで、予期せぬ寄附金があったのではないかと思うんですが、そこに関してはどういうふうになっているかお聞かせください。","respondent":"市岡企画財政課長","answer":"それらのうち取り崩して使えるものについても実施計画の中で大きな事業を計画しておりますので、それに合わせて、その時期までは国債で運用益をしっかり確保して、それ以外のものについては計画の中で行き違いのないように安全かつ確実に運用するということで。","id":"exchange-076"},{"speaker":"築舘委員","kind":"質問","question":"基金の積み立ての運用の中で社会福祉基金というのがあって、その場合には利子を運用していくわけですけれども、それを崩すということは絶対ないわけですか。先ほど言ったように、取り崩すのは、そういうふうに大きな事業があったときに崩すということですが、社会福祉基金などはある程度積み立てでの運用だから、取り崩す場合の判断というのはどういうふうなときにするんですか。本来は崩せないんだけれども。","respondent":"市岡企画財政課長","answer":"現在低金利ですので、今はあまり処分とか、取り崩すということはもちろん考えていないわけですが、逆に、こういう果実運用型の基金についても、これからの金利情勢によっては、また運用益をもって十分な仕事ができる時代がくる可能性もありますので。","id":"exchange-077"},{"speaker":"築舘委員","kind":"質問","question":"基金はなるべく崩さないで、多いほうがいいということですけれども、ただ単に基金を積み立てるだけでは、最近は経済も大変でありますし、運用をしっかり考えていくということで、この寄附金がたくさん集まるような方策を何か考えていただいたほうがいいんじゃないかなというふうにちょっと思ったものですから、その話をいたしまして、終わりといたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"中島委員","kind":"質問","question":"私は、特別区税、使用料、都支出金、時間があれば、素朴な質問ですが、財産収入についてお伺いいたします。今朝からの質問の中で、特別区税が０.９％減ったという、これも私も疑問に思っていて、質問をしようかなと思っていたんですが、前年度の会計によるということで、納得したわけです。私は、議会においてはすべての委員会を禁煙にしてほしいと思っているから聞くわけではありません。","respondent":"太田税務課長","answer":"これで１,０００本につきの割合ですが、２,６６８円が３０９円上がって、２,９７７円と、こういう改訂がございましたので、本数は減っておりますけれども、その分の改訂率でいきますと、約１１％になりますので、結果として調定額が上がったです。","id":"exchange-079"},{"speaker":"中島委員","kind":"質問","question":"本数が減ったということで安心しました。続きまして、使用料の自転車駐車場ですが、今はまだたしか大井町の駐輪場が工事中ということで、路上に駐輪をさせていただいているわけですが、聞くところによると、外に駐輪するようになってから、非常に利用者が増えたということを伺っているんですが、これは事実でしょうか。","respondent":"山口交通安全担当課長","answer":"現在大井町につきましてはリニューアル中ですが、前の立会道路に臨時の駐車場を設けまして、皆さんに当日利用を含めて、利用するように働きかけています。それについても、現状のほうは、大体の概数ですが、若干平行線をたどっているような状況と認識をしております。","id":"exchange-080"},{"speaker":"中島委員","kind":"質問","question":"私が聞くところによると、定期利用者は減って、逆に一般の臨時の利用者が増えたというふうに伺っていたんですが、それは違うということなんでしょうか。","respondent":"山口交通安全担当課長","answer":"駐輪場の利用の関係については、現在のところも増加等は見られませんので、現状は放置状況は結構見られますけれども、当日利用のほうは、委員のおっしゃったとおりです。","id":"exchange-081"},{"speaker":"中島委員","kind":"質問","question":"私などは外の駐輪場のほうが非常に使いやすいなということが、確かに室内のほうが安全であるし、雨が降ったときなどはぬれなくていいわけですけれども、外もある程度は効用があるのかなというふうに思っていたものですから、それでちょっと質問をしました。この中で緊急地域雇用特別交付金、それから、生活情報体制整備補助金、これはどういうものなのか教えてください。","respondent":"長田区民課長、榎本行財政改革担当課長","answer":"９４ページの生活情報体制整備補助金ですけれども、これにつきましては、消費者センターのほうで消費者相談ということでいろいろな相談を受けてあります。緊急地域雇用の補助金につきましては、国の制度ということですけれども、東京都経由で１０分の１０で品川区へくるという形になっております。","id":"exchange-082"},{"speaker":"中島委員","kind":"質問","question":"そういう中で、起業というものが光が当たってきていると思うんですが、たしか品川区でも女性起業の会合というものを持って、私もちょっとのぞかしていただいたんですが、今までにない新たな視点というんでしょうか、そうした社会に潤いをもたらすような起業が大分出てきていると思うんですが、こういった起業に対する補助金とか、そういったものというのはどこで出されるんでしょうか。","respondent":"日下部産業振興課長","answer":"実際に女性の起業ということで、具体的にこれをいざ実現するということになりますと、開業資金、実際に中小企業を対象にしました融資制度がありますけれども、その中の開業資金の貸し付けと、このような形で対応をできるような仕組みになっております。","id":"exchange-083"},{"speaker":"中島委員","kind":"質問","question":"開業資金というのはどのぐらいまで借りることができるんでしょうか。","respondent":"日下部産業振興課長","answer":"限度額は１,０００万円ということで設定をしています。","id":"exchange-084"},{"speaker":"中島委員","kind":"質問","question":"１,０００万円までということで、これは補助金から出る資金でしょうか。","respondent":"日下部産業振興課長","answer":"今申し上げました資金の制度は直接的な補助金ではございませんで、実際の開業に係わる資金の融資について金融機関にあっ旋をするという仕組みです。","id":"exchange-085"},{"speaker":"中島委員","kind":"質問・要望","question":"今１,０００万円とお伺いしたんですが、私が知る限りでは、今起業というのはそんなにお金をかけなくても、例えばマンションの一室でも企業を興している方がいらっしゃるわけです。非常にユニークにインターネットを使ったり、いろいろな形で行っております。","respondent":"日下部産業振興課長","answer":"西大井の創業支援センターを昨年９月に開設をいたしました。こちらは２種類ありますけれども、創業支援ブースということで、全体の９m2程度のブースを１０個ほど設けてありますが、例えばそちらの入居とか、そういう形での支援もさせていただいているという状況です。","id":"exchange-086"},{"speaker":"中島委員","kind":"質問","question":"起業家同士が、コラボレーションというんでしょうか、共同でいろいろお互いに啓発し合いながら企業を発展させていくといった面、また新たな起業家を育てていくという、そうしたシステムも必要ではないかと思うんですが、その点についてお考えをお聞かせください。","respondent":"日下部産業振興課長","answer":"今後その辺の具体的な中身についてはまたいろいろ検討をしてまいりますけれども、最近特に、例えばコミュニティービジネスであるとか、いろいろ多様な形での創業・起業、これはＮＰＯ中心のケースが多いんですけれども、そういうものに対するバックアップとか。","id":"exchange-087"},{"speaker":"中島委員","kind":"質問・要望","question":"今の社会にあって今後光をあてていかなければいけない部分かなと考えていますので、ぜひ品川区としても再度いろいろ構想を練っていただきたいなと、これは要望しておきます。最後に素朴な質問をします。財産収入の中で物品の売払収入というのがあります。不用品を売り払った代金ということで記載されているんですが、これはどういったものをお売りになったのかだけ、単純な質問ですが、お願いします。","respondent":"小野副収入役","answer":"いずれも使用に耐えなくなったということで、売り払って収益を得るというものです。","id":"exchange-088"},{"speaker":"中島委員","kind":"質問","question":"そういうものが売れるんですね。買った方はどういうことに使うんでしょうかね。","respondent":"小野副収入役","answer":"不用フィルムからは水銀が取れるということで、ナンバープレート等は建築資材とかにリサイクルをしていくというようなことです。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、委員会の資料が委員には配られますけれども、ホームページの中に資料がないと、議事録の中身も、説明している中身というのもよくわからないので、請願についても、事務局の方が朗読をしてくださっているんですけれども、それがカットされているので、その中身もわからないという状況になっているんですけれども。","respondent":"福田区議会事務局長","answer":"４点にわたるご質問をいただきました。いずれも、議会の内部の意思をどういうふうに形成するか、こういう問題が先行するだろうと思います。したがいまして、それを所管いたします議会運営委員会でしかるべき時期にお話があるのが妥当だろうと、かように考えます。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明を聞いていても、資料がなければわからないし、区政への区民参加というふうなことを呼びかけているわけですから、せっかく休みをとって傍聴に来たりとか、関心のある方が傍聴に見えているので、そういう区民を大事にすべきではないかと思うんですが、傍聴者にぜひ資料ということでお願いしたいと思うんですが、いかがでしょうか。","respondent":"福田区議会事務局長","answer":"先ほどのご質問のものと性格的に同じかと思いますので、先ほど同様、まずは議会の内部意思をどう形成するかという問題だろうと思います。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どちらにしても、より区民に対して開かれた区政にしていくかというところでの質問というふうなことでしていますので、区議会事務局としてこの問題についてどう考えるかということをお聞かせいただきたいというふうに思います。それと、例えば品川区の中でも介護保険の制度推進委員会では資料が出されているんです。","respondent":"福田区議会事務局長","answer":"議会の事務局は議長の命によって仕事をしております。したがいまして、議会意思が形成されない問題につきまして、独自の見解を持つものではございません。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"議会運営委員会を通さなくても簡単に改善できるものもありますので、そういうふうなところはぜひ前向きにご検討いただいて、分かりやすいホームページ、このホームページがつくられたところでも、一つひとつ議会の事務局のほうとしても提案をされていったという部分もあると思いますので、ぜひご検討いただきたいと思います。次に、生活保護に移ります。もう一つ、生活保護の受けている世帯が年々増えている。","respondent":"志村生活福祉課長","answer":"ですので、この辺につきましては、私どものほうでもなるべく自立助成ということに力を入れてまいりますけれども、現在のこうした傾向は当分続くのではないかなと、このように考えてあります。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、今年は老齢加算も３年間で廃止ということで、今年半分ぐらい減らされました。こういう動きになっておりますけれども、これに対して品川区としてどういうふうに捉えて、どう対応をされようとしているのかを一つお聞きしたいと思います。それと、もう一つは、１年間に新しく生活保護を受けられる方が何人ぐらいいるのか、この５年間ぐらいそれぞれ数を教えていただけないでしょうか。","respondent":"志村生活福祉課長","answer":"ご質問にお答えいたします。老齢加算、母子加算等々の改定につきまして検討をしているというお話は聞いてあります。私どもで毎月福祉事務所長会という会が開かれてあります。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"動向を見て、どう対応しようとしているのか決まっていないということですが、そういう悠長な状況でいいんでしょうかというふうなことを私は言いたいんです。そういうところでは、ぜひ今言った、国の負担割合を減らすな、それから、母子加算を取るなと、こういうふうなことを機会あるごとに主張していただきたいと思うんですけれども、いかがでしょうか。","respondent":"志村生活福祉課長","answer":"ですので、特別区区長会のほうでも平成１７年度の国の施策、予算に関する要望等にも負担の見直しについての要望を出しています。今後もこうした状況を把握しながら進めていきたいと、かように考えてあります。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つお聞きしたいのは、生活保護制度の区民への周知徹底についてどうしているかということでお聞きしたいんですけれども、昨年の自殺者が３万４,４２７人ということで、６年連続して３万人を超えたという、これは私たちにとっても衝撃をもって受け止められていますけれども、１日約１００人が自ら命を絶っているという、こういう異常な状況になっています。","respondent":"志村生活福祉課長","answer":"ですので、こうした皆様方の力もお借りしながらＰＲをしていきたい、かように考えてあります。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"広報活動を徹底的にやっていただきたいということで、ここにも意見が出されていまして、入りやすい制度にするようにというふうなことで、かなり意見も出されているところですので、品川区としてもそういうふうなところでぜひご検討いただいて、対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"須貝委員","kind":"意見","question":"今回は議会費と、基金と財産の運用についてお聞かせください。議会費のほうで、速記ですけれども、明治２３年以来続いていました国会の速記のうち、参議院の速記が廃止される方向で、速記廃止後は録音などを使って議事録を作成する方向で現在進んでいるという新聞報道がなされました。現在録音技術その他どんどん進んできておると思うんですけれども、その辺のお考えをお聞かせください。","respondent":"福田区議会事務局長","answer":"その際に自民党の委員から同趣旨のご発言がございまして、事務局としてどういうメリット、デメリットが考えられるのかということを既に検討に入っておるところです。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"これをどのように安全に分散されているんでしょうか。大体１行あたりどれぐらいの金額を預託しているんでしょうか。Ａ行とＢ行がくっつけば、今度は金融機関が１つということになりますね。そうすると、それなりにリスクということも十分考えなければいけないと思うんですけれども、その辺のご見解をお聞かせください。","respondent":"小野副収入役","answer":"品川区では平成１４年４月からペイオフの一部解禁に向けまして、公金の管理運用方針を策定いたしまして、各基金の管理運用についても、この方針と基準によって管理をしています。安全第一ということで、その上で効率性を求めるということで現在も運用しています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"政務調査費についてお伺いいたします。新聞報道によりますと、同区議団は平成１６年１月頃と書いてありますが、内部調査の結果、誤解を招きかねない不相当な支出だったとして、政務調査費の一部を区に返却したとありますが、この返却ですが、いつ、幾ら返却したのか、また、どのような形で返却されたのか、それをお聞かせください。","respondent":"福田区議会事務局長","answer":"いつでありますが、今年の１月１３日であります。幾らでありますが、３１万３,２８６円です。どのようにでありますけれども、当該会派の代表者の方から、政務調査費の交付に関する条例の第９条第１項に基づいて、その一部を返還する旨の通知が品川区にございました。","id":"exchange-100"},{"speaker":"須貝委員","kind":"確認","question":"今、確認をなさったということですけれども、領収書等を発行したんでしょうか。その辺をちょっとお聞かせください。","respondent":"福田区議会事務局長","answer":"領収書を発行しております。","id":"exchange-101"},{"speaker":"須貝委員","kind":"確認","question":"領収書等を発行して、政務調査費ということで、品川区では確認して受け取ったということでよろしいですか。","respondent":"福田区議会事務局長","answer":"政務調査費の返還です。第９条第１項は、いわゆる目的外使用でございましたので、政務調査費として交付されたものではありますけれども、その政務調査費として返還を受けたものではございません。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問","question":"我々所得税や法人税の場合には、申告に間違いがあったときに、その年度の修正申告等の処理をいたしますけれども、事務局のほうでは政務調査費に対して、議会費の修正申告というのはどこにもやっていないわけですね。それはしなくてよいんでしょうか。返還したということならば、本来その年度のそのときの政務調査費の領収書と差し替えという作業はしなくてよろしいんでしょうか。","respondent":"福田区議会事務局長","answer":"平成１３年度の、いわゆる私どもの用語でありますが、確定額、これについては変更修正をしております。それから、当該領収書でありますが、これは一たん私どもの行政情報になったものですので、条例の規程上議長のもとで５年間保存する、かような規程があります。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問","question":"普通は、例えば品川区のほうの決算報告書もそうですけれども、いろいろ変更があったら、変更というきちんとした事務処理がなされると思うんですけれども、それはしなくていいということですか。","respondent":"福田区議会事務局長","answer":"平成１３年度分が平成１５年度に変更されました。したがいまして、平成１５年度の決算審査の事項別明細書の中の雑入でそれを対応をしています。","id":"exchange-104"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々のほうにきちんとした、いつ、どこで、何をどのように処理をしたということが明確でなかった。議会運営委員会で話したのか、どこで話したのかちょっとわからないんですけれども、議会費として我々も携わっているわけですから、きちんとした書類ということで、今後処理していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"石田委員","kind":"質問・要望","question":"専門技術的な見地から調査等う行うものと、公正中立の立場から審議等を行うもの、または住民などの意思を反映するためのもの、こういうふうにいろいろ附属機関が分かれていくと思いますが、今言った４つの部分で、この４つの附属機関はどのような位置づけ、もちろん目的とかは分かっておりますが、その３つの仕分けの中でどういう形で位置づけをして、委員会等を捉えているのかというのを教えていただきたい。","respondent":"榎本行財政改革担当課長、中島指導課長","answer":"３つ目の品川区次世代育成支援対策推進協議会につきましては、地域行動計画をつくるために置いたという形ですけれども、こちらは同じく子育てとか、次世代育成についての専門家の方と、あと公募委員という形で構成しておりますので。それぞれの学校におきましては、この外部評価者の方からいただいた意見をもとに、次年度にそれぞれの学校での取り組みを具体的に表明していくという形での成果基盤型の学校づくりを目指すという形で機能しているものです。","id":"exchange-106"},{"speaker":"石田委員","kind":"質問・要望","question":"これを区長には聞かなくてもいいですけれども、区政アドバイザーの部分は、これはこれで区長が独自性を発揮するためにという目的の中で、ご意見をいただくということでありますが、これは仕分けをしてあるものですと、資料を見ると、懇談会形式のものでも、それは非常に意味があるんだという、諮問機関的にそれは区の今度いろいろなものをやるにあたっては、そういう人から意見を聞くんだということで。","respondent":"榎本行財政改革担当課長、中島指導課長","answer":"その中でのいろいろ議論をされておりますけれども、まず、区政の概要をきちんと捉えていただくということで、各有識者の方に今まで品川区がどういう歩みをしてきたか、ここ三。それぞれの学校におきましては、年に３回あります外部評価者委員会、そして２回あります外部評価に関する協議会、こういったような定例の会議、また通常の外部評価者の方が学校に見えられたときの対応等。","id":"exchange-107"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほども言いましたように、しばしば執行機関の責任逃れというところに思われないように、いい方向で動いていただきたいなと思います。成果報告書の５ページの下から５行目ですけれども、先ほどご説明いただいた、外部評価委員会において答申をいただきましてという話があったんだけれども、私が読む限り、これはどういうふうに見ても、「報告書『政策評価のしくみづくりと試行結果について』を作成しました。","respondent":"榎本行財政改革担当課長","answer":"ここの部分につきましては、かなり限られた字数の中でどういうふうに表現するかということで、そのような形になりましたけれども、今後ともそういうような観点から気を付けていきたいというふうに思っております。","id":"exchange-108"},{"speaker":"山路委員","kind":"質問","question":"委託といいますか、ほかの機関で検査されている。一つは、その理由について。もう１点は、水質検査の中で水道の水とか、井水、川の水、工場排水とか、いろいろな種類の検体に入れた水を検査をやられると思うんですけれども、この中で水質基準を超えている水質検査についてどれぐらいあるのか、また、特に重金属とか、人体に影響のあるものはあったのかどうか、その辺についてお伺いをいたします。","respondent":"島袋品川区保健所衛生課長","answer":"平成１６年度から保健所で受けつけていない理由ですけれども、水道法が少し変わりまして、検査項目等につきまして、有機物の関係、過マンガン酸カリウムを測るのがあるんですけれども、この測り方が、従来のやり方ではなくて、新しいＴＯＣという。","id":"exchange-109"},{"speaker":"山路委員","kind":"質問・要望","question":"来年度からここに載らないようになるので、今年度お伺いしたわけです。ここはいいんですけれども、１０ｔ以下の検査の義務のない、設置者が管理しなければいけない、この辺に対して、区民の方からどうしたらいいかという質問もあります。井水とか、どうなっているかということもありますが、この辺の義務のない水質検査については今後どのようになっていくのか教えていただきたいと思います。","respondent":"島袋品川区保健所衛生課長","answer":"今年ですけれども、水道事業者であります東京都水道局のほうで増圧直結というのをやっておりまして、今までは２階ぐらいしかできなかったんですけれども、受水槽を通さずに増圧ポンプを使いまして、直結して、３階とか４階に。","id":"exchange-110"},{"speaker":"山路委員","kind":"質問・要望","question":"大分普及率も上がってきているということは伺っておりますが、パンフレットを配ると同時に、そのまま放置して、水が悪い、水が悪いということで言っている方も、細かいことを知らない方も区民の中にはいらっしゃいますので、パンフレットと同時に、意識啓発も欠かさず徹底して、水の事故がないように、くれぐれもよろしくお願い申し上げます。","respondent":"早津高齢福祉課長","answer":"福祉施策包括補助金ですが、平成１５年度の実績が１億５,５００万円ですが、これが上限というわけではございませんで、さらに補助金の内容にふさわしいものがあれば追加することは可能です。","id":"exchange-111"},{"speaker":"山路委員","kind":"質問","question":"福祉という規制の枠だけではなく、いろいろなものに使えると判断してよろしいでしょうか。","respondent":"早津高齢福祉課長","answer":"福祉という冠がかぶっておりますので、広い意味での福祉施策です。この補助金は歴史のある補助金でございまして、そういう意味では障害者や、子育て家庭、児童等を対象としたというようなものを中心にしている補助金という歴史があります。","id":"exchange-112"},{"speaker":"山路委員","kind":"質問・要望","question":"午前中若林委員のほうから、緊急地域雇用特別事業ということで、雇用もかなりの方をやっていただいて、これがなくなるんじゃないか、その後続けたい事業もありましたけれども、この辺の予算の配分、これを福祉包括施策補助金と整備させていったらどうかと思ったんですが、これはどういう違いがあるものでしょうか、説明をしていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"人件費そのものというのが、福祉施策の包括補助金のソフト部分のほうになじむかどうかは、東京都側とも折衝する必要があるかと思いますが、従来からのもので比較をしてみますと、ストレートなものは難しいのではないかなというような感触は持っております。","id":"exchange-113"},{"speaker":"山路委員","kind":"質問","question":"雇用ということでは非常に難しいんじゃないかなと思っておりましたけれども、品川区独自の福祉的施策を広げていくという面では、これからもこの福祉施策包括補助金というのは有効に利用されていくんじゃないかと思います。先ほどすまいるスクールの活用と言いましたけれども、ほかにどういうものをやられているかちょっとご説明をしていただけますでしょうか。","respondent":"早津高齢福祉課長","answer":"そのほか事業項目では２０項目ぐらいありそうですが、この事業は区市町村の主体的な選択を生かしていこうという、東京都の補助制度の改正の中で位置づけられておりまして、先ほども申し上げましたように。","id":"exchange-114"},{"speaker":"山路委員","kind":"質問・要望","question":"来年の予算に関しましては、三位一体改革の問題、補助金削減の問題とか、いろいろな問題が今日議論されましたけれども、子育て支援、あるいは品川区独自で今後の施策にこれを生かしていただきたいことを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"私は、職員費に関連して伺います。山村委員、西本委員が、近年の雇用状況、採用、そして退職者の状況等を質問されまして、ある程度基礎的な数字は伺ったところですけれども、品川区は１０年近く１桁採用、ゼロ採用等を取り入れてきておりまして、そのことに関するいろいろな問題が起きてくるというのは、前にも指摘したとおりですけれども、ここ四、五十人採用が復活しつつある。","respondent":"桑村人事課長","answer":"これは一つは、これまでは再雇用ということで、定年は基本的には６０歳なわけですけれども、それについても、その後につきましては、退職職員の活用という意味で、非常勤という形で採用してまいりました。ところが、年金制度等につきましても、徐々に６５歳が基準になってくる。","id":"exchange-116"},{"speaker":"塚本委員","kind":"質問","question":"ほかのところは各事業のところに落とし込んであるということでしたけれども、そういう現場の仕事が一塊になってきた、コスト意識もだんだん芽生えてきたということになると、そこでどれだけの人件費を使っているかということが分かりやすくなったほうがいい時代にきているのではないかと思うんですけれども、その辺についてどうお考えになるか、２点お伺いします。","respondent":"桑村人事課長、市岡企画財政課長","answer":"もう一つは、そういった民間の方の活用という意味では、先ほどからちょっとご説明がございましたけれども、一定附属機関の委員という考え方もありますでしょう。ただし、現在は予算、決算を見てもお分かりのとおり、職員費という形で一括計上をしてございまして、これはこれで一覧できるというメリットはあるわけですが、やはり事業部ごとの、経営の基本はヒト・モノ・カネですから。","id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"再任用のことですが、私、団塊の世代の一番頭数の多いところですけれども、先ほど六、七年の間に七、八十人とか、１４０人ぐらいの退職者の数が、およそ２倍の幅であるということですから、そして、再任用のほうも、始めて大分行き渡ってきて、行き場所が詰まっているのではないかというような、おおよその見当をつけるんですけれども、倍の変化の幅と、それから現状の雇用の情勢を踏まえて。","respondent":"桑村人事課長","answer":"退職の非常に多く出てくるところがある。一つは、再任用に関しては、これは再任用職員の活用というのはまた別途考えなければいけませんけれども、いわゆる常勤の職員との代替みたいなことをある程度考えざるを得ないのかなというのが１点あります。","id":"exchange-118"},{"speaker":"沢田委員","kind":"質問","question":"初めに、多少ダブルことになるかもしれませんけれども、改めて三位一体改革の全体像と、税源移譲の問題がかなり大きな問題なんですけれども、税源移譲でどういう立場を小泉内閣はとろうとしているのか、少し詳しく教えていただければと思います。もちろんまだこれは完結していないことを承知で聞かしていただいているつもりですので、分かる範囲で結構ですので、よろしくお願いしたいと思います。","respondent":"市岡企画財政課長","answer":"平成１６年度につきましては、これまで予算特別委員会等でもご審議いただきましたとおり、既に国庫補助負担金の１億円の削減、それから、税源移譲は所得譲与税など約６,５００万円の移譲ということで、もうここで大分開きが出ているわけですが、この後。","id":"exchange-119"},{"speaker":"沢田委員","kind":"質問","question":"賛成いたしかねるというふうにとっていいかどうかですね。例えば税源移譲が１００％されれば、これはいいとするのかどうなのかということの見解を伺いたいと思います。地方自治というけれども、こういうふうになっちゃったら地方自治の自治権を広げるどころじゃないし、住民のほうは大変なことに直面をするというふうに思うんですけれども、その辺に対していかがお考えかお聞かせ願いたいと思います。","respondent":"市岡企画財政課長","answer":"このことについても、三位一体改革について協議の場をきちんと設けるということが、地方６団体の申し入れのまず冒頭にきているぐらいですから、ご指摘いただいたような点については、これからいろいろな議論が行われる中で意見交換が行われるというふうに考えてあります。","id":"exchange-120"},{"speaker":"沢田委員","kind":"意見","question":"実は議会の側にも地方６団体から、今度の三位一体改革について、６団体が申し入れた内容について、国に向けて各議会で意見書を出してほしいというのがきているんですが、私はその６団体の文書を読みまして、税源移譲というのなら、一体なぜ３兆円の補助金を６団体のほうから削る案を出せというのに乗っかっちゃったのかと、大変理解できない、弱点を持っている。どんどん減らしていく。","respondent":"市岡企画財政課長","answer":"特別なコメントはこの段階ではないんですけれども、今地方交付税の問題、あるいは義務教育費の国庫負担の問題、生活保護費の問題がありましたけれども、問題の状況が全国的に地方公共団体一律ではないところが問題の一番複雑なところでして。","id":"exchange-121"},{"speaker":"沢田委員","kind":"質問・要望","question":"議会で言えば、市議会議長会で全国組織の中に入ってやっていますけれども、区長会として意見を上げたという話が今あったんですが、折りに触れて、例えば広報でこの問題を、区長の立場を明らかにするだとか、区民の皆さんにもぜひ知らせて、地方自治、地方財政を守るための立場を鮮明にしていただきたいなというふうに思います。そのことをお願いをいたしまして、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"高星委員","kind":"質問・要望","question":"出先機関は、学校も、保育園もそうでありますけれども、往々にして地域の方々と一緒に生きていくんだ、成長していくんだというスタンスがあるものですから、そのところをお聞かせいただきたいと思います。２点目には、同じく寄附金ですが、決算書で言うと７０ページですけれども、寄附金の項の２節の都市基盤整備指定寄附金、これは何なのかということを教えていただきたいと思っています。","respondent":"市岡企画財政課長、金子保育課長","answer":"この寄附受領というのは、ある意味では非常に神経を細やかに使わなければいけないものですので、基本的には本課で対応をしている。保育料につきましては、認証保育所のほうが決定するものでありますが、細かい資料は手元にありませんが、たしか７万８,０００円程度の上限を東京都ならびに区の要綱で定めているというふうな性格のものです。","id":"exchange-123"},{"speaker":"高星委員","kind":"質問・要望","question":"特に学校はＰＴＡとの関係も、いろいろと地域との関係があるわけで、結びつきが大きいわけですから、いろいろなことがあろうかというふうに思うんですが、そのところを答えられることがあったら答えていただきたいというふうに思います。それから、認証保育所の関係です。東京都も財政的に何兆円も赤字をしょっているわけですから、その意味で、東京都の補助金もカットしてしまうということに動いてくる。","respondent":"金子保育課長、上野都市開発課長","answer":"ただ、施設そのものは地域に根ざした施設というふうに考えておりますので、その辺の趣旨もすべて汲み取った上でご説明していくべきものかなというふうに考えております。私のほうからは、雑入におけます都市基盤整備費収入の内訳につきまして、ご説明申し上げます。","id":"exchange-124"},{"speaker":"高星委員","kind":"質問・要望","question":"これは学校のほうもそうだと思います。それから、６億８,０００万円の話は分かりました。これがどうも今でも頭の中でひっかかっているものですから、これをどういうふうに処されているのかな、こんなふうに思ったので、その部分については土地の寄附という形になるんだろうというふうに思うので、開発組合が寄附した部分について、どういうふうに扱われているのか、ちょっとお聞かせいただきたいと思います。","respondent":"鷹倉経理課長、金子保育課長","answer":"そのことをご指摘のことかと思いますけれども、開発組合とは関連がないのではないかと考えています。私どもとしましては、今後も保育のサービスについてはいろいろな面で向上させていくとともに、運営についてもあらゆる面で効率的な運営ができるようにこれからも努めていきたいというふうに考えてあります。","id":"exchange-125"},{"speaker":"高星委員","kind":"意見","question":"たばこをやらないと思ったけれども、１分ありますので、要請したいと思います。そうすると、１時間あたり千円ぐらいのパート扱いになっているそうです。よくわからないんだけれども、それだったら、私がやってあげるわよというような人もざらにおるので、別にお金を取ることが目的でないのは分かっているんだけれども、その辺のスタンスのところをちょっと聞いて、終わりたいと思います。","respondent":"田村地域活動課長","answer":"頑張りますので、よろしくお願いいたします。","id":"exchange-126"},{"speaker":"三上委員","kind":"質問","question":"決算書の１５６ページにあたるんでしょうか、職員費のところで、１５８ページのところに、その他の職員費という項目が、これが補正予算を８億７,０００万円余組んでおり、さらに予備費を随分集めている。これはどういうことなのか、まずお聞かせいただけませんか。","respondent":"桑村人事課長","answer":"これについての見込みにつきましては、さらに３月末になりまして予想外の退職の人数が出たものですので、その意味での退職手当の部分が足りなくなったということが理由です。","id":"exchange-127"},{"speaker":"三上委員","kind":"質問・要望","question":"もう１点は、昇給に関しての問題で、国もいろいろなことで取り組みを始めてきているわけですけれども、制度上はいろいろなことで昇給制度について、品川区が今取り組んでいる状況というのはどういう取り組み方をしているのか、また国はこういうことで総務省からいろいろなことが言われてきているけれども、それに対して品川区はどうなんだとか、こういうようなことについて。","respondent":"桑村人事課長","answer":"今、国のほうで、いわゆる人事院のほうで検討しているのは、普通昇給のあり方そのものが、今まで勤務実績が悪い職員については落としていたわけですけれども、これは形式的な意味での、例えば病気で休んでいるとか、休職とか、そこについては落としていたわけですけれども。","id":"exchange-128"},{"speaker":"三上委員","kind":"質問","question":"導入したいというお考えは今分かったんですが、これについては、今後どういうスケジュール的なことは考えていらっしゃるんでしょうか。それから、これは定期昇給に関してですけれども、特別昇給という部分がありますよね、これについては現状どういうふうになっているんですか。","respondent":"桑村人事課長","answer":"そういう意味では、２３区横並びでの制度ではなくて、各区がある程度自分なりの人事考課等を使っての制度のつくり方という方向での検討、あるいは交渉というようなことになっていくんだと考えています。","id":"exchange-129"},{"speaker":"三上委員","kind":"質問・要望","question":"もう１点ちょっとお聞かせいただきたいのは、退職時の特別昇給制度については国は廃止するということになっておりますけれども、これについては、２３区としてどうなっているのか、品川区としてはどうなっているのか、そこのところをお聞かせいただきたいと思います。それから、退職の問題で、品川区は今裁判をやっていらっしゃいますよね。","respondent":"桑村人事課長","answer":"私どもにつきましては、これまで勤務実績に基づいて、基本的にはある程度の職員については落としてきたわけですけれども、こういった制度そのもの自体はこの程度の改革ではなかなかうまくいかないだろうということで、平成１５年度から変更をいたしています。","id":"exchange-130"},{"speaker":"三上委員","kind":"質問","question":"裁判上、ご本人たちは戻る気はないと言っていますが、これで戻りたいという希望に変わった場合は戻れるというふうに理解しておいていいんでしょうか。","respondent":"桑村人事課長","answer":"その意味では、退職自体が間違いだということがあるんでしたら、勧奨退職ということを理由に辞めるという意思を持っているんだから、そのことがないんだったら元に戻りたいということがあれば、それなりの検討をしたいというふうに考えてあります。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問","question":"ちょっと理解できない部分もありますけれども、もうしばらく様子は見ていきたいと思います。都費職員にあってはまだ押印が使われているということを指摘して、それについて改善したいというような答弁であったんですけれども、今日までの間そういった部分についてはどういうふうな検討がされてきているのかというところをまずお聞きしたいと思います。","respondent":"市川庶務課長","answer":"システムのインフラの整備ということがまず検討課題に上がっているわけですけれども、この辺は勤怠管理もそうなんですが、現在開発を進めてあります学校事務の電算化というか、その辺の問題、それから、広く学校のＩＴ化という問題。","id":"exchange-132"},{"speaker":"三上委員","kind":"質問・要望","question":"その身分証そのものではまだタイムレコーダー的なカードの管理という形にはならない。そこのところはしっかりと自分で打刻しましょうよと、こういうことの問題だと思うんですけれども、そういうことが、今世の中として求められている時代にありますよという時代にありながら、教職員がそれを拒むという姿勢であるのかどうかということについて、一つだけお答えいただきたいと思います。","respondent":"市川庶務課長","answer":"今ご指摘のあったように、世の中の動向がどこに向かっているか、このことについて、学校の教職員と私どもに基本的な認識の差はないというふうに考えてあります。","id":"exchange-133"},{"speaker":"原委員","kind":"質問・要望","question":"最後ということで、端的に１点だけお伺いをします。そこら辺の考え方についてお伺いをしたいなと考えています。それから、いろいろな施設等々があるわけですが、その中で手数料、使用料のバランスをどう考えられているかということです。さらに、減価償却等々完了した施設、そういったものに対しての金額設定についてはどのような反映をさせているかというところについてお伺いをします。","respondent":"市岡企画財政課長","answer":"これにかかる時間を単価単位で計算をしまして、積算をしている。これの直近の例が、住基カードを２,０００円に設定しましたけれども、そのとき委員会等で細かくご説明したような例があります。","id":"exchange-134"},{"speaker":"原委員","kind":"質問・要望","question":"先ほど施設によってのバランス性についてお答えがなかったわけですが、そういったところは、その施設施設によって使用料等については、一つ一つのここについての考え方が出てくるのではないかなと思うので、そこのところもちょっとお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"ただ、委員おっしゃられるとおり、施設の中には民間と競合するような施設から、区民の皆さんが身近なところで使っていただく施設等がありまして、こういうものは維持管理経費そのものにも差がありますし、それから、最近はあまり大規模な改修経費を織り込みますと。","id":"exchange-135"},{"speaker":"原委員","kind":"質問","question":"そういう意味では、合理的範囲だということですが、ただ、そういった要因がいろいろ出てきている中で、見直しをかけていかなければならないと思うんですが、その施設施設によっての耐久性等々もあるとは思いますが、その辺のところの見直しのかけ方はどのような形でされていますでしょうか。","respondent":"市岡企画財政課長","answer":"このように区民サービスの水準や、使い勝手、これらを維持しながら、ある意味では受益者負担の原則を貫くことが広く納税者一般との公平でもありますので、先頃施設予約システムなどを使って、ソフトの面では利用勝手を大変よくしてまいりましたけれども。","id":"exchange-136"},{"speaker":"原委員","kind":"質問・要望","question":"要するに、現額に対して決算額がそこまで至っていないということですが、これは予算の組み方が原因なのか、あるいはほかに要因があるのか、見込みとの差の考え方についてお伺いをさせていただきたいと思います。","respondent":"市岡企画財政課長","answer":"使用料、手数料につきましては、予算を組むときに前年の実績、それから予算編成、ちょうど今ですと、編成期の上半期の実績、これらを踏まえて特別な価格改定がない限りはそれらのトレンドで翌年を見込む、こういうことが原則です。","id":"exchange-137"},{"speaker":"原委員","kind":"質問・要望","question":"執行段階に、今みたいなところを十分精査をしていただいて、これに反映できるような形をとっていただきたいと思います。確かに多少余裕がないといけない部分も科目によってはあるのかもしれないというふうに思っております。いずれにしても、目的に合った使用料であり、また手数料であってほしいと思うし、見直しのことについては常に考えていただきたいというのを要望して、終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/180055?Template=document&Id=1228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":114351,"voices":323}},{"id":"h16-20041005-4","meetingId":"h16-c-settlement","date":"2004年10月5日","dateIso":"2004-10-05","committee":"決算特別委員会","time":"午前１０時０４分～午後５時５４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"最初に、１０７ページの奨学金貸付事業についてお伺いをしたいと思いますが、この中で、事務費、今年５１４万円余、前年平成１４年は約２７０万円弱ということですけれども、前年はこの緊急雇用対策ということで計上されておりますが、今年はなぜこういう形で緊急雇用対策というほうはどこでどういう名目で行ってしまって、財源はどういうところから出ているのかというのをまず最初にお伺いしたいと思います。","respondent":"長田区民課長","answer":"お尋ねのありました緊急雇用の部分、去年は２００万円ほど滞納をしている方について、実際に現場へ訪問をして徴収をしてくるということを品川区シルバー人材センターに委託をして回収作業を行っているわけですけれども。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"その他緊急雇用、昨日のお話の中で平成１８年まで補助金の対象になって出てくるということですけれども、それを使わなくなると、今度区のほうが全部もつということで、２００万円ぐらい増えていくというような気がするんですけれども、そこのところをどういうふうにお考えなんでしょうか。","respondent":"長田区民課長","answer":"２００万円の一般財源からの割り振りですけれども、この債権回収につきましては、委託をしている内容は２００万円ちょっと切りますけれども、実際にはそれ以上の効果を上げていただいているというようなことで。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"一般財源化して引き続き回収をしていくという、その言葉の裏にはやはりこれから今後続くであろうこういう不景気のもとに、回収率、未返還率が増えていくというようなことが予想されるんですけれども、ちなみに、今の回収率というのはどれぐらいになっているのでしょうか。","respondent":"長田区民課長","answer":"奨学金につきましては、返還率で言いますと６５.３％、このような状況になってあります。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"返還率は６５％、ちょっと私が言葉足らずだったのかもしれないんですが、さっきシルバー人材センターの方をお願いをして回収をされているというお話を聞きましたけれども、その方たちが回収する率をちょっと今教えていただければと思いまして伺いました。","respondent":"長田区民課長","answer":"ちょっと今資料が出てこないんですけれども、たしか委託費用が１９６万円で、平成１５年度実績については３００万円ちょっと超えていたと思います。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"それはまた後ほど伺わします。１１３ページの戸籍及び住民基本台帳費の大まかなところなんですけれども、まず、地域センターで今行われているオンライン、住民票、戸籍抄本、謄本、そしてその他のものがあるんですけれども、オンラインで結ばれているものは、主たるものはどのようなものがあるのでしょうか。オンラインで結ばれていないものがあれば、それもちょっとお教え願いたいと思います。","respondent":"冨田戸籍住民課長","answer":"戸籍住民課所管の事務で言えば、住民票、住民基本台帳事務、それから戸籍事務、それから外国人登録の記載事項証明等、それから印鑑証明、印鑑登録に関しての事務の四つが大まかなところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"オンラインで結ばれていないのは、それ以外のものということでよろしいでしょうか。","respondent":"冨田戸籍住民課長","answer":"これは例えば転籍等によりまして、品川区の戸籍を他区に移したとかというようなものについては現在開発中ですので、そういった事務については、本課においても行っておりませんし、地域センターにおいても行っていないという状態があります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"オンラインで結ばれているもの、結ばれていないものをちょっと伺いましたが、ここに、セキュリティーの部分で、品川区においてはセキュリティーの部分は個人情報が漏れてしまうということに関しては、まず限りなく１００％に近く安全性があると私は認識しております。","respondent":"冨田戸籍住民課長","answer":"ということで、現在では実施する予定は考えてございません。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"今にして見れば、素人的なやり方だと思うんですけれども、その点についてどういうふうにお考えになりますでしょうか。","respondent":"冨田戸籍住民課長","answer":"ファックスにつきましては、従来戸籍に関して地域センターで受付をして、ファックスで申請書を送って、本庁でファックスで送り返しをして交付をするという扱いをしておりましたけれども、ファックス自体をやる場合には専用回線を使いますので。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"今行政のオンラインで結ばれた専用のファックスだということを伺いましたので、そこの部分、私たちが普段使っている電話ファックスと比べて全然セキュリティーの部分がしっかりしているということを伺いましたので、今後あるだろうことがありますれば、そこのところのきちっとした情報を、個人情報を保護するという重要な観点をよく認識をされて、この事業を、仮に将来的に事業の対象になるのであれば。","respondent":"長田区民課長","answer":"平成１５年度につきましては６３７万２,０００円回収をしていただいています。平成１５年度の調定額が２,３９２万円でしたので、そのうちの２６.６３％をシルバー人材センターの方々が回収をしている、こういう数字です。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"シルバー人材センターの方が２名ということで、その２名の根拠、なぜ２名になるのかという素朴な疑問なんですけれども、なぜ２名で回収作業を行っているのかという、ちょっとそこのところを教えてください。","respondent":"長田区民課長","answer":"特に２名という根拠はありませんけれども、債権回収の場合には、いろんな困難ですとか、場合によっては事故等が想定をできるというようなことで、１人で行くよりはお２人ペアで行っていただいたほうがよろしいだろうという判断から２名にさせていただいているものです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"２名専属で、その２名の対のがほかのグループがあるわけではなくて、その２名でもっぱら回収作業、回収というか、未収金の部分のお願いに上がっているということで認識をしてよろしいわけですね。","respondent":"長田区民課長","answer":"区で催告をしている以外は２名で対応していただいているところです。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"成果報告書の１０７ページ、職員研修費、１０８ページ、水と緑の交流事業、１０９ページの生活安全推進事業、以上三つをお聞きしたいと思います。職員研修費です。簡単にそれぞれの研修、対象者とか、またどのような目的でこの研修が行われているのか、まずは教えていただきたいと思います。","respondent":"桑村人事課長","answer":"特別研修というのは、いわゆる特に計画いたします講演会ですとかそういったものを予定しているものです。最後に共同研修ですが、これは何かの事業、あるいは特別区の研修所に行ったりするような研修を予定しています。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"庁内の冊子、今手元に「ふれあい」の８月号があります。この中で、いわゆる自主研究グループ活動が紹介されておりますが、これは、この研修とはどういう意味合い、関連性になっているか、ちょっとお知らせいただきたいと思います。","respondent":"桑村人事課長","answer":"これについては、私どものほうに申請をしていただきまして、一定の審議をさせていただいて、活動実績等がある程度認められているものについてやっているものです。平成１５年度は５グループ、こういう意味での研修の援助をしているものです。","id":"exchange-013"},{"speaker":"若林委員","kind":"意見","question":"この５グループ、それぞれ中には１０年を超えるような団体、政策研究会とか、例の児童センター将来構想へ向かっての児童センター研究会ですとか、図書館業務の研究会、それから、障害児関係の自主研究グループシャインとか保育発達研究グループ、この紙面、紹介されている文章を見ますと、非常に熱意を持った前向きな各研究会だなというふうに大変に感心をしております。","respondent":"桑村人事課長","answer":"その意味では、さらに多くのグループができることを望んでいるものです。","id":"exchange-014"},{"speaker":"若林委員","kind":"提案","question":"大体のグループが、例えば政策研究会にしてみますと、基礎的自治体の内実を確実なものとするために、さまざまな区に必要な政策を勉強して、また提言をしていくような、そういう表現も見られます。このような職員の方たちの自主グループの提言、または要望みたいなものが、提案みたいなものが、区のいわゆる政策決定の過程においては、どのように考慮をされているんでしょうか。","respondent":"桑村人事課長","answer":"保育園等につきましても、それぞれのいわゆる保育課の中で、その研究の中身については仕事に生かしているんだろうというふうに考えているものです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、あくまでもみずからの部署の中での具体的な運営面での研究という枠でとどまって、それが即、即といいますか、いろんな政策決定の中で、さまざまな理事者が受け入れるとか、また決定の過程にこれが組み込まれるということはないというふうに理解してよろしいでしょうか。","respondent":"桑村人事課長","answer":"そういう意味では、すぐその年の研究していただいたものが、次の年の予算に反映するというようなシステムをつくってございませんけれども、それについては、私どものほうの研修のほうの中で、ある程度つくらせていただければ、そういうようなことで考えているものです。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"活発なこういう研究グループを増やしていきたいというようなお言葉もございましたので、各自己研鑽の意味も含めて、また活発に取り組んでいただきたいなと考えています。この山北町、早川町、十数年が経過をいたしまして、年々利用者人数が若干ずつ増えてきて、この数年間トータルでは約１,０００人単位で増加をしているというふうに伺っております。","respondent":"長田区民課長","answer":"そうしたことの中で、交流事業がもう十数年続いていますので、そういった中では自主グループ化できるようなところは自主グループにして、さらにまだ行ったことのない方々については、品川区主催のツアーを募って、そういったところをまず経験していただくというようなことで。","id":"exchange-017"},{"speaker":"若林委員","kind":"意見","question":"盛んに都会にいる人たちにとっては農村に帰れとか、また農村に学んでいこう、農村に行けば、例えば自然、景観、また原風景、非常に学ぶべきもの、またその自然の中にどっぷりつかって生活して、また都会に戻ってきて、私たちのまちはこんなにあそことは違ったいいところがある、再発見、そういうふうな自分自身の中でも交流ができる、こういう意味では、この見直しに当たっては。","respondent":"長田区民課長","answer":"それで、特に早川町のほうは南アルプスのふもとというようなことと、それから自然があるというようなことの中で、農業体験、あるいはこれから今話に出ているのは、林業の町でもありますので、林業体験ができるようなツアーも企画できないかというようなことで検討はしています。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。続きまして、最後に生活安全推進事業についてです。平成１４年の４月に生活安全条例が品川区において施行されました。具体的にはその中で、生活安全協議会を設けてさまざまな方向性、施策、運営、区民等の協働のあり方、こういうことを協議をされている、そういうふうに伺いました。","respondent":"杉浦生活安全担当課長","answer":"私どもは、昨年の１０月から生活安全サポート隊というものを発足させておりまして、毎日地域への警戒活動をやっておるわけですが、その活動の中で、例えば今日の交番はどこが空いているよというのを警察と連携をして連絡をとって、そして。","id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"そうしますと、今、まち中を自転車で走りますと、結構サポート隊ではないと思うんですが、おまわりさんがもともと空き交番だったのが随分目につくようになりました。地域の安全のためにまたぜひ引き続きよろしくお願いをいたします。この１年、具体的にどのようなサポート隊も含めて、具体的な取り組みと、またその中でまちの安心、安全のためにどういう成果があったのか、お知らせを願います。","respondent":"杉浦生活安全担当課長","answer":"そういったものが立ち上がってまいりまして、９月末現在で１３団体１,００６名という皆さんが自主的に我が町パトロール以外の部分で防犯活動に立ち上がるようになったという、こういう一つの流れができてきたです。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"これで終わりにします。今、課長のほうからも子どもの安全というお言葉が出ました。具体的には取り上げる時間はありませんけれども、五反田周辺のいわゆる小中一貫校絡みの安全性、ほんとうに子どもの目線でこれからの品川の安全を、安心をぜひ取り組んでいただきたい、このことを一言お願いをいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"大西委員","kind":"質問・要望","question":"１０８ページですね。ちょっと言い忘れていましたが、地域食事サービス、これが８５のものですが、これが評価としてはＡになっておりますが、どういう点でこれをＡに評価していたかということをお尋ねしたいのと、それと、この地域食事サービスがいつから行われて、初年度、次年度、そして現在、要するに昨年平成１５年度はどのような推移で来ているのかということを教えていただきたいと思います。","respondent":"福田区議会事務局長、田村地域活動課長","answer":"最初のご質問は考え方の問題だろうというふうに思いますので、私のほうからご答弁をお許しいただきたいと思います。それで、実際に件数ですけれども、平成１５年末現在で、成果報告書にも延べ人数では載ってありますが、実人数で申し上げますと、平成１５年度末、３月末で給食サービス、昼ですが、受給者が１８８名、それでボランティアが実質２２８名。","id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"今お答えの中で地域活動課長でしょうか、私がお尋ねしたのが、平成１５年度と、それとこれを始めたときからの推移ということで、始めたときにはどれぐらいの件数があった、初年度というのはあまり当てにならないというか、初年度にこういうことをやっているんだという告知並びに受益者がいて、それから２年度、３年度という形で推移してきて、二、三年後がほんとうの状態じゃないか。","respondent":"田村地域活動課長、中島指導課長","answer":"その後、平成９年に中学校の夕食を２校開始いたしまして、その後、平成１０年になりまして、小学校３９校、中学校１４校ということで実施してまいりました。私どもで今検討しております小中一貫校のカリキュラムにおきましても、国語ではここのところを十分に充実して取り組んでいくところです。","id":"exchange-023"},{"speaker":"大西委員","kind":"質問・要望","question":"どれぐらいの人が増えてきたのかということで、そこで比較しないとちょっと比較のしようがないんですね。その点のところをちょっと教えていただきたいと思います。そういう中で、箱根にも料理が大変おいしくて行きたいという要望を耳にするわけですけれども、残念ながら、箱根荘のほうでトイレのほうが和式のトイレが大部分を占めているということで、非常にその部分で利用しづらい。","respondent":"田村地域活動課長、長田区民課長","answer":"手持ちで、先ほど学校数はお答えしましたが、過去３年分しか手持ちも含めまして現在ございません。箱根荘につきましては、現在のところ７カ所ほどの洋式トイレに改修をしてございまして、そのうち５カ所がウォッシュレット付きに改修をしてきたものです。","id":"exchange-024"},{"speaker":"大西委員","kind":"意見","question":"もう時間がありませんので、この配食サービスは、私が認識している限りにおいては、自分で調理ができないとか、そういう非常に厳しい要件のほうを聞いております。その辺のところを徹底した告知が皆さんできているのかどうか……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、総務費の中の総務管理費の中から何点か質問させていただきたいと思います。それから、私立幼稚園の就園奨励費補助金ですが、１万８,１５６人で、１億１,２００万円ぐらいですか、その部分が出ておりますが、この財源のほうになると、歳入で８２ページの国庫補助金に国庫補助基本額は９１８万円なんですよね。この辺の差が出てくる原因をお答えをお願いしたいと思います。","respondent":"鷹倉経理課長、金子保育課長","answer":"この間、当然区議会からも区長のほうからも、移転問題について白紙撤回していただきたい、このように要望してきたわけですけれども、以前の答弁もありますけれども、これは閣議決定があるので難しいという状況。もう一つ肝心なところは、就園奨励費の補助金の国の考え方としては、区市町村が支出した２５％を国が補助するというふうになっていますが、現実のところは。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"あの時点で何も動かなければ移転されてしまったと思うんですが、そういう点でも今後区のほうとしても連絡を密に取り合って、確実に今イージャパン計画でいつ最終的なところはわからないですけれども、できる限り長期にわたって利用しやすい形をお願いしたいと思います。それから、奨励金ですが、今２０.６％のほうの国というお話がありました。２,３００万円ぐらいしか歳入で入ってきていないんですね。","respondent":"金子保育課長","answer":"ですが、具体的にどうこうと決まっているわけではないので、私どもとしては今後の推移を十分注意してまいりたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"幼稚園の関係で、残りが８,９００万円ぐらいが差額が出ていると思います。これは、先ほどの差額なら区のほうの分が出ている部分を８,９００万円ぐらいでもやはり区のほうの一般財源で出ているのか、逆にこれが財調の算定になっていかないのかな、２３区が全部この補助金なんかも絡んでいると思うんですよね。そうすると、各区がやるのか、都の分で見てもらう分なのか、そこら辺をお願いしたい。","respondent":"市岡企画財政課長","answer":"それはそれでいいんですが、もともと東京都については、この就園奨励費についても不利な取り扱いを受けている一つの例でございまして、これは東京都自身も財調の前提として国庫補助率の他の富裕団体以外のところは３分の１受けているところがありますので。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。補助金の関係なんですけれども、就園奨励金の補助対象基準のところを見ていたときに、保育園と比べたときに、基準の内容が違うんですよね。というのは、私立幼稚園の所得基準は特別区民税が基準になっていて、保育園のほうになると所得税。何で特別区民税と国税になっちゃうのかなと、そこら辺の基準の差というのは何が原因なのかを教えていただければと思います。","respondent":"金子保育課長","answer":"それで、国の徴収金基準額がこの所得税を用いているというのは推測になりますけれども、やはりほかの補助と違って保育園保育料というのは、国も都も負担金であるし。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それで、ホームページを見ていても、区の中に出ているんですけれども、やはりよくわからなかったので、その根拠は何なのかなということで、ちょっと確認をさせてもらいました。それと、臨海斎場の件と、学校等の避難所機能の充実に関してちょっとお聞きします。こういう備品の関係というのは、いろいろ新しいものも出ていると思うんですが、交換していらっしゃるのかどうか、そこら辺をお聞きしたい。","respondent":"久保田防災課長、長田区民課長","answer":"したがいまして、今後そういうようなことについて、よりふさわしい、そういうものについては私ども検討していくということは、これは十分やっていきたいと思いますけれども、ただ、その辺の今持っている備蓄品との兼ね合いの中で。臨海斎場の負担金の割合のお尋ねですけれども、負担金につきましては、構成区の５区で平成１３年１２月に取り決めがなされておりまして、これにつきまして、品川区の数字。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"トイレの件ですけれども非常に使いにくいんですよ。それから、臨海斎場のほうは１７.２％というお話があったんですけれども、これで３年待たずに見直しをするなんていう報道も出ていたんですが、品川区としては使っていただきたい中で負担率が上がるのもどうなのかなということで、３年待たずにやはり見直しをされてしまうのかどうか、そこら辺、区のほうのお考えを、お答えをお願いしたいと思います。","respondent":"久保田防災課長、長田区民課長","answer":"どこまで用意できるかということについては限界があるわけですので、今全体で１,５００基ほど持ってあります。数万円するものですので、当然、費用対効果との兼ね合いもありますので、十分今後検討していきたい、こういうことです。先ごろ新聞報道等もされましたけれども、３年後に向けて事務レベルでは検討会を持ってあります。この中で検討して３年後という約束ですので、早まることはありません。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点ちょっと短く。区民保養所に関してなんですが、この決算成果報告書の中で去年と今年と書き方が変わっている。去年明細があったのは今年はないんですが、何か特別な意図があるのでしょうか。","respondent":"市岡企画財政課長","answer":"それで、私のほうでお答えしますが、申しわけありません、これは実は去年は事務事業評価で各保養所ごとに違う評価が出ていたもので、実績としては細かく入れましたけれども、これはこの箇所だけではありませんが、毎年成果報告書の見直しをする際に。","id":"exchange-032"},{"speaker":"南委員","kind":"意見","question":"１０７ページの代替職員雇用経費に関して、お尋ねをしたいと思います。ここの決算書に出ておりますのは４,５６９人、３,８６４万３,４６１円ということですが、具体的な内容、どのような職場に主なところで結構ですけれども、配置されているのか、そして、数字は出ておりますけれども、賃金がどの程度のものなのか、勤務時間はどうなのか等々についてお尋ねをしたいと思います。","respondent":"桑村人事課長","answer":"延べ４,５６９人ですけれども、これはいわゆる延べですので、この比ということですので、年間で月２０日ぐらい使えば大体１９名ぐらいというようなことです。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"そうしましたら、ここに計上しているのは保育園、学校以外のものということですが、そこも含めてどういう状況なのかをちょっと伺いたいと考えていますけれども、よろしくお願いいたします。","respondent":"桑村人事課長","answer":"全体の経費等につきましては押さえているんですけれども、具体的な人数等が私どものほうでは押さえておりませんので、全体の臨時職員のほうの賃金ですけれども、私ども以外に所管課のほうで大体６,０００万円ぐらい執行しています。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、私は庁内だけじゃなくて、品川区役所の全分野にかかわって、どのような形態の職員配置がされているのか、どこにどういうふうに盛られているのかをちょっと伺いたいと考えていますので、ぜひとも保育園、学校のところも教えていただきたいと思います。ですから、ここで聞く以外にないのかなというふうに思っておりますので、よろしくお願いいたします。","respondent":"桑村人事課長、金子保育課長","answer":"その意味では、保育園ですと、保育園運営費等のところの経費で入ってありますので、基本的に先ほどご答弁したとおり、内訳は私どものほうで持ってございませんので、所管課が来ればお答えすると思いますので、よろしくお願いいたします。保育課における非常勤と臨時職員の金額ですけれども、ただいまちょっと資料を寄せておりますので、お待ちいただきたいと思います。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"できれば、保育園の派遣職員については、平成１５年度の金額をおっしゃっていただきましたけれども、いつからそういう形態で採用しているのか、何人採用されているのか、どういうところに派遣職員を充てているのか、その点についてもお尋ねをいただきたいと思います。その点についての見解も伺いたいと思います。そのこともあえて申し上げて、ちょっと質問、ご答弁をお願いします。","respondent":"金子保育課長","answer":"それで、幾つかお話をいただきましたが、私どもとしましては、この人材派遣の導入に当たっては、正規職員からの、従前は正規職員をその分充てていたわけですが、これにかえるに当たって、まずもちろん保育士の資格を持っていること。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"今、ご答弁いただきました。そういう中で１４万円ですよ。しかし私はそういう立場ではないですから、そこは明確にしておきたいと思います。１４万５,０００円で正規職員と同じ仕事をさせる。１４万円では低過ぎますよ。１４万円という、こういう金額で正規職員と同様に働かせるということについて、区長はどういうふうに感じていらっしゃるでしょうか。私はぜひ区長の見解を伺いたいというふうに思うんです。","respondent":"金子保育課長","answer":"その意味では、私どもとしては十分な妥当な契約金額であるというふうに考えておりますし、それぞれの派遣会社が人材派遣されている被雇用者に対して、どのような賃金を払っているかということについては関知するところではありません。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"妥当な賃金だ、関知することない。派遣会社との契約でありますけれども、そういう認識で担当課長は感じていらっしゃるということを区長はよく聞いておいていただきたいと私は思います。それで、派遣職員の方が次のように述べていらっしゃいます。いい仕事をしたい、しかし、１年雇用で切られる。いい仕事をしたって継続できないじゃないですか。どんどん人間として発達していかないじゃないですか。","respondent":"高橋区長","answer":"人件費が４７％から今２６％になりました。それでも品川区の仕事は２３区で負けをとらない仕事をしています。そのところをよくご認識をしていただきたいと思います。","id":"exchange-038"},{"speaker":"南委員","kind":"意見","question":"今、区長から答弁をいただきましたけれども、しかし、区長は一生懸命仕事をしていらっしゃるとおっしゃいました。確かにそうだと思います。しかし、土曜日や日曜日も出勤している多くの方が働いているんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"９ページのほうに報告書でいろいろ載っておりますけれども、この私立幼稚園預かり保育モデルという、この事業ですが、どういう経緯で始められたのかということ、それから８園今されているんですけれども、１園１００万円程度ということなんですが、これは何のための経費として使われているのか、その内容をぜひ教えていただきたいと思います。","respondent":"金子保育課長","answer":"私立幼稚園の預かり保育事業についてのお尋ねですが、まず、この事業ですが、この預かり保育につきましてはきんだぁくらぶという呼称で呼んでおりますが、私ども幼保一元化事業も実施しておりますけれども、従来の幼稚園の４時間、５時間の保護者の保育ニーズに。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"二つ目の１園１００万円程度だと思うんですが、これはどういう経費として支給、補助をされているのか、その辺はいかがでしょうか。","respondent":"金子保育課長","answer":"それで、決算書平成１５年度では確かに８園実施しておりましたが、この５月３１日付で１園廃園になりましたので、現在のところは７園が実施しているというものです。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"その中で気になるのは、私立幼稚園の運営も非常に大変なところがあるかと思います。そこで、１００万円という、これは人件費といいましても、非常にそんな多い、決して十分な金額とは思えないとは思うんですが、その辺の私立幼稚園等の関係といいますか、ある程度の合意はとられて進めているんでしょうから、それについて、どういう私立幼稚園側、受け入れる側の考え方も含めてお願いいたします。","respondent":"金子保育課長","answer":"私どもとしましては、この事業を東京都の補助との絡みもありますので、この東京都の補助金の推移、今後の動きですね、それも見定めながら、私どもとしてはその適切な補助の金額というものを検討していく必要があるというふうに考えてあります。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"今後三位一体という形で、非常に補助金の件に関しては、しっかりと見ていかなければいけないというところだと思います。それで、金額等１００万円程度ということでされてはいるんですが、ほんとうにこの１００万円程度で十分と見ているのか、例えばこれから拡大しようというところの幼稚園の側としては、金額等々のその増加というのは望んではいないのか、そこら辺の情報は聞いていらっしゃいますでしょうか。","respondent":"金子保育課長","answer":"それで、先ほども申し上げましたとおりですが、私どもとしては、今後も適切な補助については、検討してまいりたいというふうに考えております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"利用されている方の傾向を少しお聞きしたいんですが、どういう理由で利用されている方が多くなってきているのか、その辺はいかがでしょうか。","respondent":"金子保育課長","answer":"それでこれが、つまりきんだぁくらぶを実施しているということが幼稚園の選択の一つの要素になっているということもお聞きしています。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"そうすると、働かれている、就労している方もいらっしゃるという動きなのでしょうか。その辺の動向はいかがでしょうか。","respondent":"金子保育課長","answer":"確かにそういう方もいらっしゃるというふうにお聞きしておりますが、細かいデータを収集しているわけではないので、今のところ正確には把握してございません。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"そういう意味では、今後幼保一元という形も含めていろいろ検討されていくんだろうと思うんですが、今、７園ということですが、今後、私立幼稚園、公立幼稚園はまた担当が変わると思いますけれども、品川区としての考え方、そういう形で私立の幼稚園に対してやっていきたいというところに対しての補助といいますか、それも今後考えられようとしているのか、その辺はいかがでしょうか。","respondent":"金子保育課長","answer":"私どもは現在幼保一元化事業を進める中で、今までの幼稚園と保育園と二者択一であるという考え方が、まだまだ現状も多くはそういう傾向にありますが、そういう考え方が抜け切れない方が非常に多いと考えています。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"１０８ページの地域振興事業なんですが、コミュニティー組織づくりという中に３９０万円でしょうか、入っておりますけれども、これはどういう活動をされたのか、どんな成果があったのかということをまずお聞きしたいと思います。","respondent":"田村地域活動課長","answer":"地域振興事業の中の、特にコミュニティー組織づくりですが、これは、実際には名称的には地区活動会議というようなものをそれぞれ地域の方々が地域の問題をみずから解決して互いに助け合う、連帯感に支えられた地域社会をつくろうという目的のために、地域センターごとに町会。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"これは平成１５年度からということの認識でよろしいんでしょうか。以前はそういう形はなかったということなんでしょうか。","respondent":"田村地域活動課長","answer":"以前からこの事業自体は実施しております。ただし、１３すべてが地域活動会議があったわけではなく、今は現在のところ１３地域センターすべて活動会議があるです。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"適正というのはあまりいい言葉じゃないかもしれませんけれども、コミュニティーづくりですので、新しい人材をどんどん入っていただいて具体化していくということが必要になってくると思うんですが、そういう動きは、今年度せっかく１３地域センターで行われるということがありますので、そのこういう検討はありますでしょうか。","respondent":"田村地域活動課長","answer":"先ほど申し上げましたように、メンバーはこういうメンバーじゃなきゃいけないよという形ではございませんが、一般にどこの地域センターも同様ですが、町会、自治会の方、あとは青少年対策の地区委員、あとは民生委員、高齢者クラブ等ですから、必要に応じて、議題。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"それが地域の活性化にもなりますし、それから、商店街の活性化というところに広がっていく、いろんなところに広がりが出てくるものですから、それを区として率先してアイデアを出すとか、それから横のつながりをつくってあげられるのは、やはり区の立場だからできるというところがあろうかと思うんですが、その辺の新たな試みというのは今後のお考えはありますでしょうか。","respondent":"田村地域活動課長","answer":"例えば高齢者クラブにしても、民生委員にしても、出張所を地域センターに名称変更をして、それぞれ１３の地域ごとに割って地域一体化して考えていこうという形でも、これも何年も検討して実現した。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺を網羅的にして、それで、こういう状況でこういうことをやっているから、ご紹介をするとか、興味を持っていただくとか、協働して何かできることについては協働できるような環境をつくってあげるとかということは、率先してやれることがあるんではないかなというふうに思っているんですが、今後。","respondent":"榎本行財政改革担当課長","answer":"今、地域のいろいろな団体のということでお話がありましたけれども、ボランティア活動の組織等もつくりまして、そういった情報を集めながら、いろいろな区で持っていない情報とかもかなりたくさんあると思いますので。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"私は１１０ページの契約関係事務費に関連しまして質問をします。それで、少ない予算でその最大の効果を上げるためのという観点から入札制度を考えたときに、一つは、その視点としては公正な競争を促進していくという観点と、もう一方では、適正な品質の確保をいかにして図っていくかといったようなことが求められるかと考えています。","respondent":"鷹倉経理課長","answer":"来年度に向けてこの制限付き一般競争入札の拡大をしていきたい、そうすることによって、競争性等の、あるいは透明性等の確保ということに及んできた、このように考えているところです。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"それはほんの一例かもしれませんが、そういった区の独自の取り組みという中で業者選定の考え方、単に過去の実績だけではなくて、将来に向けての区民福祉の向上につながる業者とのつき合いができればいいわけですので、その辺の業者選定の考え方、チェックの仕方について、お考えがありましたらお聞かせをいただきたいと思います。","respondent":"鷹倉経理課長","answer":"したがいまして、その私ども制限付き一般競争入札の中で、条件付けのところでの、工事にもいろいろよりますけれども、新しくてできるところについては、その辺のところの条件をよく吟味しながら、対応していきたいな、このように考えているところです。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった意味での検査体制、全体的には外部委託等々が進んでいる中で、区が直接というのは分野的には少なくなってきているかもしれませんが、区がトータルを含めて責任を持つ中での品質を確保していくということに対する考えをお聞かせをいただきたいと思います。","respondent":"鷹倉経理課長","answer":"私ども経理課の検査をする部門がありますけれども、そこでもさらにチェックをする。そういう形で製品が適正に執行されている、それを確認した上で、お支払いをする、こういう形のチェック体制をとっているところです。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"電子申請は来年の１月に稼働、電子調達のうちの業者登録が今年の１２月、そして電子入札が来年の４月稼働ということで、これは東京電子自治体共同運営協議会のもとでこのシステムが開発されておりますが、この電子申請、電子調達に移行すると、これまでの入札等々の中で、どのようなメリットがあるのか、またこれまでの入札のやり方とどう変わっていくのか。","respondent":"鷹倉経理課長","answer":"したがって、今いろいろ検討していますけれども、ある程度の情報が公表されていく。したがいまして、入札のプロセスの透明というものが図られていくだろうです。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ共同化の電子化のメリットもありますし、またその中で、区の独自性が発揮できるように、ご尽力いただきたいと思います。それで、今後、システムのこれは開発の一部分だろうと思いますが、その今費用対効果の部分もありますけれども、これまで２００万円前後で推移されてきたものが、今後共同化することによって区の負担がどういうふうにかわっていくのか、最後にそれをお聞かせをいただきたいと思います。","respondent":"田中情報システム課長","answer":"共同運営の部分については平成１６年度１７０万円程度で、平成１７年度以降、電子申請、電子調達合わせてほぼ実質的には１,０００万円弱、年間の負担で電子申請、電子調達ともできるということになっております。","id":"exchange-056"},{"speaker":"嶋委員","kind":"質問","question":"私のほうからは３点お伺いいたします。１０７ページの非核平和都市品川宣言事業について、二つ目には１１０ページのＣＡＴＶ事業について、３番目には１１２ページの区民保養所の関係について、３点についてお伺いいたします。初めに非核平和都市品川宣言、今回記念事業ということで明年２０周年を迎えるということで、これについてプレス発表されておりますが、その事業について、お伺いをいたします。","respondent":"宮地総務課長","answer":"内容といたしましては、今度できましたしながわ中央公園に平和のモニュメントを設置し、その元にタイムカプセルを埋め込みまして、これを３０年後の２０３５年に開封するという、そういった取り組みと、それから講演会を実施すると同時に、その記念の日の前後、２５。","id":"exchange-057"},{"speaker":"嶋委員","kind":"質問・要望","question":"今回は２０周年ということで、モニュメントをつくられているところです。そういう意味ではモニュメントがどんな形で今進められているのか、またそのタイムカプセル埋め込み、次世代を担う青少年ということで３０年後に開封するという、その時代まで元気に生きていきたいと考えていますが、そういう意味で、タイムカプセル埋め込みの内容について、ちょっとお聞かせをいただきたいと思います。","respondent":"宮地総務課長","answer":"私どものほうで実施しております青少年の広島、それから長崎の派遣事業の参加者の皆さんにもその気持ちを込めて、平和に関するメッセージを書き込んでいただきまして、カプセルの中に埋め込むということを考えております。","id":"exchange-058"},{"speaker":"嶋委員","kind":"提案","question":"そういう中で、品川区もこの非核平和都市品川宣言２０周年、このタイムカプセルも、品川区だけではなくて、せっかく品川区は姉妹都市、ポートランド市、また友好都市、オークランド市、ジュネーブ市という交流がありますので、そういう中でそういう国の方たちからも発信がいただけたらいいかなという思いがありますが、ご所見をお伺いいたします。","respondent":"宮地総務課長","answer":"あまり先のことですので、今現在いろいろ関係のあるところとどういう関係になるかわかりませんし、そういった貴重なご意見も参考にさせていただきながら、現在は小学生を中心に考えているところです。","id":"exchange-059"},{"speaker":"嶋委員","kind":"質問・要望","question":"ほんとうに希望を持って生きていきたいと考えていますが、そういう中で、このタイムカプセルはそれで質問を、平和史編さんという部分でのご見解をお聞かせをいただきたいと考えています。","respondent":"宮地総務課長","answer":"私どものほうは１０年、１５年、２０年と今年迎えまして、次は５０周年が大きな一括りではないかと考えています。その間地道な努力はしてまいりますが、そういった継続した地道な事業というのも大切だと考えていますので、その中で対応してまいりたいというふうに考えております。","id":"exchange-060"},{"speaker":"嶋委員","kind":"意見","question":"ぜひ昭和６３年のこの学童集団疎開資料集の初めの文章の中に、いわゆる品川区民３４万人による心からの平和の願いが日本中、世界中に大きく広がることを願って刊行するものと書いてありますので、ぜひ品川区から世界に大きく発信をして、５０年後を楽しみにお互いに見てみたいと思いますので、もしご意見がございましたら。","respondent":"宮地総務課長","answer":"５０年後というのは今からあと３０年ですので、何とか生きて迎えたいと考えています。","id":"exchange-061"},{"speaker":"嶋委員","kind":"質問・要望","question":"お互いに元気に生きたいと思います。次に、ＣＡＴＶ、ケーブルテレビのほうに入ってまいりたいと考えています。そういう意味では将来的な高度の利用についてということで、どういうお考えで、そのようなのか、お聞かせをいただきたいと思います。","respondent":"中川原広報広聴課長","answer":"今、私どもで資料を取り寄せまして、南東京ケーブルテレビと検討を始めましたものに、いろんな高齢者とか子育て途中の方とか、こういった都市の中で行政サービス。","id":"exchange-062"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味で生放送とか、これからはデジタル放送の競争部分もありますが、その点のお考えをお聞かせをいただきたいと思います。","respondent":"中川原広報広聴課長","answer":"生放送というのは非常に難しいんです。実は区民アナウンサーとか区民ＶＪは素人の方ですので、生放送に対応できる技術とか、そういうものを身につけるというのはなかなか今の皆さんの参加を得てやっていく中では、今後の課題なんです。","id":"exchange-063"},{"speaker":"嶋委員","kind":"質問・要望","question":"それで、よくまちの商店街のこのお店、あんな店とかいうのを、ちょっと正式なタイトルでなくてごめんなさい、間違っていると思いますが、ここへ行ってみたいなと思って電話番号を書いたりするんですが、なかなか場所がわからなくて、ご近所の方に聞いてもわからないことがあるので、きっとそういう方がたくさんいるんではないかと思いますので、せっかくご紹介をするのならば。","respondent":"長田区民課長","answer":"それで、見直しについての方針、方針というものはまだ立ってございませんけれども、今申し上げました廃止を前提としたというようなことと、新たなシステムで立ち上げる、こういうような部分での検討を始めてまいりますけれども、検討の内容といたしましては。","id":"exchange-064"},{"speaker":"嶋委員","kind":"質問・要望","question":"ここは運営委託を富士屋ホテルにやっているところで、大変使いやすく、ほんとうに車いすでそのままどこへでも行かれるという形で、料金も品川区の場合は１部屋とか１人の料金設定でございましたが、ここはもちろん１人の場合は高いんですが、２人になると幾ら、３人になると幾ら、一応最高５人までのお部屋なので、４、５人幾らという形で、それぞれ料金に差がついて、大変仲間づくりには。","respondent":"長田区民課長","answer":"そのほか、施設をそのまま貸して、借りた人が保養所を運営していく方法だとか、民間の旅館、ホテルを指定をしまして補助金を出すというような、いろいろな方法が考えられると思いますので、いい意見も参考にしながら検討させていただきたいと思います。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは成果報告書の１０８ページのマイガーデン運営費と１１１ページの行政評価システム経費について伺います。","respondent":"長田区民課長","answer":"マイガーデンですけれども、マイガーデンにつきましては、区民が日常土に触れる機会がないというようなことから、まず土に触れていただこうというようなこと、それから土に触れて、それから野菜等、あるいは花を育てる中で、その収穫の喜びを知っていただくというようなことと。","id":"exchange-066"},{"speaker":"井上委員","kind":"提案","question":"ほんとうに今おっしゃったように、区民のニーズにすごく合っていたなというのがあるんですけれども、今回の場合には道路用の用地ということで、平成１９年までということなんですけれども、私たちも都市農業を残して農業振興が東京都にも必要だということで、生活者ネットワークでは東京都には提案をしているんですけれども、品川区には残念ながら農業用地はないということで、でもさまざまなところの。","respondent":"長田区民課長","answer":"区内の中で市民農園が果たして持てるだろうかどうだろうかというようなことは、さまざまな条件もありますので、即答はちょっと申し上げられませんけれども、検討課題にさせていただきたい、このように思うところです。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ区民のニーズというところを考えていただいて、前向きに検討課題に乗せていただければと思います。次に行政評価システム経費なんですけれども、この内容はどのようなものなのか、ちょっとお知らせいただきたいんですけれども。","respondent":"榎本行財政改革担当課長","answer":"ここのところの行政評価システム経費として出ている１,５３６万円余ですけれども、これにつきましては、政策評価という外部評価の委員会の運営経費、それから、事務事業評価のシステムのＩＴの維持運営経費というものが入っております。大きく行政評価の２本立ての事務経費です。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問","question":"関連してなんですけれども、政策評価の仕組みづくりで、外部評価委員会が設置されているんですけれども、このことについて五つほど伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"外部評価委員会を設置したのが平成１４年度ですけれども、ちょっと漏れていたらまた後でいただきたいんですが、まず、学識経験の委員につきましては、今までの政策評価で全体を第三次長期基本計画全体を評価して。","id":"exchange-069"},{"speaker":"井上委員","kind":"質問","question":"今の区内団体関係者が町会連合会前会長と東京商工会議所品川支部会長ということになっていますけれども、この理由がちょっとわからないということと、あとは選考委員会をつくられたということなんですけれども、選考委員会のメンバーはどなただったんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"団体につきましては、長期基本計画を検討しているときにも、そういう関係団体がありましたので、そのときの団体からちょっと絞らせていただいたという形です。","id":"exchange-070"},{"speaker":"井上委員","kind":"質問","question":"わかりました。そのときに参加されていた公募委員以外の皆さんが、そろってなぜ私が選ばれたのかわかりませんという発言をされていたんですね。そういった、品川区が要項に関して言えば、区長が委任するというようなことになっておりますけれども、この次世代育成の協議会では、どのような説明をされて選考されたのか伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"そういう学識委員等の選考の基準というお話ですけれども、次世代育成のこの協議会につきましては、去年の段階ですと、もう少し大型の協議会ということで考えている旨をちょっと発言した覚えがあるんですけれども、その後いろいろ検討していく中で。","id":"exchange-071"},{"speaker":"井上委員","kind":"質問","question":"ですから、やはり公募委員の方たちがこれから積極的にかかわろうと思っているときに、学識、正副委員長の方はそういう感じではなかったですけれども、そうではない、現場の意見としてというところを積極的に伺いたいということであれば、もう少し事前にきちっとした、この会がどういう会であって。","respondent":"榎本行財政改革担当課長","answer":"それで、そういう検討をした中で、各委員からいろいろご意見をいただいておりますので、今回はそのご意見をもとに、今年度の世論調査の中では、もう少しボリュームをアップした形での満足度の調査を今やって、集計をしています。","id":"exchange-072"},{"speaker":"井上委員","kind":"質問","question":"その後は活動されていないというようなお話もあったので、今後の外部評価委員会を前回の再任とするのか、新たな組織としてされるのか伺いたいと思うんですけれども、品川区の審議会や推進委員会なんかは全般的に委員の再任は妨げないということになっていまして、何回受けても制限はないというようなことが多いようですけれども、今回の場合には、前回のこの外部評価委員会の皆さんの答申を受けながら。","respondent":"榎本行財政改革担当課長","answer":"団体の代表につきましては、総務委員会のほうで報告したときに、やはりそういう方は意見を発言する機会がほかの場でもあるんではないかというようなご意見もいただきまして、ちょっとそういう団体はどういうふうにしようかというのは今検討中です。","id":"exchange-073"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。今回の答申の中でも生かされるような区民からの意見、これを一応出した中で、区民としてパブリックコメントを求められるような仕組みづくりをぜひしてほしいということを要望して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"築舘委員","kind":"質問・要望","question":"１０８ページの青少年対策費と、１１１ページの企画調整費のところの事業部支援プロジェクトについて質問したいと思います。協議会の事前に。その内容というか、そのときの状況を簡潔に教えていただきたい。そのときそのときがあるでしょうけれども。それから、１１１ページのほうは、事業部支援プロジェクトというのがどういう内容なのかというのを、これも簡潔で結構ですが教えてください。","respondent":"田村地域活動課長、榎本行財政改革担当課長","answer":"それと、もう一つの品川区の青少年問題協議会の幹事会というメンバーですが、実際には、全体の青少年問題協議会のうちから特に主だっては官公署を中心と。事業部支援プロジェクトですけれども、これにつきましては、事業部制が始まった後、各事業部を円滑に運用していく中で活用する中で。実際の幹事会でどのような内容ということで、青少年問題協議会に当たりまして、事前に先ほど申し上げたメンバーの中で議題調整等。","id":"exchange-075"},{"speaker":"築舘委員","kind":"質問","question":"それとあと、次の、もう一つのほうの事業部支援プロジェクトは、品川都市白書をつくるので、各事業部からそれぞれ若手の精鋭が出てきて、そしてこの品川都市白書のたたき台をつくっているというのをちょっと事前に聞いたんですけれども、これは大変いいことで、やはりそれぞれの事業部でいろいろ部長、課長たちはそれぞれ熟知しているということはあるかもしれないけれども、将来を担う若手のホープが。","respondent":"田村地域活動課長、榎本行財政改革担当課長","answer":"ご指摘のとおり、やはり青少年の健全育成、もう言い古された言葉かもしれませんが、家庭、学校、地域、行政という４者が連携し合いながら情報交換をしながら。やはり７回の検討の中では、いろいろとそういうものをまとめまして、これから今度は平成１６年度については、そういうものをさらにブラッシュアップして進めていきたいというふうに進めているところです。","id":"exchange-076"},{"speaker":"築舘委員","kind":"意見","question":"地域活動課が中心に青少年対策を一生懸命やるということがこれからも大切なことだと思いますが、地区委員会ですね、それぞれ地区の、このメンバーとか、行事がちょっとマンネリ化しているんじゃないかとか、年齢が高齢化しているんじゃないかとか、専門性がないんじゃないかというような、そういった意見もあるんですが、全体的にそれぞれ地区によってそれはバランスがとれているところ。","respondent":"田村地域活動課長","answer":"それで、年齢的にもいわゆる若い方、３０代、４０代の方もＰＴＡを通じて参加していて工夫しているのが徐々に効果が出てきているのかな、そのように感じております。","id":"exchange-077"},{"speaker":"築舘委員","kind":"質問・要望","question":"この事業部制というのがそれぞれの意識を高めて、自分たちのということと同時に事業部を離れた全体としての横のつながりでの将来を見つめるという作業もこれは大事なことなので、そういう意味の意識を若い職員の人にもしっかりと持っていただくような、そういった試みをどんどんやっていっていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"山村委員","kind":"質問・要望","question":"中途半端にシルバーセンターを移行するんでしたら、全面１階部分はシルバーセンターにするですとか、そういうふうにシルバーセンターのほうの機能を拡充したほうが私はいいと思うんですが、この葬儀をわざわざ、もう臨海斎場もでき、今後要望が減っていくであろう相互機能をいまだに維持する信条か何かがあるのか、その理由があるのでしたら教えていただければと思います。","respondent":"田村地域活動課長","answer":"平塚橋会館のことについて、ご説明いたします。区民委員会でもご説明しましたように、今回、平成１０年６月から平塚橋会館を開館して、その後、平成１６年まで利用状況等をご報告させていただきました。","id":"exchange-079"},{"speaker":"山村委員","kind":"質問","question":"この葬儀が一緒に行う場所にシルバーセンターを移行するということに対して、中延シルバーセンターに通われている方には説明されているのかということと、私は、どうしてももう葬儀の必要性はないと思うんですが、私を納得させていただけるだけの理由を言っていただければとてもうれしいんですが、よろしくお願いします。","respondent":"蓼沼高齢事業課長","answer":"既にその中には、平塚橋会館を今も利用しているんですけれどもと前置きして発言された方も何名かいらっしゃいまして、そうした方たちも含めて、特に葬儀についてのご意見等はございませんでした。ご理解していただいているというふうに考えてあります。","id":"exchange-080"},{"speaker":"山村委員","kind":"質問・要望","question":"今後も見込みもないわけでして、もし来年度これでシルバーセンター等が一緒になって、それでさらに説明では優先予約のほうも取り消されるということですから、その優先予約を取り消されることによって、ましてまた葬儀件数も減ってくると思うんです。どういうふうになったら、そこら辺の見直しをされるのか、教えていただきたい。","respondent":"田村地域活動課長","answer":"区民委員会でもご説明しましたが、いわゆる斎場の優先の手続というのは地域活動課に所管替えしたときに、ですから、平成１５年度４月からもう既にそれは条例改正をして見直しております。","id":"exchange-081"},{"speaker":"山村委員","kind":"質問","question":"今後はもうちょっと青少年問題協議会自体を活発化させようというような意識があるのか、そういう意味では、委員として質問したいんですが、資料等を事前配付とか、そういうのはしていただけるんでしょうか。その本日、大体その日に配付なものですから、そのときにすぐ見て質問をしろと言われても、全然なかなか難しいものでして、事前配付とかがあるんでしたらできるかどうか教えてください。","respondent":"田村地域活動課長","answer":"それで、委員会の中での活性化は、決して事務局として委員の意見をいわゆる抑えているわけでは全くございませんので、やはり委員各自がそれぞれの立場で議題等があって、あるいはその他何かありますかという形で振っておりますので。","id":"exchange-082"},{"speaker":"山村委員","kind":"質問","question":"実際もう１５年後にじゃあほんとうにケーブルを埋設して、一々その事業をやる必要がなくなったときというのは、私はほんとうにその可能性はかなりあるなと思うんですが、それを見越して今何かやられようとしているのか、要するにケーブルテレビという形態ではなくて、もうデジタルのほうにある程度会社の構造自体、やること自体を移行すべきだと思う部分もあるんですが。","respondent":"中尾根企画部長","answer":"それで、もう一つは、高度の利用の仕方のニーズに対して、例えばインターネットを結びつけるだとか、そういう方法を同時にサービスとして提供していく、この二つの道を同時に追求するという方法を今後の地域での展開の軸に据えたい、こう基本的には考えているところです。","id":"exchange-083"},{"speaker":"山村委員","kind":"意見","question":"ちょっといまいちよくわからないのですが、要するに地方局であるのでしたら、別にその番組をデジタル放送下で流すことは可能でありますし、私が言いたいのは、もうケーブルを埋設してつなぐことよりも、もう光ケーブルなどを利用してデジタル放送を流すほうがよほど安上がりになると思うんですが、要するに、そこら辺についてどうお考えなのか、お答えいただけますか。","respondent":"中尾根企画部長","answer":"せっかくここにあるものについて、先ほど言いましたように放送と通信の分の融合化がたとえ現象として世の中にできたとしても、地域での活用の部分、これを最大限今後は活用していく、この道が残されて、これこそ今後品川区が目指す道ではないか、このように考えているところです。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、総務費全体に関連して質問をしたいと思います。さきの本会議において、青年の雇用問題を取り上げさせていただきましたが、今後の新しい事業の実施に当たって、区の基本的な姿勢や現状の認識について伺いたいと思いますのでよろしくお願いいたします。本会議の中で区長は、前向きに考えている、しばらく待っていただきたい。前向きに検討することはほんとうに歓迎いたします。","respondent":"日下部産業振興課長","answer":"就職をしてから３年以内に離職をする割合が非常に高い。","id":"exchange-085"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたかったのは、青年の意識が多様化している、これが雇用を悪化している、その意識とはどういう意識なのかということを伺いたいんです。そこだけ１点お答えください。","respondent":"日下部産業振興課長","answer":"意識の問題ということについて限って申し上げますと、やはり特に国のほうが若者の自立・挑戦プランということで指摘をしておりますけれども、今の若い方たち、とかく将来についての目標を立てることがなかなか難しい。","id":"exchange-086"},{"speaker":"中塚委員","kind":"意見","question":"この１２年間で正規労働者と言われる方々は１７８万人減少しています。一方で、パート、アルバイトを含める非正規労働者はこの１２年間で６１５万人、１.６倍に膨れ上がっています。よく、若者の意識の話をしますと、昔の若者はどうのとか、いつの時代も言われますけれども、最近の若者意識がそうであるならば、昔の人と今の人は一体どんな意識が違うのか、あわせて答えてください。","respondent":"日下部産業振興課長","answer":"したがいまして、単純に若者の意識の問題だけではなくて、これは国のほうも指摘をしておりますように、社会的な背景としましては、求人の減少であるとか、パート、アルバイト化の問題であるとか、そういった意識の問題にあわせて社会システム上の問題もかかわっている。","id":"exchange-087"},{"speaker":"中塚委員","kind":"質問・要望","question":"このことを挙げて、要は５２万人のもニートと呼ばれる若年無業者が働く意欲がない、このことをご紹介して、みずからもそれが正規の事実です。こう答えているんですね。こういったことを話していました。改めて、品川区はこのニートと呼ばれる無業者が増えている原因、またこのフリーターが増えている原因は一体何だととらえているのか、教えていただきたいと思います。","respondent":"日下部産業振興課長","answer":"そのような無業者の状態を指しているわけでございまして、そういった点をかんがみた場合、どうしてもそういった一つの意識、意欲の問題、この辺を抜きに語ることはできないだろう、このように理解をしているです。","id":"exchange-088"},{"speaker":"中塚委員","kind":"質問・要望","question":"みずからの責任を投げ出しているんじゃないかと思うんですね。品川区は具体的にどういう調査をしてどのようなふうにつかむ努力をしているんですか。質問いたしますけれども、この品川区はこのニートの意識やフリーターの意識などをいろいろ言いますけれども、じゃあ具体的に青年の実態を直接どういった調査を行ったんですか。青年の仕事に対する実態調査などを行ったことがあるんですか。教えてください。","respondent":"日下部産業振興課長","answer":"実態の調査ですけれども、区のほうとして直接実態の調査等を行ったということはございません。","id":"exchange-089"},{"speaker":"中塚委員","kind":"質問","question":"正確に実態調査もせずに、みずから新聞やマスコミや政府の答弁やいろいろな白書や、これだけで青年雇用対策を前向きに実施するというのであれば、一体どんな中身なのか、きちんとまず実態を把握してから、青年の仕事の状況をつかまなければ、この問題を解決することは決してできないと思いますので、改めて直接青年の実態を調査すべきではないかと思いますけれども、いかがでしょうか。","respondent":"山田区民生活事業部長","answer":"今るるご質問がございましたけれども、雇用問題に関して、これは国が責任を持って対応していくものだと認識しています。ですから、個別の部分で実態調査をするという考えはございません。","id":"exchange-090"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、国と都と連携をとって、いかに安定した仕事をつくっていくのか、これが青年雇用対策ではないかと思うんですね。そうでなければ就職相談会や面接会、本会議の質問の中では相談カウンセリング、就職支援を行う、こういう検討をしていくと言っておりますけれども、身近な区ができること、一体どんなスケジュールで、一体どんな内容を今後はやっていこうと考えているのか、教えていただきたい。","respondent":"日下部産業振興課長","answer":"これも本会議でご答弁申し上げましたように、現在いろいろ具体的な検討を進めている状況ですので、これにつきましては、今後その辺の具体的な中身がまとまった段階で、またその辺は明らかにしていきたい、このように考えております。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"平成１５年度には地域防災計画の修正がされました。これは当然直下型地震ですとか、合わせて風水害等、いろいろさまざまな対応を防災の計画をしているということで、そういうことなんですけれども、昨今非常に風水害が極めて目立つ状況でして、当然この防災計画ということですから、何に力点を置くかが当然限られた予算なので厳しいと思うんですが、大変区内においても特に水害が多いなと見えるわけです。","respondent":"久保田防災課長","answer":"この主体を担うのが防災課と、それからまちづくり事業部の下水道河川課、それから道路公園課ということになってありますけれども、一次非常配備体制が設置されますと、まちづくり事業部と区民生活事業部が協力して態勢をとるというような形になってあります。","id":"exchange-092"},{"speaker":"本多委員","kind":"質問・要望","question":"町会、自治会長ですとか地域センターなどですとか、それぞれ伝言板、テルてる両方、町会には２０７台、地域センターや関係機関には２３台ということで、それぞれ配付をされているということで、いざというときのための情報網ということなんですが、日ごろの日常の活用について、それがどのように生かされているのか普段の活用についてお聞かせいただきたいのと、それと、その後の住民。","respondent":"久保田防災課長","answer":"特に町会長の皆さんは、災害対策が起きたときには防災対策本部長として、これは私どもと一緒に連携をとって対策をとっていただくというような立場ですので、特に災害対策本部あるいは区役所との連絡を密にしなくちゃならないと、こういうことから防災伝言板を配備して。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、防災訓練なんですけれども、年々各方面からの参加、連携が増えてきて整備されておりますが、今後の防災機関としての拡充についてが一つと、それと、現場での医療の想定についての、医師、薬剤師、看護師との連携をどのように考えているのかと、派遣ボランティアについての考え方、これについては派遣と受け入れということで教えていただきたいと思います。","respondent":"久保田防災課長","answer":"従来は訓練に参加した方の、もしぐあいが悪くなった方がいらっしゃったら、その応急診療に当たるということが主だったんですけれども、最近は、地震が実際に起きたということを、起きるということを想定しまして、トリアージ訓練等を実施しております。","id":"exchange-094"},{"speaker":"中島委員","kind":"質問","question":"午前中にも西本委員のほうから私立幼稚園に関しては質問をされておりましたが、この私立幼稚園というのは、今品川区で２４園、そのうち７園が預かり保育をしていると認識しているんですが、ここで振興費補助金というんですか、この辺のお金のまず配分、これはこういう預かり保育をしている、していないということではなく補助金が出ているものなのか、この辺の配分を教えてください。","respondent":"金子保育課長","answer":"私立幼稚園の幼稚園教諭の給与の問題ですけれども、私立幼稚園教諭の平均の給与が、私どもで聞いているものは、年額で３９０万円余ということで聞いてあります。","id":"exchange-095"},{"speaker":"中島委員","kind":"質問","question":"青少年問題協議会です。先ほども質問が出ておりましたけれど、これは区長の附属機関ということで私は伺っております。私も、この中にかつて入ったこともあります。人は亡くなったら、死んだらどうするかと聞いたときに、ほとんどの生徒が再生する、生き返ると答えたデータもあります。当然ここには報酬が支払われていると思いますが、そこら辺の意識啓発はどのようにされているんでしょうか。","respondent":"田村地域活動課長","answer":"先ほどのご質問にお答えしたとおりなんですが、やはり、メンバー的に会長は区長ですけれども、それ以外に人数が５８名ということで、それぞれの地域の代表の方、あるいは官公署の役員の方というんで、私ども初めて出席させていただきましたが。","id":"exchange-096"},{"speaker":"中島委員","kind":"質問・要望","question":"最後に選挙費なんですが、この中に、明るい選挙話し合い７４８回というのがあるんですね。それから、話し合い助言者研修、これが研修会と地区教養講座、３回、８回行われているんですが、どのような研修をされているんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"それで、その話し合い活動を進めるに当たって、明るい選挙推進委員の方には入って一、二年の方から５年から１０年というような形で、初心者の方を対象とした、２年未満の方をおおむね対象とした明るい選挙推進委員の活動はどうあるべきかというような。","id":"exchange-097","title":"議員研修会の内容と所要時間"},{"speaker":"中島委員","kind":"質問・要望","question":"選挙に対する啓発活動、それから寄附の禁止とか、こうしたものももちろん大事なことで、しっかりやっていただきたいと思うんですが、選挙当日のこういった方たち、また、選挙管理委員の方たちは、まちの中にどういう目を光らせているのかということを一つお伺いしたいんです。え、これはおかしいと思いました。こうしたことの取り締まりは、どのようにお考えになっているか、ご質問したいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、こういった事例につきましては私どもで現認できませんので、警察の、まさに公職選挙法を担当しているところの担当係にすぐ通報いたしまして、善処方警察のほうにお願いしています。","id":"exchange-098"},{"speaker":"中島委員","kind":"質問・要望","question":"一部の方からにらみつけられたり文句を言われたりしておりますが、私は、これは大事なことだと思いますので、ぜひ選挙当日前に、警察の方ときちっとこの辺のところは協議をしておいていただきたい、このように要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"本間委員","kind":"質問","question":"そこでお尋ねしたいと思います。この部分、大変交通の便が何とかならないかということを頭に入れているわけです。何を言いたいかと言いますと、このような部分を、非常によろしい部分を何とか品川区の中で橋渡しする方法は何かないのか、交通の便、それから自然豊かな部分での農園等々のこの橋渡しを何かすることができないのかということですが、何かお考えはありますでしょうか。","respondent":"長田区民課長","answer":"それと、実は早川町のほうでは３年ほど前だったと思いますけれども、南アルプス号というバスを買いました。このバスは、町長いわく品川区との交流のために奮発をしたというようなことで説明をいただいております。","id":"exchange-100"},{"speaker":"本間委員","kind":"質問・要望","question":"現在も努力をされている部分は承知しておりますが、一層新たな、何といいますか、接点を求める方法をお願いしたいというふうに思います。現地の人たちは非常に素朴な、町民のまち場の人たちにお聞きしますと、自分たちは何をしていいのか、皆さん方のご意見をください、こういうことをよく言われますので、そういう部分を大切にしながら、私たちももっと開拓していくべきですね。次に行きます。","respondent":"金井環境課長","answer":"エコスポットのお話ですけれども、これは、品川区の商店街連合会が、区が一部助成をしておりますが、商店街連合会として実施をしているです。それで、区はその一部を助成をしている、こういうことです。","id":"exchange-101"},{"speaker":"本間委員","kind":"意見","question":"どうしてもっと繰り返し繰り返し中止の案内をできなかったのか、なぜかと言いますと、午前中は時々晴れたり小雨が続いたからです。そのようなことで、きちっとした中止なら中止の案内を町会長に連絡するだけでなく、地域のほうにきちっと連絡をとる方法はなかったのか、屋外防災無線について、繰り返し繰り返し放送するなど手だてはなかったのかということについて、お尋ねします。","respondent":"久保田防災課長","answer":"これは、防災協議会のほうでその中止のときの連絡体制、これはしっかりと今後やっておきまして、単に防災無線だけではなくて、いろいろな方法を使って中止のお知らせが、もし中止になった場合には十分にお知らせしていきたい、こんなふうに考えております。","id":"exchange-102","title":"町会・自治会支援"},{"speaker":"本間委員","kind":"質問・要望","question":"最後に１点だけお尋ねします。学校等の避難所機能の充実の部分ですけれども、ちょっとこれは時間がないので問題点の部分だけにしておきますが、実際の訓練さながらにやっているところもあります。さらに一歩足を踏み出していただきたいというふうなことについて、お伺いします。ご意見を。","respondent":"久保田防災課長","answer":"学校避難所の機能等も含めてですけれども、いろいろな課題、問題点、まだまだあります。そういう点では、この学校避難所連絡会議を重ねて開催することによって、その辺の解消を図っていきたい、こんなふうに考えております。","id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"防災対策なんですけれども、自分たちのまちは自分たちで守るということで、町会でも防災訓練とかをよく行っていますけれども、町会によって、ミニポンプなどの整備だとか、それから訓練の中身だとか回数とか何かについても随分違うと思うんですけれども、ここら辺の実態がどうなっているのかということと、区としてそれをどう考えているのかということを一つお聞きしたいのと、二つ目は。","respondent":"久保田防災課長","answer":"町会によって、ミニポンプとかあるいは町会独自の訓練の実態ですけれども、全体的にはちょっと今数字を持ち合わせていないんで、お答えできないんですけれども、確かに町会によってミニポンプ隊を組織しているところ、区民消火隊を組織しているところ、全体の数で言いますと。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"防災公園の整備についてなんですけれども、これをどういうふうに考えられているのかというふうなことで、ちょっとお聞きしたいんですが、実は町会のほうからも幾つかのところから、その防災公園を充実してほしいというところで、具体的にかまど用のベンチ、これは日ごろはベンチに使っていて、上のふたをあけるとかまどに使えるという、そういうふうなかまど用の、かまど兼用ベンチというんですか。","respondent":"久保田防災課長","answer":"同じくマンホールの仮設ということですけれども、これは、今現在学校避難所においては仮設便槽というのをそれぞれつくりまして、ここにはある程度の避難所生活に耐えられるようなトイレの対応というふうにやっておりますけれども、公園に仮設置するのは。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうに区としてもさまざまな取り組みをされているというふうなことは私どもはよくわかっております。そして、そのマイクの音が割れてしまったりとか、そういう不便な状況があるんですけれども、それをぜひ充実してほしいというふうに思うんですけれども、ここのところをどういうふうな状況になっているのか、そしてまた定期的な点検というふうなものをどうしているのかをお聞かせいただきたいと思います。","respondent":"田村地域活動課長","answer":"施設全般ということなので、地域センターに限ってちょっと私のほうからご答弁しますが、やはり備品関係については、その都度利用者のほうから地域センターを通じて声が上がって、やはりそういうような不備があれば、暫時取り替えなり改修していきたい。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところでは、ぜひ使いたいときに使えるような、もうちょっと施設の区民が使える施設を増設してほしいというふうに思うことが１点と、それからあと、今ある施設の有効利用というふうなところで、ぜひ去年の第４回定例会の中でも宮崎議員が質問していますけれども、第３庁舎の区民への開放をぜひお願いしたいと思うんですけれども、この点について、第３庁舎の６階の前の労政講堂と言われていた。","respondent":"榎本行財政改革担当課長、鷹倉経理課長","answer":"必要なときにとれないということに対しては、施設予約システムで似たような規模のところで探せる検索システムを用意してありますので、そのようなそこの地域を限定して、何人ぐらいの規模の会議室であれば。年間利用率等の数字は個別には特に押さえてございませんので、お答えできませんが、セキュリティーの問題云々という形の答弁につきましては。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区民への開放をしていただきたいなというふうに思います。１分しかなくなってしまったんですけれども、最後に区民ギャラリーなんですけれども、あそこが屋外掲示板をぜひつけてほしい、何をやっているのかというのが見えないというふうなところがありますので、屋外掲示板をぜひつけてほしいという要望が出されていますけれども、いかがでしょうか。","respondent":"諸岡区民生活事業部副参事","answer":"大井町駅前ということで非常に利用率が高いのですが、駅前の看板の下に催し物案内、これを設置したいということで、ビル管理者、それから入居店舗のほうに交渉を行いまして、一応の了解をいただいておりますので、デザイン、それから経費面での検討に入っているところです。","id":"exchange-108"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、大都市事務ということもしておりますが、よく出てくる役割分担、大都市事務の中で、上下水道、消防という話がありますが、この役割分担の考え方、区としてどのように今のところ、この上下水道、消防も含めて、大体の大枠は知っているので簡潔にそこら辺の上下水道と消防とか、区の役割分担をどうとらえているかというところだけを教えていただきたいと思います。","respondent":"田村地域活動課長、市岡企画財政課長","answer":"それと、取り組みについてですが、建設時あるいは登記、そのような助成制度は設けておりますが、それについての特に区としての対応はございません。たまたま平成１５年度の決算を見ると、プリスクール西五反田を含めて、委員ご指摘の点が施設は補助金が全部ついているものですが、逆に申しますと、区のほうで実施計画。","id":"exchange-109"},{"speaker":"石田委員","kind":"質問・要望","question":"区長もよく言っていらっしゃるように、税源移譲をして、我々の市町村民税を使っているわけですから、そういうところのデータベース化をして、そういう情報は区には必ず見てわかるぞというものを訴えていくなり、行政の皆さんが答える部分でも、そういうデータベースは必ず区が取るぞと、それぐらいは市町村民税を使っているのであれば、やはり法的な部分があったって。","respondent":"田村地域活動課長、高橋区長、市岡企画財政課長","answer":"現在、品川区には町会、自治会を含めまして２０６町会、そのうち会館を持っているのが７２ということで３５％の保有率という形になります。品川区は、ほかの区から比べますと、下水道はかなり下水道から委託事務を受けまして下水道の課を設けて実施をしております。例えば公共施設整備の計画についての附属機関その他いろいろなご意見と、それから区の政策決定の関係ですが、これは附属機関等を含めまして。","id":"exchange-110"},{"speaker":"石田委員","kind":"質問・要望","question":"区長のお話は、今のは非常に私もそのとおりだと考えていますが、基本的に、昔そういうところで都の事務だったよというところの話があって、基礎的自治体になったけれども、まだ内部団体みたいな考えを都は持っているというところがありますが、ぜひここは、そこら辺のところは都民でもあり区民でもある、そういう区民の方へサービスをしていくときに、はい。","respondent":"榎本行財政改革担当課長","answer":"総合実施計画につきましては、毎年度ローリングを重ねて、次にどういうふうにしていく、今後３年間どういうふうにするということで、各部からの計画が上がりまして、それに基づいて企画部のほうで調整をして最終的に区長決定をとるというプロセスをとっておりますので。","id":"exchange-111"},{"speaker":"石田委員","kind":"質問・要望","question":"最後にこれをお願いしておきます。いろいろな、それは課から上がってくるのか、部から上がってくるのかわかりませんが、それをすごく対応して、いつでもあげる体制でぱっとこういうふうにやりましたよという意味で、有効にこの約１８７億円ぐらいを使っていただきたいなと考えています。これはお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"藤田委員","kind":"質問","question":"昨日の朝日新聞でしょうか、路上禁煙に対する記事が大きく載っておりまして、品川区も現在の状況等が記事に載っかっておりますが、昨年の１０月からスタートいたしましたこの歩きたばこ防止についての事業に対する感想を、この１年間やってみてどうだったのか、それをまずお伺いしたいのと、それから、２点目の広報につきましては、区内在住、在勤の外国人に対する親切な区政の情報提供。","respondent":"田村地域活動課長、中川原広報広聴課長","answer":"その後、新聞にも報道されましたが、大崎駅周辺を含めまして五反田、大井町、武蔵小山、青物横丁と５カ所実際に地域美化推進地区として路上喫煙、同時にポイ捨て等を禁止区域罰則適用と、地域を拡大してまいりました。４点目は区政概要の中に英字表記しまして、数字とか区政の様子を冊子にしましてお届けしています。","id":"exchange-113"},{"speaker":"藤田委員","kind":"質問","question":"商店街も含めまして。外国人に対して。この３カ国ですか、外国人向けの生活情報紙。「英語」と表示しているんですけれども、やはり見ていますと、もうほんとうに品川区のこういうところはありますよというぐらいの、私は外国人に対する情報提供になっているんですけれども、むしろ、ここに外国人が知りたいような情報をもっと提供してあげてもいいんではないかと、こう思いますけれども、どうでしょうか。","respondent":"田村地域活動課長、中川原広報広聴課長","answer":"それで、現在まだ在庫が１５０枚ほどあるようですが、やはり今後のことを考えて、雨の日もあるということなので、引き続き千代田区だけではなく、そのようなほかの例も参考にして検討してまいりたいと、そのように考えております。そこで相談される内容等を盛り込みまして、ホームページの内容については必要な情報を盛り込んでいくようにしたいと思ってあります。","id":"exchange-114"},{"speaker":"藤田委員","kind":"質問","question":"そういうのをつくって。直でお聞きになってもご理解されると思いますけれども、やはり品川に住んでいて、どういう感想を持っているのか、どういう意見があるのか、自分がこれまで住んでいた例えばアメリカなり韓国なり、そういうところと品川区がどう違うのか、どうあるべきなのか、そういう建設的な意見を聞くような、そういう場を設けても私はいいんではないかなと思うんですけれども、いかがでしょうか。","respondent":"中川原広報広聴課長、田村地域活動課長、高橋区長","answer":"ちょっとこれについては申しわけございません、失礼いたしました。ただ、もう一度その張っている場所も含めて、区民に周知する方法を見直して検討してまいります。当然区長出ろというならそこへ出ますけれども、そのような方法がより私は国際的でいいのでないのかなという思いがしておりますので。","id":"exchange-115"},{"speaker":"藤田委員","kind":"質問","question":"よくわかりましたので、よろしくお願いしたいと思います。この路上喫煙につきましては１年を経過しまして、やはりこれから、ほんとうに新たな展開を私は示すべきだと思います。ですから、来年度の予算につきまして注目をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"須貝委員","kind":"意見","question":"私は、１１１ページ防災、１１２ページ区民保養所について、それから１１３ページ電算システム、あとは青少年対策地区委員のほうと、あと町会のほうを兼ねてやらせていただきます。最初に情報システムについてなんですけれども、先だって情報システム課マシン室のほうへ視察にまいりました。というのは、どなたか１人がカードを持っていますと、一緒に続いて入れば、その方も入れる。","respondent":"田中情報システム課長","answer":"普通は入退室の管理につきましては、入った人と出た人の数が合うように整合性のチェックをしていますので、２人入って１人しか出なければ１人が残っているということがわかるようになっております。なお、担当の職員がカメラでずっと入退室する人を監視しております。","id":"exchange-117"},{"speaker":"須貝委員","kind":"確認","question":"ですけれども、今そういうふうにビデオでも監視している云々はあるんですけれども、やはり、どこの企業でも必ずそこに入退室するときには最低ガードマンを１人でも置いて、１人ずつ確認、チェックする、だれだれが入ったとか出たとか、後で実際に人数を１人出る人が少なかったというんだったら、それはちょっとまずいんじゃないかと思うんですけれども、今後、もしそういう方向に持っていけましたら。","respondent":"久保田防災課長","answer":"そうは言っても一部においては、やはり聞こえない地域が残るというのは現実ですけれども、そのためには新しい通信手段を含めた災害情報の伝達については今後十分検討していきたいというふうには考えております。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問・要望","question":"どんな建物でもやはり老朽化してきます。例えば、今区の設定が大体５,０００円前後、１泊２食の設定になっていると思うんですけれども、じゃあ１万円のところだったら５,０００円補助する、そういうふうにすれば、行く人に対しての補助なんで、今後の維持管理費とか、今でも補助しているわけですから、維持管理費をさらに上乗せして補助すると、区にとってはずっと長年経費が相当加算でくると思うんですね。","respondent":"長田区民課長","answer":"保養所の運営につきまして、ご提案をいただきました。午前中の質問にもお答えをしたかと思うんですけれども、今後、検討していく中でも、委員の提案していただいた民間の旅館、ホテルを利用した上で補助金を出すというようなことも頭の中に入れて検討はしてまいります。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"三位一体のいろいろ話がありましたけれども、あらかじめ特定財源みたく決まっていて、それに使うんだ、使わなきゃいけないんだというんじゃなくて、各町会、自治会ごとにやりたいものがあったならば、それをどうぞ皆さん使ってください、そのかわり、ちゃんと事業計画と予算を明示してください、町会のことですから、そんなにきちっと云々ということはできないと思うんですけれども。","respondent":"田村地域活動課長","answer":"須貝委員の趣旨、若干取り間違えているかもしれないですが、町会は２０６町会あります。それで、地区委員はそれぞれの町会長の推薦で地区委員になっています。それで、区長が２年という形で地区委員で委嘱しています。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"それで、潮干狩りは、あれはかろうじてお子さんも来るけれども、その大人も一緒に来て、親子の交流の場としてはいいんですけれども、実際にそういう青少年対策地区委員という考え方をするならば、本来子どもに目を向けて、子どものために有効に使うんだということが大事だと思うんですけれども、実際にその辺、地区委員の現実とやっていることと。","respondent":"田村地域活動課長","answer":"ただし、区のほうで、いわゆる事業補助をして自主的な活動、一番地域に定着している方々ですから、ですからそれを阻害するような、あるいは前年どおりにやりなさいとか、あるいはこういう内容でやれというのは、まさに越権行為そのものなので、確かに地域センターのほうは。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"それも、真だとは思うんですけれども、じゃあ実際にお聞きいたしますけれども、本当にふるさとまつりとか運動会、そういうのが青少年の健全育成のためになっているとお思いでしょうか、それだけお聞かせください。","respondent":"田村地域活動課長","answer":"もともと、平成１６年度、平成１７年度の、ご存じかどうか、品川区の青少年の健全育成の基本方針というのが平成１６年度、１７年度２カ年にわたっての方針を先ほど来ご議論のある協議会のほうで決定をします。","id":"exchange-122"},{"speaker":"須貝委員","kind":"意見","question":"実際は、我々の地域だからかもしれませんけれども、中学生はＰＴＡなり中学校の先生が協力しようやということで、なっているんで、子どもが自主的に云々というのは、運動会等々もありません。やるところもあると思いますけれども、その辺お考えください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"私のほうからは事項別明細書２５ページ、用地特別会計に関連をして、それから成果報告書の１１３ページ、住基ネットに関連して質問をいたします。これは単純に土地購入の事実がなかったということだけではなくて、計上しているわけですから、品川区が支出をしなかったこと、用地特別会計の支出をしなかったことを成果として判断したと考えますので、そのことの説明を端的にお願いいたします。","respondent":"市岡企画財政課長","answer":"このことについては、平成１４年度のこの成果報告書をご配付、ご提出するときに簡単な説明書ですけれども、それをつけてご提出した、こういう経過があります。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"確認","question":"住基ネットワークのほうを質問します。多少の問題点がありますが、去年たしか予算特別委員会で指摘をさせていただいた封筒の問題とか、多少あったんですけれども、ここで確認したいのは、そのときにあわせて指摘をさせていただきました職員の３人の体制のことを指摘させていただいたと思います。そのことの対応をどうしたかということをお聞かせをください。そのことについての見解をお願いいたします。","respondent":"冨田戸籍住民課長","answer":"住基カードの見込みですけれども、国におきましては、当初３００万件ほどの発行が平成１５年度に、平成１５年８月から実施をしておりますけれども、３００万件ほど発行されるのではないかという見込みを立てておりましたが。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問・要望","question":"非常にある意味では総務省の要請で品川区が安全性が確認されたわけですから、今度はソフト的なところで、この情報公開等審議会のところが客観的に品川区の住基ネット等のシステムに対して評価ができているかということ、それから、品川区からこの情報公開等審議会に対して、住基ネットシステム等を評価していただくことをやっているかということ、そして。","respondent":"田中情報システム課長、中川原広報広聴課長","answer":"特に一定の報道の中で、「Ｓｕｉｃａ」や何かと住基カードと同じ規格を一つのカードで吸収できるようなシステムのカードの開発がＮＴＴで行われているという報道もされておりますので。情報公開審議会の件ですが、品川区の情報公開審議会は、住基ネットの条例ができましたときに、情報公開・個人情報保護制度の運営とともに。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"確認","question":"住基ネットという大きなデータベースの安全確保ですので、もう一つ確認したいというか、お願いしたいのが、総務省からの要請でその実験をやったことを踏まえた上で、全国一の安全対策をやるべきだと私たちは思っています。","respondent":"田中情報システム課長","answer":"それで、どういう内容の監査をやるかというようなことについてのガイドラインも示されているような状況になってきております。それで十分受けとめて咀嚼した上で、対応を考えていきたいというふうに思っております。","id":"exchange-127"},{"speaker":"宮崎委員","kind":"質問","question":"私は成果報告書１１０ページの情報公開についてお伺いしたいと思います。その前に、まず議員に対する情報提供の問題について初めに伺いたいと思います。この間、うちのほうで、この問題をずっと取り上げてきました。今回の本会議でも、教育委員会のところの情報提供の問題で取り上げました。ちょっと今時点で改めて区のほうの対応、その考え方について、まず初めにお伺いしておきたいと思います。","respondent":"中川原広報広聴課長、宮地総務課長","answer":"１０条により、非公開情報であっても裁量的公開が認められております。その決定につきましては実施機関が決定することになっております。総務課のほうで所管を振りまして、そしてまた所管のほうから区議会事務局のほうに回答が行くという、そのルールをこの間も皆さん方には守っていただきまして、私どものほうも着実に推進しています。","id":"exchange-128"},{"speaker":"宮崎委員","kind":"質問","question":"今まで、この前の予算特別委員会のときでは、これはいわゆる議員に対する情報提供のあり方というのはいろいろ議論になって、先ほど紹介したように区長の答弁になったというふうに思うんですけれども、今のお話ですと、今までの教育委員会の対応ですけれども、これは区議会事務局の調査係を通しても情報公開だというふうに言ったら、区長がせっかく区議会事務局の調査係を通せ、通してほしいという。","respondent":"宮地総務課長","answer":"それは、一般的に区民の方が情報公開制度を利用してとるよりも、さらにスピーディーに努力をして、その資料を提供するというふうにしているんだと伺いましたので、その点では随分努力をしているなというふうに考えているところです。","id":"exchange-129"},{"speaker":"宮崎委員","kind":"質問","question":"何を便宜を図っているのかよくわからないんですけれども、もしかしたら２週間後に出すか出さないかの可否を決めるというのがもうちょっと短くしているということぐらいしか私は思えないんですけれども、問題は、例えば意思形成過程の問題、情報でも前の区長の答弁では、そういう資料は区議会事務局の調査係を通せば、そういう隠匿しないで提供できる、だから。","respondent":"本間総務部長","answer":"これは基本的に調査係を通して、それで多くの場合、情報は議会に提供される。ただ、その要求の情報によっては、それぞれの所管の判断があるということでひとつご理解をいただきたいと思います。","id":"exchange-130"},{"speaker":"宮崎委員","kind":"質問","question":"それを私は意思形成過程の情報でもないし、実際にその場所に行けば見れるわけですよ。だから、ここのところがわからないんですけれども、もう一度ちょっとそこのところをお伺いしたいと思います。ちょっと心配なのは、今回、本会議のときの区長の答弁で、それぞれの部局に委任しているんだ、そういうようなお話だったかと思うんですけれども、ちょっとここの真意も合わせて伺いたいというふうに思います。","respondent":"市川庶務課長、古川教育次長","answer":"依頼をいただいたときに説明させていただいたかと思うんですが、提供依頼のあったものは、すまいるスクールの改修工事のいわゆる工事図面です。それで、工事図面は一般的に公表しているものではございません。その際に、区長のほうの答弁につきましては、これは議事録を見ていただければ、一番おわかりいただけるかと思うんですが、区議会事務局の調査係という、そこを通して出していただければ、うちのほうで統一的な対応はできますので。","id":"exchange-131"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今のご答弁は、ちょっと大分すりかえだというふうに思います。今の区長の答弁をちょっと先ほどから紹介していますけれども、流れを言いますと、その前に助役が答弁しているんですよね。私は、この予算特別委員会で区長が答弁したこの内容で、区長はちょっと全体きちっと仕切っていただきたい。そのリーダーシップを発揮していただきたいと思うんですけれども、いかがでしょうか。","respondent":"高橋区長","answer":"そういうふうに申し上げましたのでございまして、じかに議員がそれぞれの部署に行って、あの書類くれ、この書類くれと言っても、それはだめですよということをお話ししたわけですが、それでよろしゅうありますか。そういうふうに申し上げたわけですが。","id":"exchange-132"},{"speaker":"宮崎委員","kind":"質問・要望","question":"あくまで議会と執行部の関係は、やはりしっかり行政はチェックを受けるということで、必要な資料は出すという、それがやっぱり正々堂々とした議論になるし、それがこういう行政に今求められているというふうに私は思います。そうしたら、まだ議会で決まっていないんでまだだというふうな話だったらしいんですけれども、一体どこがどうなったら出すのかということをお聞きしておきたいと思います。","respondent":"高橋区長","answer":"そういう場合にはお出しはできませんよ、こういうわけでございまして、今の保育料の値上げでも、値上げをするかしないか、今検討している段階では、とても情報公開の対象にはなりません。","id":"exchange-133"},{"speaker":"川西委員","kind":"質問","question":"一つ目は区政アドバイザー会議、そして、これと同じように、きらめきとーくタウン、この二つについて伺います。短い期間ですが、これまでの実績と、そして来年度予算に向けて何らかの形で要になるようなことがあったら教えてください。","respondent":"榎本行財政改革担当課長、中川原広報広聴課長","answer":"それからあと、第２回目につきましては、第三次長期基本計画のほうの説明ということで、今までの基本計画の中でやってきた成果についてのご説明をしまして、その中で話題になったのが民間活用についてですとか、環境対策について。それは、区長の中でどう受けとめていただいているかはちょっとわかりませんが、すみません、余計なことを言っちゃいまして、それで、２回目、３回目が終わりました後、それぞれ要望につきましては、所管に即日、翌日とか伝えまして。","id":"exchange-134"},{"speaker":"川西委員","kind":"質問","question":"それで今後もできるだけ、回数を地域的に配慮しながら計画実施してほしいと思います。それから、品川区の区政運営というのは、区長の大変な実力と個性、強力な個性で独自性のある区政運営というのはもうずっとこの間やっていらしたと思うんですが、こういう専門家の方からアドバイスを受ける必要があるのかなとこの事業を設定されたときに思ったわけですが、その辺についてのお考えはいかがですか。","respondent":"榎本行財政改革担当課長、高橋区長","answer":"区政アドバイザー会議の設置のときの考え方ですけれども、やはりこれは総合実施計画事業としても区政アドバイザー会議の開催ということで入れさせていただきましたように。これからもそれぞれの皆さん方のご意見を真摯に受けとめまして、初心に返って行政をしてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-135"},{"speaker":"川西委員","kind":"質問・要望","question":"時間がないので次に移りまして、二つ一緒に簡単ですから。地域センターの管理運営について、この事務事業評価の中で、行政事務については再検討していく、この中身を教えていただきたい。それから、決算特別委員会で発言することかどうかわかりませんが、その次には大崎の総合体育館の跡地利用についての区の考え方を教えていただきたい。","respondent":"田村地域活動課長、榎本行財政改革担当課長","answer":"行政事務のあり方ということで、当初、先ほどもちょっとお話ししたんですが、平成１２年に出張所から地域センターに名称変更と同時に行政事務をできるだけ縮小して地域事務に移行しようという形で名称変更も含めまして検討しました。その中で検討していくということなんですけれども、その体育館の部分がそういう計画の中で権利としてありますので、その活用をどういうふうにするかをこれから検討していくという形です。","id":"exchange-136"},{"speaker":"川西委員","kind":"質問・要望","question":"できるだけ、せっかくある区有財産の権利ですから、区の今後の施設活用、それから将来夢のあるような利用ということを考えていただきたい。売ってしまって積立金にするようなことは寂しいことだと思います。ここで要望しておきます。","respondent":"田村地域活動課長","answer":"まだ具体的に開発中なので、具体的な内容まで確定しておりませんけれども、基本的には今やっている内容を処理の仕方がかわる、そのように理解しております。","id":"exchange-137"},{"speaker":"三上委員","kind":"提案","question":"成果報告書１０９ページの歩きたばこ防止キャンペーン、それから、１１０ページのＣＡＴＶに関して、それから、１１２ページの平塚橋会館についてお伺いします。そのときのことを取り上げて、そして私どもはいろいろな事業が展開できるでしょうということで、いろんな具体例を挙げて、そして質問し、提案してまいりました。","respondent":"田村地域活動課長、中尾根企画部長","answer":"その間の取り組みですが、平成１０年度開設して平成１３年度に備品関係ではマイク、アンプ、平成１４年度ＣＤラジカセ、平成１５年度、テレビ、ビデオデッキ、あとは平成１５年度はトイレの増設という工事を実施したものです。大まかなイメージをしますと、ＣＡＴＶのネットワーク、これを使いまして、住民との間での行政、災害での情報であるとか行政広報での活用、それから、中小企業間では当然ながら店舗情報であるとか、サービス。","id":"exchange-138"},{"speaker":"三上委員","kind":"提案","question":"歩きたばこの件ですけれども、朝７時半から９時半、夕方５時半から７時半というのは、この夕方の時間帯、私は武蔵小山の商店街に近いところにいるもんですから、このエリアの中ですよね。大体夜の８時から９時ぐらいにかけて、酒を飲んだ人が表に出てくる。ですから、こういう見張りをしているという言い方は悪いですけれども、そういう人がいるという時間帯は、それは捨てないですよ。","respondent":"田村地域活動課長、中尾根企画部長","answer":"しかしながら、これを繰り返しますと２４時間監視体制ということになりますので、やはり特に武蔵小山関係、商店街について、同じ区民生活事業部の中に産業振興課もありますので、ちょっと連携して。それはそれだけさまざまな問題があります。そのことについて提案されているということは十分わかっておりますが、全力を尽くして今後とも取り組んでまいりますので、ご理解のほど、よろしくご支援をお願いいたします。","id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"平塚橋会館だけ要望が、もうそれだけではありませんよ。とにかく障害者用のトイレの水洗用ボタンが、押すと水がとまらなくなる。それから、音が漏れる。今年の夏、あの暑い最中、扇風機を持ってきて使ったとか、それから、駐車場の電灯がつかないとか、要望はいろいろあると思いますよ。こういうような要望を発信している側があって、それを受けとめている方がほとんど手をつけないで放っぽり投げてきた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"原委員","kind":"質問","question":"もう１点は、総務費全体にかかわることで、款別の執行状況なんですが、ここの不用額と執行率の問題で、執行率は９５.８％というのは全体的には出ているんですが、不用額も３億９,２１９万８,０００円ということですけれども、その内容を見ると、総務費の約１５事業に関しまして、事務事業に関しまして、予算額と執行額に３０％以上の差があるというふうに監査のほうから報告が出てきておりますが。","respondent":"長田区民課長、市岡企画財政課長","answer":"そういったことで、品川区主催のツアーも数多く実施をしています。そういった中での事務経費がかかっているというようなことで、職員が行く回数もかなりの数の開きがあります。総務費についてに限ることではありませんが、いろいろな理由で不用額が出てまいりますが、総務費に関して申し上げると、一番大きな不用額というのは、やはり光熱水費、例えば総合区民会館の電気、ガスの使用料の減。","id":"exchange-141"},{"speaker":"原委員","kind":"質問","question":"先ほどの不用額のほうですけれども、形とすれば、ほかの款まで入ってしまいますけれども、平成１３年、１４年、１５年と、約３６億、４４億、３８億ということで、かなりの金額の不用額を出しているということなんですが、これは、この範囲内ということで、いろいろと状況的には許せるものなんでしょうか。","respondent":"長田区民課長、市岡企画財政課長","answer":"それで、この延長につきましては、常々山北町との交流の問題点、こういった部分は運営協議会等を中心に検討をしてまいりました。そういう意味では、これは毎年のことですけれども、この不用額については綿密な原因分析を通して経費の組みかえをすることと、こういうのを予算編成方針の中で出しています。","id":"exchange-142"},{"speaker":"原委員","kind":"質問・要望","question":"不用額のほうなんですが、これは今平成１３、１4、１５年度と出させていただいて、大体同じような形で各款のトータルは不用額として出ているわけですけれども、ある意味では行財政改革のあらわれの一端なのかなというふうな考えもできるわけですけれども、この予算の中で、もう少し不用額を縮めるとか、あるいはこのままでいいのかどうかも含めて、ちょっとお考えだけ聞かせていただければ。","respondent":"市岡企画財政課長","answer":"この数字自体は一般的に申し上げてそれほど高い数字ではございませんので、このこと自体に問題があるというふうには考えませんが、問題は、刻々毎年、やっぱり施策とか経費の内容というのは変わってまいりますので、それに応じて前例踏襲ではなく、適切に組みかえを行って。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/180055?Template=document&Id=1230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":121363,"voices":340}},{"id":"h16-20041007-4","meetingId":"h16-c-settlement","date":"2004年10月7日","dateIso":"2004-10-07","committee":"決算特別委員会","time":"午前１０時０５分～午後６時０９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"おはようあります。私は今日、１１６ページ、暮らしの福祉インフラ整備事業、それと１１７ページ、視覚障害についてお伺いしたいと思います。本年度は平成１４年度に比べますと半分ぐらいで、平成１４年度は６,１００万円、今年、平成１５年度は３,４００万円余、補助金のほうも１,０００万円ばかり減っておりますけれども、そこのところの減った仕組みといいますか、流れの説明をお願いしたいと思います。","respondent":"早津高齢福祉課長","answer":"それからもう一つは、平成１４年度のこの事業にかかわる痴呆性高齢者に関する検討経費というものが平成１４年度に１,０００万円ほどありましたので、その分も減っていると、この二つの理由です。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"今年お金が減ったということ、一応今の二つの要因があったということでわかりますけど、まず、そしてその次にこの暮らしの福祉インフラ整備事業についての本区においての背景と目的、なぜそういう施策が行われたかについて、ちょっと簡単な説明をお願いします。","respondent":"早津高齢福祉課長","answer":"品川区におきましては、この今回の春光福祉会の隣地につきましては、都市整備公社が調達すべき４分の１については、区から貸付金として出しているということで、いずれにいたしましても、グループホーム等の暮らし密着型の福祉インフラを整備しようと。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"東京都の新しい制度ということで、土地を購入する上のということで、新しい制度ということをお伺いしましたけれども、これは東京都の制度第１号というふうに本区は聞いておりますけれども、これについて推進地区といいますか、指定を受けているわけですけれども、他の推進地区についての今後の取り組みのご予定がありますれば、聞かせていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"他の自治体では、いまだ例がございません。したがいまして、東京都の中で一つだけの例です。今後の活用の見込みですけれども、ただいま懸案中になっております都南病院の取得の際に、この制度が活用できるかどうか、あわせて検討したいというふうに考えているところです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問・要望","question":"都南病院、この制度を活用して計画が図られるやに今伺いました。次に移ります。視覚障害についてなんですけれども、まず、視覚障害者の方に区から郵便物を出すときに、何か工夫を施されているのでしょうか、ちょっとお伺いしたいと思います。","respondent":"西島障害者福祉課長","answer":"ただ、これは１件１件文書になっている内容をコンピュータで入力いたしますので、なかなか多数の処理はできないというような現状があります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今課長がおっしゃいました難しい問題とは、具体的に言うとどんな問題があるんでしょうか。","respondent":"西島障害者福祉課長","answer":"国からの文書もあります、都からの文書もあります。あるいは金融機関からの文書もありますので、その辺をすべて網羅するのは現段階では難しいかなというところが一番困難な点です。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"あれはどのカード、どのカードといろいろと区別をするために視覚障害者の方がさわると思うんですけれども、この郵便物は区から来たよということで何か切り込みを入れるなり、区から発送した郵便物であることを視覚障害の方が顕著にわかるような方策をとっていただけるような考えを私は持っているんですけれども、いかがなものでしょうか。","respondent":"西島障害者福祉課長","answer":"それ以外に、おそらくそういう方は全盲もしくは全盲に近い方だと思いますので、区以外の文書の切り分けができないということで、区だけの文書を切り分けたことがどれだけ有効なのかなというところがありますので、その辺もう少し。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"切り込みを入れることについての有効であるか有効でないかというのは、人それぞれによって違いますので、よく当該の方とご協議していただいて、よりよい、せっかく区からのお知らせ、郵便物ですので、より効果のあるような形ですぐにごみ箱に行くのではなくて、効果のあるような形で区からの情報を発信していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"私、大きく１１６ページのいわゆる社会福祉費、それからできる限りと思いますが、１１９ページの高齢者住宅対策、１１６ページの成年後見、さらには１２４ページの保育所関係、時間が許す限りお伺いしたいと思います。さまざまな項目にまたがって存在して、額の多寡もあるわけですけれども、返還金、なぜ返還しなければいけないのか、ここら辺のご説明からまずお願いいたします。","respondent":"早津高齢福祉課長","answer":"その支出されたものが本来の目的に沿って使用したときに、残額が出たというときにそれを翌年度になりまして前年度分に相当するものを返還すると、こういったものです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"ここら辺の返還金の算定の出し方、ちょっとどうなのかなというふうに一つ単純な疑問を持ちまして、そこで、具体的に１１９ページの高齢者世帯の安否確認事業で１,０００万円、それから１２５ページの児童保育委託費で７９０万円、さらには多少額は少なくなっておりますが、１２７ページの家庭あんしんセンターで１３０万円、もう一つすみません、１２８ページの生活保護で４３０万円、これをそれぞれ簡潔に。","respondent":"早津高齢福祉課長、金子保育課長、志村生活福祉課長、辻田児童課長","answer":"１１９ページの高齢者世帯の安否確認の返還金が１,０００万円あるということですが、これは実は東京都のさまざまな補助金を返還するのに。私ども児童保育費については、国からも８億円余の負担金を平成１５年度までいただいておりましたので。私からは生活保護費に係る返還金についてご説明申し上げます。そういう中で、当初の計画を立てましたが、スタートしたばかりということで、ショートステイ。","id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"ご丁寧な説明をいただいたところと、ちょっとわからない部分がありました。すみません１点だけ、高齢者世帯の安否確認のところで、何か項目以外のところからまとめて１,０００万円にしたというようなふうに聞こえたんですが、もし誤解がありましたら訂正というか、丁寧なご説明をお願いしたい。","respondent":"早津高齢福祉課長","answer":"それぞれの事業の中で執行した結果、残が出てきて都に返還すべきものが生ずるわけですが、これをそれぞれに計上するのではなく、まとめてここの項目に計上したというものです。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"はい、わかりました。了解です。今後区として、ここら辺の再配分の一つの見方として教えていただきたいんですが、高齢者への再配分、また、子育て世代、民生費としての子育て世代への再配分、このような考え方、これから将来、近い将来、５年、１０年という内にそういう時代がやってくるわけですが、ここら辺の考え、大変大ざっぱな聞き方で恐縮ですが、考え方、また工夫とかをお知らせ願いたいと思います。","respondent":"新美福祉高齢事業部長","answer":"私どもも、この点は品川区も人口構成上同様と考えていますので、当面品川区としましては、やはり、長寿になって元気でということで予防というような、あるいは医療にかからない、医療の適正な受診等々、そういったところを着実に区民に理解を求め。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"基本的にはそういうお考えだと私も思います。その上で、今後２０２５年と今部長のほうからございましたけれども、今後例えば来年度にしてみますれば、いわゆる介護保険と、支援費の統合問題とか、目前にそこら辺の絡みのお話がどんどん目の前に連日の新聞報道なんかを見ましてもくるくる回転をしている中です。","respondent":"早津高齢福祉課長","answer":"例えば、その中でも焦点化されてくるのが介護予防にかかわることでございまして、こういったことにつきましては、従来からの老人保健事業との関係、もう少し制度改正で明確になってくる中で具体的な検討をすべきかと考えていますが、庁内におきましても。","id":"exchange-012"},{"speaker":"若林委員","kind":"意見","question":"はちょっと細かい点といいますか、奥に入った問題で、一つは１２４ページの保育所関係です。その基準の中にぜひとも、いわゆる多子家庭というのが今滅多にありませんけれども、いわゆる３人以上お子さんをお持ちという、多子家庭というのか、いわゆる子だくさんの家庭、ここに対する保育所としての、もう少しご丁寧なケアがあってもいいのかなというふうに思いましたが、お答えをよろしくお願いいたします。","respondent":"金子保育課長","answer":"現在のところ、私どもとしましては、兄弟姉妹が保育所にいる場合には一定の優遇はありますけれど、多子家庭で優遇するということはしてございません。ですが、今後の課題というふうに考えてあります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"現実的には、例えば私は５人子どもがいる家庭を存じております。一番上のお子さんは小学校に上がられておりますが、その下の４人はいわゆる乳幼児の方です。この４人の方を、５人の子どもを２人の親で見るわけですから、当然共働き家庭になる。その方は、４人の子どもを保育所に送り迎えするのに、どうしても車が必要だ。じゃあ、これについてもう一回理事者のお考えをお聞かせください。","respondent":"金子保育課長","answer":"ただ、順位としては低いほうのところに現在は考えていますので、それも含めて今後研究させていただければというふうに考えてあります。","id":"exchange-014"},{"speaker":"大西委員","kind":"質問・要望","question":"それと昨日もちょっと高齢福祉課長と話したんですけど、アンケートですね、受給者、発足以来８年、１０年とたっているんですけど、そのとき以来、受給者、受益者の方々のアンケートをとっていないということは、現在それが果たしてその方々にとってよいものか悪いものか、増えているということは、悪いものではないと思うんですけど、よりその人たちに喜ばれる区の施策であっていただきたいためには。","respondent":"蓼沼高齢事業課長、早津高齢福祉課長、西島障害者福祉課長、金子保育課長","answer":"高齢者クラブに対してもアンケートをとってございまして、やはりクラブといいますか、高齢者という名称ですとか。そういったことで総合的に支援しようということでございまして、安否確認というようなものも含めて行っていることですので。１２１ページの地域生活援助の内容ですけれども、これはグループホームにかかる経費でございまして、区内５カ所、区外１５カ所。私どもとしましては、従来からも含めて、保育の方法あるいはどういった場所を使うかも含めて工夫しておりますが。","id":"exchange-015"},{"speaker":"大西委員","kind":"質問・要望","question":"それとともに、安否確認のためということを言われましたけど、それをもってして２回という整合性が私にはどうもわからない。その回数をぜひ高齢者が希望するのであれば、できる範囲内で高齢者の希望に沿った回数を考えていただきたいというのが私の希望するところですが、その点に関してはどうでしょうか。","respondent":"早津高齢福祉課長","answer":"そういう意味では、週２回というサービス、多くの方には週２回ということで、ご納得をいただいている現状ですので、先ほどの繰り返しになりますが、当面はこれで実施していきたいというふうに考えているところです。","id":"exchange-016"},{"speaker":"大西委員","kind":"意見","question":"そうすると、ちょっと整合性がなくなる問題が、さくら会のさくらハイツにおいては、元気な高齢者に週７日間２１食を提供しているわけですね。実際にさくら会のほうでは、２１食提供中、大体５割を超える利用率があるということで、バランスのよい食事を提供されるものは受けたいということで、それだけのニーズがあるわけですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高齢者の方々、障害者の方々の社会参加、そして余暇ももっと楽しく生活できるような、当たり前のことになってほしいなという願いを込めて質問をしたいと思いますが、やさしいまちづくり計画推進費にこのお金が何に使われているのか、また、駅のエレベーター、そしてエスカレーター設置状況をお聞きしたいんですが、全部聞いていると時間がなくなってしまいますので、未設置。","respondent":"早津高齢福祉課長","answer":"やさしいまちづくり計画推進費ですが、平成１５年度におきましては、エレベーターを設置いたしましたのが、東急荏原中延駅です。こちらのエレベーター２基の設置費、これが２,６００万円ほどあります。それから、やさしいまちのガイドマップをつくりました。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やっと来たノンステップバスが未整備状況でスロープの板がなかなか出ないとか、扱いになれていない運転手さんだと、やっぱりまだまだ利用が少ない、利用しにくいから少ないというのも、どっちが先かというところですけれども、そういった面で、利用がしにくいんだと改善を求める声も出ているんで、ぜひこの辺も声を届けていただきたいなと思いますが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"やさしいまちづくり協議会というものがございまして、これには事業者と区と、それから区民の方が参加しておりますが、その中でもさまざまな要望が出ておりますし、事業者のほうからも検討計画とかというようなことを述べているところです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひその辺、増額をお願いしたいのと、あと電動車いすなんですけれども、この概要を見ると、交付が、ちょっとわからない、１５台、何か台数が少ないなと思うんですが、電動車いすは利用の条件が厳しいということを聞いているんですが、もっと多くの方が利用されると行動範囲が広がると思うので、電動車いすはもっと条件緩和をしていただきたいという声があるんですが、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"福祉タクシーにつきましても、その一つの方策として実施しているものでございまして、トータルで見ていただければ、区の障害者施策というのは大変進んでいるのではないかなというふうに考えてあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"杉並区なんかは月５,３００円、渋谷区は４,６００円、３,３００円くらいがすごく多いんですね。３階のところを新しくするといったことで、少し改善は図られているんですが、以前から議会棟に一つもない多機能トイレをつくってほしいと言っていたので、絶好のチャンスであると思ったんですが、改修に当たって一つも入っていないということですごく残念なんですが、どうしてなんでしょうか。","respondent":"鷹倉経理課長","answer":"多機能トイレ、だれでもトイレというふうに言われておりますけれども、今回工事をいたしましたのは、第１庁舎のトイレの改修をしているところです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年の６月にバリアフリー化推進要綱というのができまして、その中に社会のバリアフリー化はいまだ不十分なレベルで、できる限り大きく、できる限り早く確保するようにと書かれているんです。そういった面では、もっともっとテンポを上げてやっていただきたい、このことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問","question":"私は成果報告書１２６ページ、保育園運営費、それから全体の高齢者施設の考え方ですが、それこそたくさんあるので、例として触れるのは１１６ページ、西五反田高齢者施設のところを例として触れたいと思います。認証保育のこれはイメージでいいんですが、大体１カ月間ぐらい幾らぐらいかかるか。７万円ぐらいかなというところもあるんだけれども、そういう認識でいいのか、そこら辺もあわせて教えてください。","respondent":"金子保育課長、早津高齢福祉課長","answer":"定員を合計しますと２５７人というふうになりまして、計算上では認証を含めれば待機児についてはきちっと対応できているというところがあります。それから、認証保育所の保育料です。民間の有料老人ホームとの比較ですが、もちろん安いというふうに考えてあります。有料老人ホームも非常に差がありますので、どういう比較をするのが適当かというのは難しゅうありますが、費用はかなり安いというふうに考えてあります。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"これは、先ほど来言っているように２０２５年なのか、そのピークはどこなのかわかりませんが、こういう層が出てきたときに、今後必ずこの需要が出てくるのであれば、こっちの高齢者施設の場合はちょっと有料の民間というのは私は必要だと思うし、またその部分でＰＦＩなのかなんなのかということも考えながら、そういうことを今からある程度考えていく準備が必要だと思うんですが。","respondent":"金子保育課長、早津高齢福祉課長","answer":"そういう意味では、レベルの違いということもありますので、私どもとしましては、今後とも認証保育所が待機児解消の一つの手法としては考えておりますが、全体として区としましても。公と民と、両方のパワーの中でより充実した高齢者福祉を追究すべきものと思います。そういう中で、民間の活力というものを十分に活用してまいりたいというふうに考えてあります。","id":"exchange-024"},{"speaker":"石田委員","kind":"質問","question":"保育園のほうからいきます。今からある程度の準備をして、そういう考え方をしていって、私はこういうところがすごく増えてくる、もちろん特別養護老人ホームとかの考え方もあるけれども、こういう形のある程度自分自身で払えるような方は非常に増えてくるから、ここら辺のところの考え方だけは先行してもいいのかなとちょっと思っているんで、そこら辺の考え方を教えてください。","respondent":"金子保育課長、早津高齢福祉課長","answer":"そのときにもご説明申し上げたとおり、国の徴収金基準額の６０％を目標とするということで、受益者負担の部分については、やはり今後とも社会情勢等を見極めながら見直しをしていかなければならない部分だろうとは思ってあります。高齢者の関係ですが、２０２５年といいますのは、団塊の世代が７５歳を皆さん迎えられるということでございまして、そういった時代に向けまして、計画的な基盤整備に努めてまいりたいと考えておりますし。","id":"exchange-025"},{"speaker":"石田委員","kind":"意見","question":"わかるんだけれども、そういうふうにせっかく民がこれだけ育ってきたのであれば、そこら辺の施策をぜひもう一段、先ほど言ったいろんなところがやっていることも言いましたけれども、そういうのをどうやって当て込んでいったらこれが官の仕事なんだということは、必ず考え方として私はこれから持つべきだろうと考えていますので、高齢者の部分もそういう考えでぜひお願いをして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"私は１２７ページの家庭あんしんセンターについてお伺いします。特にこの家庭あんしんセンターでの相談ということでお伺いしたいんですが、ひとり親の、どんな相談の事例があるのか、また最近の相談が、何か特徴というものはあるのかお答えください。","respondent":"辻田児童課長","answer":"経済的な問題、それから仕事、それから最近は資格の取得というようなことが大変意欲的に相談されているということです。それから、一つ近年のちょっと傾向なんですけど、勤めるのではなくて事業開始をしたいというような自立心に富んだご相談もあるということです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"ひとり親家庭というイメージは、まさに母子家庭になってしまうかと思うんですけれども、今ひとり親家庭は父子家庭ということがあると思います。ただ、急に今度育児、家事をしなくてはならないという場面になってしまうと思うんですけれども、その中で、父子家庭に対しての区の支援はどのような形になっているんでしょうか。","respondent":"辻田児童課長","answer":"そういう中で、父子家庭に対する対応というのは、基本的には経済的支援としては育成手当、それから生活上のいろんな相談については私どものほうで、それから家庭あんしんセンターにおきましても、いろんな相談に乗っていく。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"児童相談所が今は都だと思うんですけれども、これから品川区の仕事になると思うんですが、家庭あんしんセンターとのネットワークはどうなるのかということと、あと今、次世代育成支援行動計画というのをようやくどういうふうにしていこうかという話し合いが始まったと思うんですけれども、その計画の中にひとり親家庭の支援というのは入るんでしょうか。","respondent":"辻田児童課長","answer":"そういう中で、家庭あんしんセンター、ここでは地域のネットワーク化を図ってまいりますけど、それだけではございませんで、これからは学童保育事業が抜けた後の児童センター、そういうところが家庭あんしんセンターを中心にしながら。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"区としてひとり親家庭に対してきめ細かい対応をなされていると思います。そんな中で、ひとり親家庭、いわゆる親御さんたちがお子さんに対して愛情を持って育てていると思いますが、そういう母子、父子、あわせたひとり親家庭の親御さんたちに対して、区としてこれからどんな決意で、また支援をしていくか、最後に教えてください。","respondent":"辻田児童課長","answer":"昼間働きに行っているために、お子さんのケアも十分できない、そういう中で、父子家庭に対する課題というのは新たな問題だというぐあいに私どものほうも考えております。そういうことでは、この辺につきまして、今後十分検討していきたいというぐあいに考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことで、ぜひ病院に入院中の方への現金支給をお願いしたいということで質問をしたいんですけれども、介護状態で入院されている方というのが何人ぐらいいるのか、まずその人数について教えていただきたいと思います。ぜひ、病院に入院中の方におむつ代の現金支給をしていただきたいと思うんですけれども、どうでしょうか。その検討の結果もあわせてお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長、福島福祉高齢事業部副参事","answer":"要介護認定を受けている方のうち、入院されている方の数ですが、要介護認定を受けている方、全体で約８,８００人中７８０人ほどの方が病院に入院されているという状況です。私のほうから、社会福祉協議会といたしまして、こちら、現金のほうで紙おむつの支給ができないか、入院時にできないかということについてお答えします。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の１人当たりの支給料というのも、２３区で最低の状況になっているんです。ぜひ品川区が社会福祉協議会への補助金をしっかりと増やしていただいて、他区並みに増やしていただきたいというふうに思うんですけれども、いかがでしょうか。ぜひ福祉の品川というのであれば、入院中の現金支給についてもぜひ実現をしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"早津高齢福祉課長、福島福祉高齢事業部副参事","answer":"他区との比較ですが、この紙おむつの支給というものは、在宅の介護者の方および家族の方を支えようということの趣旨でございまして、この在宅の介護生活を支えるのは基本的には介護保険サービス等を使いながら。私ども、この紙おむつ事業は昭和５８年から実施してございまして、当時は１５０人という小規模な事業だったんですが、それがだんだん拡大いたしまして、昭和６２年から区の補助金も入るようになりました。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この緊急通報システムの必要性というのは、ますます広がっていると思うんですけど、なぜ減っているんでしょうか。緊急通報システムがあることでかなりの不安解消になりますし、急に脳梗塞だ、心筋梗塞だ、こういう状況になったときに、命を救うことにもなりますので、ぜひ広報などの制度も活用しながら、この制度そのものの周知を広く図っていただきたいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この緊急通報システムについては、消防庁直結型と民間型があります。どちらもぜひ自由に選べるようにしていただきたいというふうに思うんです。それとあと、この問題についても２３区調べたんですけど、品川区は民間型の利用が１,８００円です。ぜひ住民税非課税世帯に対して無料とか減額、これをご検討いただけないかと思うんですが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"１,８００円という問題ですが、これは区も一定補助している結果でございまして、利用者の方にもご納得いただいている金額ですので、このまま、１,８００円のままとしたいというふうに考えております。","id":"exchange-034"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、その後、郵便物を受け取った後も、まだバリアはとれていないわけで、その後についてちょっと、先ほどはお金のかからない部分だったんですが、ちょっとお金のかかる話なんですけども、文書読取装置、スピーチオをどうしてもなくては生活できないような状況においては、ぜひその辺の、区だけでは対応は無理かもしれませんが、そういった意味でのバリアを除く措置を検討していただきたいと思うんですが。","respondent":"西島障害者福祉課長","answer":"視覚障害者に対する郵便物の件ですけれども、先ほどもご答弁申し上げましたけれども、視覚障害者当事者と十分お話し合いをしまして、有効な方法について検討してまいりたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ積極的な対応をよろしくお願いいたします。先ほども不用額の話が出ておりましたので、この助成事業に関しての、ここの部分の成年後見センターの部分の不用額の決済について、それと権利擁護サービスの相談件数ですとか、任意後見契約、成年後見制度、任意後見制度などの申し立てまでの経緯について、状況を教えていただきたいと思います。","respondent":"早津高齢福祉課長、福島福祉高齢事業部副参事","answer":"成年後見センターへの助成金で、残が出た理由ですが、年度末に近くなりまして、東京都社会福祉協議会のほうから単年度限りですが、補助金が入ることになりました。５００万円余ですが。その結果が大きなものです。私から成年後見センターの事業についてご説明します。成年後見センターの事業では、大きく三つに分けてございまして、一つが法定後見コースというものです。","id":"exchange-036"},{"speaker":"本多委員","kind":"質問","question":"それぞれ件数、わかりました。当然権利を擁護するサービスの周知というものを、例えば高齢者のさまざまな契約のトラブルですとか、そういったものの防止ですとか、当然お話がありました財産管理、保全ですね、そういったものを含めまして、さらなる周知をと思うんですが、その辺についてはいかがでしょうか。","respondent":"福島福祉高齢事業部副参事","answer":"具体的には、月１回ではありますけれども、説明会を開催し、こちらの説明会につきましても、各地区で開催したり等の工夫をしています。それ以外にも、パンフレット配布等を行っている次第です。","id":"exchange-037"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひさらなる周知をお願いしたいと思います。それと、将来の不安について、あらかじめ後見人を選ぶということで、任意後見制度というものが今事業が進んでいますけれども、障害者福祉との整合性ですとか、成年後見制度が５年目ということですので、いろんな制度について今後の課題ですとか、その辺のことについて教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"障害者につきましても、特に知的障害者を中心といたしまして、将来の問題というのは当然ありますので、成年後見制度の中に取り入れて進めてまいりたいというふうに考えてあります。","id":"exchange-038"},{"speaker":"本多委員","kind":"質問","question":"その整合性についてはわかりましたけども、制度そのもので５年目ということで、今後の課題についてはいかがでしょうか。","respondent":"福島福祉高齢事業部副参事","answer":"任意後見コースにつきましては、件数自体が今まで７件と数が少ないということもありますので、今後拡大に向けてＰＲ等活動するようにしていきたいと考えています。","id":"exchange-039"},{"speaker":"本多委員","kind":"質問・要望","question":"いろいろとほかにも課題があると思いますので、それぞれ対応していただきたいと思います。次に１１８ページの高齢者クラブ助成金についてお伺いいたします。","respondent":"蓼沼高齢事業課長","answer":"そういう意味で、平均の活動数も増えてきておりまして、そういう意味では、中には前年度より活動数が増えたにもかかわらず、助成金が減ってしまったというようなクラブもございまして、そういう意味では、今お話にありましたように、その報告書の様式等について。","id":"exchange-040"},{"speaker":"本多委員","kind":"質問・要望","question":"正直にやっている回数を出して、実際には活動しているんだけれども、助成金が減ってしまうというような、そういう正直者が、そういうことにならないように、しっかりと定義というものを、友愛活動の定義についてしっかりと見直していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"嶋委員","kind":"質問","question":"私のほうからは、まず１２７ページの家庭あんしんセンター、子ども未来館の運営費について、２番目に１２５ページ、子育てひろば事業について、３番目には１１７ページの社会福祉協議会、もし時間がありましたら４番目に認証保育所の運営助成についてお伺いをいたします。初めに１２７ページの家庭あんしんセンターについてお伺いいたします。","respondent":"辻田児童課長","answer":"そういう中で、地域の子育て支援ということの児童センターが核になってまいりますので、その施設を使って今後子育て支援センター的な役割を担っていただくというような形で今後地域への拡大というようなことを考えております。","id":"exchange-042"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぷりすくーる西五反田に子育て支援センターの二つ目ができたですが、ここは子ども未来館という形で位置づけをされておりますが、子ども未来館に対する事業をちょっと、家庭あんしんセンター、子ども未来館ということなんでしょうけれども、何かこの子ども未来館ということに関してのイメージ的なものがどういう発信をされているのか、ちょっとお聞かせをいただきたいと思います。","respondent":"辻田児童課長","answer":"そういうことで、新たな家庭あんしんセンターとしての活動も現在あそこを中心にしてひまわり荘、それから子育て支援センター、ファミリーサポートセンター等々、充実した形での中心館としての役割を果たしているです。","id":"exchange-043"},{"speaker":"嶋委員","kind":"質問・要望","question":"中心館という形で一つあるということで、子ども未来館、愛称ですが、これから第二、第三になっていくと思います。そこのところにも子ども未来館という愛称づけが重なっていくのかどうかをちょっと教えていただきたいと思います。","respondent":"辻田児童課長","answer":"中心館に対して地区館という位置づけをしていいのかどうか、それは今後の検討課題に入ってくると思います。","id":"exchange-044"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひまた次のぷりすくーるとか、いろんな形で区民住宅ができたところもありますので、ぜひ愛称などをつけて、もっともっと皆様が使いやすくなっていただけたらと思います。次に１２５ページの子育てひろば事業ですが、きっと今のところと流れが同じになってくるかと思いますが、この子育てひろば事業について内容をお聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"１２５ページの子育てひろば事業に関しましては、保育所あるいは児童館等で行う子育てひろば事業Ａ型というものの事業がありまして、これを私立の認可保育園のどんぐり保育園というところで実施しているものです。","id":"exchange-045"},{"speaker":"嶋委員","kind":"質問・要望","question":"子育てひろば事業的には今はどんぐり保育園でやっているということでございましょうか。厚生労働省は将来的に中学校１区域に一つつくっていくという構想がありますが、そういう中で、品川区として今は一つということなのでしょうか。これからの事業の拡大とか充実についてお聞かせをいただきたいと思います。","respondent":"辻田児童課長","answer":"ただ、今後につきましては、先ほども申しましたように、児童センターが新しい機能を持ってくる、そういう中では、子育てひろば事業Ａ型という形での国の事業かどうかは今後検討いたしますけど、そういうような機能は必ず各センターとも持ってくるです。","id":"exchange-046"},{"speaker":"嶋委員","kind":"質問・要望","question":"児童センターがそういう子育てひろば的な事業を展開していくということで認識をさせていただきました。そういう意味では、児童センターの拡充をしていく中で、こういう専門的な相談を受けていく受け皿的なものはどのようにお考えかお聞かせいただきたいと思います。","respondent":"辻田児童課長","answer":"相談事業を受けるということで、その相談体制の整備ということで、個々の職員の能力アップを図っていかなければならない、研修等が今後私どものほうの職員に求められている最大のことではないかなというぐあいに考えております。","id":"exchange-047"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味で、こういう子育てひろば事業的な中で、そういう双子、三つ子たちの対応というのも、これからどんどん悩みとか、２人、３人になると授乳時間が全部ばらばらだと１日使ってしまうような時間で、親御さんのノイローゼ的なもの、うつ的なものも発生をしていくこともあるかと思いますので、そういう意味で、お子さんの多い家庭に対しての子育てひろば的な発信といいますか、声がけといいますか。","respondent":"辻田児童課長","answer":"そういう中で、当然多子というような、例えば双子であるとか、それから多子であるとかというようなことの対応というのもそれなりに現在やってきておりますので、今後各児童センターがさらに在宅子育て支援をしていく中で。","id":"exchange-048"},{"speaker":"嶋委員","kind":"質問・要望","question":"それで、平成１６年度の事業ですが、皆様から、各委員から出ておりましたオアシスルームを開設をされた、５園ということで、大変これもうれしいことで、第二子が生まれて大変ということもありますが、まだまだやっている園が少ないということで、ぜひこれも拡充をしていただきたいという要望がたくさんありますが、そこら辺のお考えをお聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"このオアシスルームについてのお尋ねですが、委員からご指摘のとおり、この６月から始まりまして、５カ月目に入りまして、非常に好評を得ているところです。私どももニーズが高いということで、それを踏まえて来年度については検討していきたいというふうに考えてあります。","id":"exchange-049"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひリフレッシュという意味で、大変お母さんが楽しく、子育ては楽しいものと思えるような形でぜひご努力をお願いしたいと思います。次に、１１７ページの社会福祉協議会の件ですが、ここで品川区として入院中の高齢者へのヘルパー派遣を社会福祉協議会でやっていらっしゃると聞いておりますが、この内容とどのぐらいの皆様からのご要望があるのかお聞かせいただきたいと思います。","respondent":"福島福祉高齢事業部副参事","answer":"私のほうから、委員からご指摘のありましたヘルパー派遣についてご説明します。社会福祉協議会で行っていますヘルパーですけれども、正確にはさわやかサービスにおきまして、入退院時サポート事業というのを今年度から行っております。","id":"exchange-050"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうにも大変こういうご相談が多くて、お願いしたところ、社会福祉協議会で、品川区ではやっていないけども、社会福祉協議会のさわやかサービスでやっているということで、そちらのほうにご連絡をしましたが、この２２件で実施されたのが１５件、差が７件ありますが、この内容はどうしてこのようになったのかお聞かせいただきたいと思います。","respondent":"福島福祉高齢事業部副参事","answer":"問い合わせが２２件で、サービスを実施したのが１５件、その差の７件ですが、こちらは問い合わせした段階でお話を伺っている中で、サービスが必要ないというふうになったもので、実際のサービスにはつながりませんでした。","id":"exchange-051"},{"speaker":"嶋委員","kind":"質問・要望","question":"私が伺ったところは、やはりこちらが希望した日時とか要望がありますね、入退院ですので、そういう意味で、そのヘルパー、さわやかサービスの方たちのいわゆる日にちが、相手の方の都合が悪いという形で断られたというお話を聞いているんですが、そこら辺の、もしその方がだめなら次のヘルパーが派遣できなかったのかどうか、ちょっとそこら辺を、課題があるならばお聞かせいただきたいと思います。","respondent":"福島福祉高齢事業部副参事","answer":"実際にいない場合、次の者等を当たっていきまして、なるべくご希望に沿う形をとってあります。委員ご指摘された件につきましては、たまたまそのときに合わなかったといことです。今後はそういうことがないように、さまざまに対応していきたいというふうに思っております。","id":"exchange-052"},{"speaker":"嶋委員","kind":"質問・要望","question":"おひとり暮らしで、まだ６５歳の高齢者の家族というのはだんだん増えてまいりますので、今はさわやかサービスでやっておりますが、品川区としてこれを今後やっていかれる事業的にあるのかどうかをちょっとお聞かせいただきたいと思います。ずっとさわやかサービスがこの事業を展開していかれるのかどうか、お聞かせをいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"区としての考えですが、実は入退院時のホームヘルプサービスというのは、介護保険では制度上対象にならないということになっておりまして、その介護保険制度を埋めるサービスとして、社会福祉協議会というものが品川区においては活動しているということで。","id":"exchange-053"},{"speaker":"嶋委員","kind":"質問・要望","question":"４分ありますので、最後に認証保育所の運営について、皆様からもありましたが、認証保育所と品川区との関係といいますか、何もなければ、そのままいいと思いますが、毎月１日の在園児数でいわゆるいろんな助成をしていると聞いておりますが、何か問題とか、またそこに通わせたときに、緊急一時の場合が一番ちょっと私が問題にしていきたいと思っていますが、緊急、どこへも預ける方がない、そういう場合に。","respondent":"金子保育課長","answer":"通常私どもが対応しているのは、月１６０時間以上お預かりしている場合の方についての助成なんですが、それぞれの施設においては、さまざまな事業が、委員ご指摘の一時保育的な事業もやっているように聞いてあります。","id":"exchange-054"},{"speaker":"嶋委員","kind":"質問","question":"別に大きな問題があったわけではございませんが、これからどんどん緊急時にお預けをするという形に、近くに認証保育園があるとご利用する方も多くなってくると思いますので、区のほうもなるべく多く意思の疎通をするように、年何回か会議とか協議をやっていらっしゃると思いますが、ぜひそういう中で、利用者のアンケートもとるようなことも年に１回ぐらいはされてもいいのかなと考えていますが。","respondent":"金子保育課長","answer":"ですので、私どもとしましては、第三者が評価するこういった評価というものも参考にしながら、適切な対応をしていきたいというふうに考えてあります。","id":"exchange-055"},{"speaker":"山村委員","kind":"質問","question":"成果報告書１２７ページ、生活保護費、時間がありましたら１２７ページ、児童センターのことで質問させていただければと考えています。それと、この福祉から就労へということで、保護の申請、認定に影響があってはいけないと思うんですが、そこら辺のことも教えていただければと思います。","respondent":"志村生活福祉課長","answer":"この場合、生活保護の申請から決定に至る間に、いろんな事情があります。さまざまです。その中で、今資産は実際はあるんだけど、実際の活用ができないみたいなケースもあります。その場合も一応私どものほうで、窮迫の事情から保護が必要だということでかけてまいります。","id":"exchange-056"},{"speaker":"山村委員","kind":"質問","question":"たまたまということですので、基本的には受給後にチェックを入れるようなことはしていないと思ってよろしいんでしょうか。不正受給とか、そういう場合は基本的には申請されるということでしょうか。","respondent":"志村生活福祉課長","answer":"すみません、ちょっと私のほうの説明が足りなくて申しわけありませんでした。","id":"exchange-057"},{"speaker":"山村委員","kind":"質問・要望","question":"６件あったというふうにお聞きしましたが、その６件が発覚したというか、発見された経緯といいますか、そこら辺を教えていただきたい。","respondent":"志村生活福祉課長","answer":"この６件、まことに申しわけございません、全部の把握は、今ちょっと手元に資料がございませんけども、これにつきましては、今申し上げましたとおり、私どものほうの就労指導も含めまして、いろんな意味での指導をしています。その中で発生したものです。","id":"exchange-058"},{"speaker":"山村委員","kind":"質問","question":"先ほど自立支援プログラムのことをお聞きしたと思うんですが、そのことは、要するに品川区が今後方針転換後にやること、プログラム的なものはまだ全然青写真的なものはでき上がっていないのかどうか。","respondent":"志村生活福祉課長","answer":"ですので、今こうした生活保護世帯が急増しているというような傾向を受けまして、ややもすれば、ちょっと手薄になったのかなという感はありますけれども、私どもこれからも引き続きその辺の向上については検討していきたいというふうに考えてあります。","id":"exchange-059"},{"speaker":"山村委員","kind":"質問","question":"そうすると、今までも例えばシルバー人材センター等で仕事を紹介するとか、そのようなことをやられていたんでしょうか。","respondent":"志村生活福祉課長","answer":"今、ご質問にありますとおり、ハローワークはもちろん、私どもサポしながわ、それからご質問にありましたシルバー人材センター等々に相談に行く、あるいはそうした求職活動をするようにということで指導を図っているところです。","id":"exchange-060"},{"speaker":"山村委員","kind":"質問","question":"最初に質問したんですけど、お答えいただけていないのは、今後方針転換して、することになったと思うんですが、保護申請の認定等に影響があるのかないのか、そこら辺のことは。","respondent":"志村生活福祉課長","answer":"自立支援の向上につきましては、これはただいま申し上げましたとおり、これからも引き続きいろんな方策を検討してまいりたいと思ってあります。","id":"exchange-061"},{"speaker":"山村委員","kind":"質問・要望","question":"次の児童センター運営費のことで質問させていただければと考えています。児童センター運営費の利用状況と年層別人員ですか、高校生以上というのがあるんですけど、高校生以上というのは、高校生以外も含まれていると思うんですけど、高校生だけだと何人ぐらいなのかとか、例えば高校生以上というのは、ほとんどは親御さんとか、そういうことになると考えてよろしいのか教えていただきたい。","respondent":"辻田児童課長","answer":"このくくりとしては、高校生以上というのは、高校生、それから一般の社会人、それから保護者の方々も全部含めてという形です。それから、高校生の人数ですけど、年間で１万４,６００人弱という形でカウントされております。","id":"exchange-062"},{"speaker":"山村委員","kind":"質問・要望","question":"ちょっと親御さんは子どもを連れてきているだけで、利用しているとカウントしていいのかどうかは、ちょっと私いまいち疑問を感じただけなんですけど。高校生が１万 ４,６００人弱ということで、中学生は４万８,０００人弱ということで、中学生、高校生に対して利用を呼びかけるようなことを何かまた最近新しいことをやられているかどうか教えていただきたい。","respondent":"辻田児童課長","answer":"児童センターで中高校生に対して何かですが、私どものほう、現在ティーンズプラザを平成１４年度から立ち上げまして、平塚、それから東大井、それから今年は冨士見台ということで、中高校生事業に対応する館づくりをしております。","id":"exchange-063"},{"speaker":"山村委員","kind":"質問","question":"そうすると、実際児童センターの利用状況というのは、高校生の１万４,６００人を足しただけの数で考えたほうがいいということでよろしいんでしょうか。１８歳以下しか使えないと考えると。","respondent":"辻田児童課長","answer":"基本的な施設の対象者としてはそうだですけど、当然ここは地域の中での子育ての中心的な施設という意味合いも持っておりますので、親御さんですね、保護者の方、特に在宅で子育てをしている保護者の方々。","id":"exchange-064"},{"speaker":"山村委員","kind":"意見","question":"私が言いたいのは、高校生以上じゃなくて、高校生とそれ以外で分けていただけると、ちょっとわかりやすかったかなと思いましたので、次からそういうふうにできればしていただけるとすごくいいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう一点、介護保険料のほうです。介護保険料は第１号被保険者のたしか９８％ぐらいの徴収率が示されていたと思うんですが、その中で普通徴収と特別徴収は随分差が出ている、その辺でなぜという部分、普通徴収ですから、わかることはわかるんですけど、ことに、不納欠損内訳資料の中で、２,５００万円ぐらいが時効が成立されてしまっている。この時効の条件的なものをお答え願いたいと思います。","respondent":"早津高齢福祉課長、黒田保険年金課長","answer":"この新予防給付の中には、筋力向上トレーニングですとか、低栄養対策ですとか、骨折防止事業ですとかというようなものが予防事業としてメニュー化される見込みになっておりまして、筋力向上の内容としまして、機械を使うもの。介護保険の時効ですが、国民健康保険と同じように２年を経過しますと不納欠損、時効ということで不納欠損にしています。","id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"確認","question":"新介護予防になってきて、歳入歳出上どの程度影響があるのかなと、５００万円ぐらいの分だけが影響出てくるのかなというのはちょっと確認をさせてください。","respondent":"早津高齢福祉課長、黒田保険年金課長","answer":"この２０５ページにあります４８０万円ですが、これは昨年「身近でリハビリ」は３カ所で始めましたが、７月に１カ所、１月に２カ所ということで、年度の中途からでございましたので、この数字が保険給付費になってくるわけですけれども。そういうことで、督促と催告もやっている中で、このような状況を経て２年経過した方が時効ということで不納欠損ということで落としています。","id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"時効のほうですけど、請求して、１回請求したら終わってしまうのかなというのが気になるんですけど、それが時効の中断方法というのははっきりわからないので、国の税とかこういう保険料ですか、その分がわからなかったので確認しています。ただ、今言ったように、使う分、ここから運用していく分ではない基金だと思っていますのでね。ただその中でどうなのかなと、ちょっとそこら辺でお答えをいただきたい。","respondent":"小野副収入役","answer":"運用につきましては、所管当局、それから財政当局の指示に基づいてやっているところですけれども、いずれにいたしましても、現在普通預金の金利が０.００１％、それから定期ですと０.０３％、国債等ありますけれども、国債の場合は２年とか３年とか。","id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"質問","question":"さっきの時効の関係ですけど、時効というか、介護保険料なんですけど、支払う気がなくてこういう形になるのか、それともほんとうに支払えないという方、どっちが多いのかなというのを教えてください。それともう一個聞きます。国民健康保険の中の今度コンビニエンスストアの収納代行ができましたけど、委託料が載っていますけど、これは財源的には区の負担、持ち出しなんでしょうか。","respondent":"黒田保険年金課長、市岡企画財政課長","answer":"やはり、滞納している方を対象に１件１件説明をさせていただきながら収納していくということで、それなりの成果が今上がってきてあります。コンビニエンスストアの収納代行の財源という関係では、特別の特定財源が当たっているものではありませんが、国のほうから、いわばこういう徴収努力をする公共団体については、調整交付金という補助金が来ていまして。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"児童センター運営費ですが、ここに３億２,７００万円ということがあるんですけれども、これは大体どのような形で使われているのか、それから、児童センターの事業の中にはいろいろとくくりがあるかと思うんですが、例えば幼児、乳児用の催しでありますとか、あとは小学生対象のもの、それから中高校生対象のものということで、さまざまなものがあるかと思いますが、簡単で結構ですので、割合。","respondent":"辻田児童課長","answer":"幼児クラブ、小学生、中高校生というような形での事業別という仕分けはこの中でちょっと今持っておりませんので、ご容赦いただきたいと思います。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"今の児童福祉問題調査会、私もメンバーの委員になっているんですが、この中で今話されているのが、中高校生の自立した活動の拡大と地域のかかわりについてという形で今盛んに議論をしています。その中で、地域とのかかわりについてということなんですが、児童センターの考え方として、中高校生に対する事業の展開、考え方ですね、それはどういうふうにされていこうとしているのか、その辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"ただ、中高校生事業につきましては、ティーンズプラザを立ち上げまして、子どもの居場所であるとか、それから子どもがやりたいこと、例えばスポーツであるとか音楽であるとかということに対する十分な対応を既に始めているところです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"地域の中で育てていくべきなんだというような意識がかなり高くなっているというのをお聞きしました。ティーンズプラザといういろいろな事業展開するのは当然ながら、今後も進んでいくことだとは思いますけれども、やはり地域の中で育てていくんだという地域の方たちの声、それを品川区としてはどういうふうに吸い上げていって実現化していくのかという、その辺のご見解をお願いいたします。","respondent":"辻田児童課長","answer":"地域に根ざした、また地域の方々が協力してくれない中高校生事業、ティーンズプラザのようなものは、なかなかこれから発展していかないだろうということで、私どものほう、その取り組みについては十分大事だなというぐあいに感じております。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の方たちが率先して取り組もうという意識が高まってきたというところがありますので、ティーンズプラザ等々の事業展開はかなりのコストがかかってこようかと思います。関連しまして、今児童センターのほうでさまざまな行事を行っているんですが、中高校生の位置づけはいかがでしょうか。","respondent":"辻田児童課長","answer":"基本的に中高校生の位置づけというのは、１８歳までの児童センターの施設ということで、利用者の位置づけというのが非常に強うあります。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"そう考えますと、今やっている事業の中でも、中高校生の位置づけというのはお客様ということではなくて、やはりスタッフの一員、ボランティアというのはお金の問題も絡んできますので問題あるかと思いますが、スタッフという形で運営にかかわってもらうということは非常にいいことではないかなというふうに思いますが、その辺の見解はいかがでしょうか。","respondent":"辻田児童課長","answer":"イベントであるとか、日常的なボランティアの中でやっておりますけど、特に東中延のロックバンド、要するにロックバンドのコンサートを開くときに、中学生、高校生がみんな協力し合って、スタッフであり、参加者であるというような関係を持ちながら。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"認証保育所の件なんですが、先ほど待機児が４月の段階で１８４名ということなんですけれども、待機児のカウントの仕方はどういう考え方でカウントされているのか、まずお聞きしたいと思います。","respondent":"金子保育課長","answer":"それで、従来ですと保育園の入園申し込みをして入れない方、すべてカウントするというものでしたが、平成１４年度以降につきましては、まず市区町村が助成をしているような例えば認証保育所であるとか、あるいは保育ママであるような助成をしている、出資している事業について。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"先ほど待機児１８４名というのは、どういうカウントの仕方になっているんでしょうか。","respondent":"金子保育課長","answer":"今申し上げました新しい定義に基づいたカウントの方法で１８４人というものです。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"認可保育園に入りたいけれども入れないという保護者の方たちが結構いらっしゃると思うんですね。そうすると、カウントの仕方、旧のカウントの仕方で数えた場合に、この品川区の実際の待機児というのは、認可保育園、要は自分の希望する保育園に行きたいというふうに希望しても行けないという待機児の数というのはどのくらいのレベルなんでしょうか。","respondent":"金子保育課長","answer":"私ども、待機児として数を出している数字はこの１８４人というだけですので、ご理解いただきたいと思います。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"先ほど認証保育所Ａ型、Ｂ型、２５７人の定員があるということをおっしゃるんですが、では、４月の段階で認証保育所の空きが多いというのはなぜかというふうに考えると、やはり認可保育園に魅力を感じているんだろうと。その人に対する助成というのは必要じゃないかなというふうに私は思っているんですが、その辺のお考えはいかがでしょうか。","respondent":"金子保育課長","answer":"ただ、認証保育所につきましては、認可保育園へ入るための待機としてお使いになる方と、先ほどもちょっと申し上げましたとおり、認証保育所のメニューあるいは施設等々に魅力を感じてそちらを選んでいる方もいらっしゃるということで、これにつきましては。","id":"exchange-078"},{"speaker":"宮崎委員","kind":"質問","question":"私は１９７ページの介護保険会計と、あと１１６ページの訪問介護サービス給付等自己負担金軽減事業、あと１８９ページの老人保健のほうを伺いたいと思います。","respondent":"早津高齢福祉課長","answer":"ホームヘルプの軽減事業の利用者ですが、実利用者で平成１３年からしかありませんので申しわけございません。平成１３年が９２３人、平成１４年が７７１人、平成１５年が、１２月までの実績ですが、６５６人いうことになってあります。失礼しました。","id":"exchange-079"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあ、金額は、わかったらお願いいたします。それから、この制度を利用されている方の、今人数、平成１３年、１４年、１５年度の人数をお伺いしたんですけれども、この方々の平均年齢がわかったら、ちょっと。それが１点。","respondent":"早津高齢福祉課長","answer":"まことに申しわけありませんが、利用者の平均年齢、それから年数というようなものを把握してございません。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとそれだとなかなか話が先に進まないんですけれども。私、この制度は何とか続けられないものかというふうに考えているんですけれども、その点で、区のほうは事務事業評価のところを見ると、今年度で終わりというような内容になっているかと思うんですけれども、この制度についての区の考え方をちょっとお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"このホームヘルプの減額制度は、委員ご指摘のように介護保険制度が導入されたときの、いわば経過措置的な扱いで導入されたものでございまして、一定所得以下の方については １０％の負担ではなく、３％、それを徐々に経過措置ですので。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"質問","question":"平成１５年のところでも、３,６００万円ということで、これは平成１２年のときは４,３００万円だったのが、ずっと減ってきていますけれども、この財政的な負担、今国の制度が終わるからというふうなお話でしたけれども、財政的な負担なんかも含めて、それだって介護保険、介護を軽減していくというところの考え方。","respondent":"早津高齢福祉課長","answer":"本来の本則であります１０％の負担に戻るですので、公平性の観点等から見て、国の考えどおりでよろしいのではないかというふうに考えているところです。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問","question":"国の制度だということで、利用者がみんなで払うんだというお話なんですけれども、それでは、ちょっとお伺いしたいんですけれども、区のほうの介護保険の基金、前年度も積み立てありましたけれども、今時点で合計幾らになっていますか。それと、第１号被保険者１人当たり幾らになっておりますか、改めて伺いたいと思います。","respondent":"早津高齢福祉課長","answer":"平成１５年度の決算を終えたところですので、基金は１９億８,３００万円余ということになろうかと思います。第１号被保険者を大まかに割りますと３万３,０００円ぐらいではないかというふうに思います。","id":"exchange-083"},{"speaker":"宮崎委員","kind":"意見","question":"あわせて、今年度予算が組まれておりますけれども、基金積み立てですね、２期、この３年間では介護保険の積み立ては、あとこれからどのくらい積み立て予定というか、計画がありますか。","respondent":"早津高齢福祉課長","answer":"したがいまして、積み立てることはできません。おそらく今年度は８,３００万円の基金取り崩しを計上していますが、来年度はさらに増えるものというふうに考えてあります。","id":"exchange-084"},{"speaker":"宮崎委員","kind":"質問","question":"今時点で第１号被保険者１人当たり３万３,０００円ですから、平均、いわゆる基本額でいいますと１０カ月分ですよね。区のほうは、国の法律があるんだというふうなお話なんですけれども、自治体での、区独自での継続等というのは、法律の関係とかいろいろありますけれども、その気があったら私はできるんじゃないのかというふうに思うんですが、その点はどうでしょうか。","respondent":"早津高齢福祉課長","answer":"ホームヘルプの減額というような形での基金の使い方は考えておりませんで、品川区が選択いたしましたのは、リハビリサービスを充実しようというようなことで条例改正をご提案し、全会一致でご賛成をいただいたところです。","id":"exchange-085"},{"speaker":"宮崎委員","kind":"質問・要望","question":"その点、ちょっともう一回答弁いただきたいんですけど。今の方の例なんですけども、実際に収入が少ない、特に年金も減ってきておりますので、当然切り詰めるところは限られてきますので、当然このヘルパーを減らすしかないかというふうなお話なんですけれども、こういうふうな声というのは、聞いてどういうふうにお考えでしょうか。","respondent":"早津高齢福祉課長","answer":"ヘルパーの負担軽減の問題ですが、区としても国の考え方に賛成です。したがいまして、区として継続する意思はございません。","id":"exchange-086"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の答弁は、逆に言えば、区はやろうと思えばできるというふうに私は受けとめました。これが第１号被保険者、お年寄りの負担でつくられてきていると、そういうことをしっかりと受けとめていかないと負担ばかりが、このままこの介護保険制度は続いていいのかということになっていくと思います。私は国に対してしっかりと改善も含めた対応を求めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"井上委員","kind":"質問","question":"私からは１１７ページの各種助成金の社会福祉協議会の中の事業と、１２７ページ、家庭あんしんセンター運営費について伺います。","respondent":"福島福祉高齢事業部副参事","answer":"このサービスをする側の協力会員がサービスをした時間を現金でもらうのではなく、時間として預託するというものです。預託した時間につきましては、自分が、あるいは自分の親がそういったサービスが必要となったときに、そのサービスを使っていくという制度です。","id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどから議論になっています介護保険制度も限られた財源でよりよいサービスを提供しているということで、今年は見直しが今進められているわけで、そういった財源不足のところを補って、担って、支え合う仕組みとして、なかなか利用は難しいかもしれないですけれども、そういう人づくり、支える人をつくっていくという仕組みができるために、そういう連携をもっと広げていってはどうかと思うんですけれども。","respondent":"福島福祉高齢事業部副参事","answer":"２３区の社会福祉協議会の中では、時間預託制度自体を廃止する区も出ているという状況もありますので、今後自治体の社会福祉協議会と連携をとっていくということは、大変難しいことだと考えています。","id":"exchange-089"},{"speaker":"井上委員","kind":"質問","question":"以前に私、区民の方から相談を受けまして、紙おむつの種類が少なくて使い勝手が悪いとか、使う人がもう住んでいらっしゃらない、施設に入所されたんだろうなと思われるにもかかわらず配達がされていたとか、そういった指摘をいただいていまして、担当者の方にお話を伺いましたら、いろいろなところで改善をされているということがわかって、とても安心したんですけれども。","respondent":"福島福祉高齢事業部副参事","answer":"そういった形で制度を充実させています。見直しにつきましては、２年に１度中身あるいは使い勝手等、利用している方のご意見も聞きながら、あるいは民生委員等の意見も聞きながら選定している次第です。","id":"exchange-090"},{"speaker":"井上委員","kind":"質問","question":"ちょっと先ほどの答弁で気になったところは、市販より安いと言われましたけれども、実際に私も現物を見せていただきましたけれども、市販で同じものが安いというのか、たくさん買うから安いという、トータルをおっしゃっているのか、安いと言われても、実際はどのぐらい安くなっているのか教えてください。","respondent":"福島福祉高齢事業部副参事","answer":"こちら、高齢者にとりまして、かさばる紙おむつを買いに行くというのは大変ということも伺っていますし、宅配されることで大変助かっているというご意見も聞いてありますので、こうした宅配を含めたサービスは続けていきたいというふうに考えてあります。","id":"exchange-091"},{"speaker":"井上委員","kind":"質問","question":"品川区からこのおむつの支給の助成金として、年間４,０００万円近くの事業かと思いますけれども、３,８２８万円の経費が支出されているわけですから、品川区としても社会福祉協議会のほうにいろいろな働きかけができるかと思うんですけれども、先ほど鈴木ひろ子委員のほうは病院に入院された方の現金支給をということだったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ現金から現物へという流れがあるとおっしゃっていましたけれども、社会保障、福祉に関して言えば、ほんとうにその人たちの支援になっているのか、施設とかそういう業者支援になっているのかというのは、今大変問題になっていることかと思いますので、そういう視点も入れて、利用者にとって選べるサービスという流れがあるというところでは少し検討をいただきたいということと、ニーズ調査については。","respondent":"辻田児童課長","answer":"基本的には家族というものがお互いに助け合う、夫がいれば、夫が妻を助けて支援をするというようなことが本来でありますけど、そういう部分がどうしてもできないというような場合に限ってこの産後支援ヘルパーを派遣するです。","id":"exchange-093"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、こういう支援ができますというだけじゃないものが必要かと思うんですけれども、利用者が求めている支援というのは、多分パンフレットの中にも書いてありましたけれども、実家に帰れないとか、親元に行けなかった人とか、親元で過ごせてお産ができるような支援というのも言葉に入っていたかと思います。でも、補助であって、実際には沐浴をしちゃいけませんよというふうに言われている。","respondent":"辻田児童課長","answer":"それでできないような部分について、産後支援ヘルパーを使うということでの切り分けはきちっとしていきたいなというぐあいに考えております。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、家庭あんしんセンターというのは、虐待防止の中核を担うという施設を、そういう目的でできているわけですから、さまざまなところと連携をとって虐待防止をしていこうという、こっちでやっています、こっちでやっていますということじゃなくて、こういう制度のつながりでそのことが派生的に虐待防止の事業というか、品川区全体でそういうことがつながってくればいいと思うので、先ほど洗濯のこととか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問","question":"私からは、成果報告書の１２０ページ、かかりつけ医・歯科医定着促進事業に関連をして、それから１２５ページ、保育園に関連して質問をいたします。おそらく一つの事業を医師側とそれから高齢者側、二つに分けたと思われますが、ここで１２０ページに計上されておりますかかりつけ医・歯科医定着促進事業については、何をされているかということを端的にお聞かせください。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては、今年度で終了ということで、来年度以降は健康課のほうの機能推進事業のほうに統合していくという予定です。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"質問","question":"それは切り口がたまたま医師側と、それから高齢者側だけであって、もともと同じなわけですから、それをどうして一つにできなかったのか、柔軟な事業体制の中でできなかったのかと単純に思いますので、そのことについての答弁をお聞かせください。","respondent":"蓼沼高齢事業課長","answer":"この民生費のほうで計上しておりますかかりつけ医事業につきましては、若干の経緯がごいざまして、老人医療制度の開始に伴いまして、事務取扱手数料というものが創設をされまして、医療機関のほうに支払いがされていたという経緯がございましたが、制度が定着して。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"確認","question":"もう一回だけ確認しますけど、もしＰＲのためだけであるならば、さっき説明があったように、もう少し内部、同じ、まして部長のほうでやられている事業ですから、それをたまたま医師側と高齢者側で切り分けただけであるとするならば、当初からもう少し事業の整合性とか仕組みを考えられるんじゃないかと思います。ＰＲということだけじゃないです。いかがでしょうか。","respondent":"蓼沼高齢事業課長","answer":"ＰＲだけではないというご意見ですけれども、これにつきましては、先ほど経緯につきましては若干述べたとおりです。これにつきまして、東京都が補助事業を創設いたしまして、平成１２年、４年間の期間限定の事業ということで取り組みを始めました。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひそちらのほう、よろしくお願いいたします。次に保育園のほうでありますけど、これはいわゆる保育園のＰＴＡについて質問します。簡単に今の保育園ＰＴＡの現状と、それからいわゆる保育園の保護者との連携、それから自主事業内容と、それから一番聞きたいのは保護者の評価はどうでしょうかということを端的にお聞かせください。","respondent":"金子保育課長","answer":"保護者の評価ですが、日ごろどうしても忙しいご両親の方々がいらっしゃいますので、保護者の方々がいらっしゃいますので、こういった保育園の中での、日常子どもがやっているようなことをその場で知ったり、あるいは知識的にほかの方との子育ての共通した悩みの交換といいますか。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そこでもう一つお伺いしたいのは、去年の予算特別委員会でも随分議論になりました保育料の引き上げ、改定のことについてでありますが、当然このＰＴＡの皆さんも含めて、いろいろ税の投入の現状と、それから保護者負担水準の内容等々説明なさったと思いますが、保育園ＰＴＡも含めて、これに対する、保育料の改定に対する意見、それから要望等何かありましたでしょうかということをお聞かせください。","respondent":"金子保育課長","answer":"ＰＴＡ事業の今後の園とのホームページ等々のかかわり合いですが、区全体のホームページ、それから事業部としてのホームページがありますが、今後各園のホームページあるいはご質問のＰＴＡのホームページについては研究していく必要があると思いますが。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問","question":"特に保育料の改定のことにつきましては、去年の予算特別委員会を思い出しながら今質問させていただきましたけれども、正しい情報、私たちも随分言いました。税金をたくさん投入して、これだけかかっているんだよと。それは広報に載せてくださったことの結果として非常に理解が進んだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"高星委員","kind":"質問・要望","question":"ご苦労さまです。私のほうからは２点ほどお聞きしたいと思っています。町会に対する、これらに関する補助金の関係、これは品川区の町会の補助金のくくりの中には間違いなく入っているわけですから、どのくらいの規模で各町会等々に補助金が出されているのか、どこを見ればこういうものが出てくるのか、わかったら教えていただきたいと思います。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長、福島福祉高齢事業部副参事","answer":"１６名ほど増をいたしまして、ちょっと記憶ですけれども、９割以上の方が今の段階で推薦を終わって、東京都の審査のほうに回っている段階です。今現在は区単独でお祝金を支給をしておりまして、中身については節目、８０歳、８８歳、９０歳、９９歳。社会福祉協議会を通じまして、各町会、平成１５年度では１６２町会・自治会に対しまして、長寿お祝会を行う町会に対しまして。","id":"exchange-102"},{"speaker":"高星委員","kind":"提案","question":"これは時間の関係もあるからあまり長いこと言えませんけれども、私思うんですが、これまで私もワンルームマンション等々の問題で、住民票のないお年寄りの方のことも指摘をさせていただいたんですけれども、どうしても、これはふれあいサポートの関係があるから何とも言えないのですが、お年寄りの安否確認、日常的な、近隣とのおつきあいは。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"民生委員の関係です。先ほど私９０％ぐらいの方の推薦が終わっていると申し上げましたが、３２２名の定員のところ、３０５名の方の推薦をいただいております。９５％ぐらいの推薦をいただいているという段階です。今後とも友愛活動については活動が進むように努めてまいりたいというふうに考えてあります。","id":"exchange-103"},{"speaker":"高星委員","kind":"質問・要望","question":"わかりました。どういう町会活動、どんなことをやりましたかとかを含めて、町会の婦人部長をやりましたとかなんか、経験ありますかどうかまで全部書いてあるんです。だから、そこは最終的には町会長が総責任ということで判こを押すんですけれども、町会長の判こだけでいいんじゃないかというような感じがするんで、そうしないと、これから先ちょっと心配なのでお聞きしました。要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104","title":"町会・自治会支援"},{"speaker":"中島委員","kind":"質問・要望","question":"私は１１９ページ、高齢者福祉費の在宅介護者激励研修事業、それと地域ケア会議等事業、それからその下のほうにあります年賀状のことについて、それから１２７ページ、児童福祉施設費の先ほど出ました家庭あんしんセンターに関連して、産後支援ヘルパー派遣制度、このことについてお伺いいたします。初めに、在宅介護者激励研修事業と、それから地域ケア会議等事業、この内容を教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"地域ケア会議のほうですが、こちらは名称どおりの地域ケア会議、これはケースを検討したりというような会議ですが、そのほかに特別養護老人ホームへの入所調整会議もこの中に入ってあります。それから、徘徊高齢者のＰＨＳに関する事業費もこの中に計上しています。","id":"exchange-105"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、在宅介護者激励研修事業というのは、介護される方の研修ということなんですが、介護されていない方でも、やはり介護のノウハウというかポイントとか、そういったものを学ぶ必要がこれからはあるのではないかな、このように私は感じているんですね。そうしたものを多くの人が学ぶチャンスというものが必要になってくるのではないかと思うんですが、この点はどのようにお考えでしょうか。","respondent":"早津高齢福祉課長","answer":"例えば今年度ですけれども、痴呆に関することをいろいろ勉強していただこうというようなことも行っておりますし、来月には痴呆のシンポジウムも広く呼びかけまして、介護に関する知識を、実際に介護をされていない方にも身につけていただこうという活動も広めているところです。","id":"exchange-106"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひこの事業はもっと強化をしていただきたいなと思っているんですね。できれば、私は、今テレビ局でもいろんな番組でやっていますけれど、品川ケーブルテレビなどでも、こういったことを大きくアピールしていくということが大事ではないかなと思うんですが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"ケーブルテレビも含めまして、ＰＲの仕方については改めて検討させていただきたいというふうに考えております。","id":"exchange-107"},{"speaker":"中島委員","kind":"質問","question":"介護者の方のストレスがたまると、高齢者に対する虐待といった、そういった問題にも達してしまうこともあると思いますので、ぜひよろしくお願いしたいと思います。それから、地域ケア会議というのは、先ほどいろんな徘徊だとか、そうしたものの対処ということでなさるということなんですが、どういった方がここでは会議をなさるんでしょうか。","respondent":"早津高齢福祉課長","answer":"地域ケア会議は、基本的には介護支援センターのケアマネジャーたちが集まりまして、担当しているケースの中で、困難な事例等を検討する中で、それに直接携わらない人間も自分の場合はこうだということをスキルアップを含めて検討していくものでございまして。","id":"exchange-108"},{"speaker":"中島委員","kind":"質問","question":"これは相当数の方がかかわるんでしょうか。非常にこれは費用のほうも２,３００万円と大きくかかっておりますので、どのぐらいの方たちが参加されているのかなとちょっと疑問に思ったものですから。","respondent":"早津高齢福祉課長","answer":"先ほど申し上げましたのは、地区ごとに行っておりますので、１３カ所の地区で毎月１回の開催ですので、かなりの人数が集まるということになります。","id":"exchange-109"},{"speaker":"中島委員","kind":"質問","question":"はい、わかりました。それから、年賀状のところなんですが、ここで２万人の方に「年賀状等」を出しているということで、多分区長のお名前で出されているんではないかなと思うんですが、年に何回出されているんでしょうか。","respondent":"早津高齢福祉課長","answer":"「年賀状等」といいますのは、暑中見舞いと年賀状の２種類です。","id":"exchange-110"},{"speaker":"中島委員","kind":"質問","question":"金額的にはそう大きくはないんですが、それでも１５７万円という金額になっておりまして、区長のお名前でよろしいんでしょうか、内容は、違いますか。","respondent":"早津高齢福祉課長","answer":"「品川区長」としています。","id":"exchange-111"},{"speaker":"中島委員","kind":"質問","question":"ただ、印刷だけですと非常になんか味気ない、無味乾燥という感じの受けとめ方をなさる方も中にはいらっしゃるんじゃないかなと思うんですが、年に２万人の方に出すということで、手書きということは大変な作業だと思うんですが、今はいろんな技術が進歩しておりますので、手書きに近い、一言でもちょっとしたそういう配慮があってもいいんじゃないかなと思うんですが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"パソコン等も活用して、その辺は工夫をしてみたいと思います。","id":"exchange-112"},{"speaker":"中島委員","kind":"提案","question":"ぜひ、そうしたはがきに、せっかく５０円かけるわけですから、いただいた方が品川区の心が感じられるように、よろしくお願いしたいと思います。続きまして、先ほど産後支援ヘルパー派遣制度、このことが出ておりました。この産後支援ヘルパー派遣制度というのは、予算はどこから出ているんでしょうか。","respondent":"辻田児童課長","answer":"これはやっている主体が家庭あんしんセンターでやっておりますから、家庭あんしんセンターで支出しているわけですが、東京都から補助金が出ているという状況です。","id":"exchange-113"},{"speaker":"中島委員","kind":"提案","question":"この当時、私は国の母子保健施策の推進ということで、そうした予算措置があるからということで、ここで提案させていただいたんですが、東京都から出ているということで、この予算の使い方というのは制限があるんでしょうか。先ほど井上委員がおっしゃっていたように、いろいろ仕事に制限があるようですが、この予算の使い方に制限があるわけですか。","respondent":"辻田児童課長","answer":"それで、標準的な部分につきましては、実施のヘルパーの登録要件というところで、看護師、保健師、助産師、保育士の有資格者というような形でここに書かれております。","id":"exchange-114"},{"speaker":"中島委員","kind":"質問","question":"今のご説明だと、確かにそのとおりだと思います。ところで、今回１０月１日から三鷹市でやはり産後支援ヘルパー派遣制度というのが始まりました。ここでは、全部、炊事、洗濯、掃除、ここまで入っているんですが、これはどこから出ている、どういう制度になっているのか、こちらでは把握されていないでしょうか。","respondent":"辻田児童課長","answer":"ですから、要するにやむを得ずにしなければならないときには、こういう部分もきちっと支援しますよです。ただ、本筋は先ほど申しましたような形です。","id":"exchange-115"},{"speaker":"中島委員","kind":"質問","question":"実は、私も昨年か一昨年だったと思いますが、委員会で取り上げたかもしれませんが、３人お子さんがいる家庭で、次に産まれたお子さんが三つ子だったということで、一遍に６人になってしまった。こういう家庭がございました。その辺のところをきちっと指導できるようなもう一度ネーミングなり、また制度なり、アピールなり、考えていただいたほうがいいんじゃないかなと思いますが、いかがでしょうか。","respondent":"辻田児童課長","answer":"それは一つ一つ丁寧にお答えすることによって違うんだというような形です。ただ、基本的には産後間もないために困難なこと、家事は基本的には実施するということです。","id":"exchange-116"},{"speaker":"中島委員","kind":"質問","question":"よくわかりました。それとともに、先ほど言われたように、今これは保健師の方だとか看護師の方たちが、そういう経験のある方たちというと非常にプライドもあると思いますので、仕事の内容によって派遣される方もいろんな方がいらっしゃると思うので、その辺のきめ細かな目配り気配りというか、そういったものも必要かなと考えていますので、いかがでしょうか、その辺のことは。","respondent":"辻田児童課長","answer":"そういう中では、講習会の受講者、それから熱意のある方、要するに子育ての経験のあるような方の実際的なアドバイスというのも非常に有効になるかなと考えています。そういう意味で、その辺の人材も今後十分確保しながら体制を整えていきたいと考えています。","id":"exchange-117"},{"speaker":"中島委員","kind":"質問・要望","question":"わかりました。ぜひ誤解のないように充実した子育て支援になるように要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"菊地委員","kind":"質問","question":"それからもう一点です。国民年金ですとか、あるいは厚生年金でも、ここの水準にまで達しない方がいろいろいらっしゃるかと思うんですけれども、こういう方たちは先にお聞きした人数把握のときの基準と一緒になりますけれども、こういう方たちは入居資格がもともとないのか、それとも少ない、ここの１８万円というところに達しなくても何か入居する手だてがあるのかどうか、まずこの３点、お聞かせ願います。","respondent":"早津高齢福祉課長","answer":"「温々」が対象になりましたのは、民間企業が設置をするというタイプのものでございまして、これが東京都の補助が４分の１ということで、それぞれの設置者がだれか、それからどういう形であるかによって、東京都が補助する額というのが異なっておる関係で。","id":"exchange-119"},{"speaker":"菊地委員","kind":"質問","question":"しかも、次のグループホーム、大田区がつくろうとしている次のグループホームですけれども、これも同額程度、１３万円程度で施設運営ができるような事業者を募集したところ、九州の事業者が手を挙げて、同額程度で開設をするというふうになったそうですけれども、同じように厚生委員会ですけれども、都市部ではサービスや経費がかかるという答弁がありましたけれども。","respondent":"早津高齢福祉課長","answer":"痴呆の高齢者について、どうしてですが、痴呆症状が見られる高齢者というのは、品川区の場合で約４,０００人いるであろうというふうに大体想定されることでありますし、また、これは現場のケアマネジャー、あるいは私ども高齢福祉課のケースワーカー等の話を耳にしても。","id":"exchange-120"},{"speaker":"菊地委員","kind":"質問・要望","question":"時間がないのであれなんですけど、私とにかく少ない年金暮らしの収入の皆さんが入居可能なシステムというのをぜひもっと研究していただきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"私は２点お伺いをいたします。１２４ページの乳幼児医療費助成に関して、それからもう一点は、１２７ページの家庭あんしんセンター運営費に絡んで子育て相談に関しての質問をします。１点目の乳幼児医療費制度に関してであります。それで、この部分に関してのそれまでの所得制限の考え方についてお聞かせをいただきたいと思います。","respondent":"辻田児童課長","answer":"長年この乳幼児医療費助成につきましては、所得制限を入れた形で実施をしてきました。２３区の中で品川区だけ所得制限を入れているということで、私どものほうは福祉施策としての位置づけをしながら胸を張ってこの制度を守ってきたわけです。","id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、その後の、先ほども申し上げたように、小学校卒業まで所得制限つきで、当初決めたものを、多くの区民からの声があったですが、その多くの区民の方々の声をぜひお聞かせいただきたいと思います。具体的にどのようなものがあったのか。","respondent":"辻田児童課長","answer":"長い方では１時間、２時間のお話をしながら説明をしていくという状況の中で、理解を求めていこうということでやってきました。それで、その中の声としては、制度が拡大できるのなら、まず自分たちを対象にすべきであろうです。","id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"午前中の石田委員のお話にもありましたように、ある種今後の考え方として、受益者負担というものも一方では求めていきながら、ある一定程度の利益を得る方には、一定程度の負担もしていただきたいという思いで、今回も保育料の最終的には目標は国の基準に対する６０％が目標かと伺っておりますが、そういう方向にある。","respondent":"金子保育課長","answer":"ただいま子育て支援施策のところから保育料あるいは私立幼稚園の補助金等を含めまして、受益者負担の考え方についてのお尋ねですが、私ども例えば保育に関しては、これまで措置というものでしたが、これが契約という概念に変わっています。","id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"さらにそこに施策によって所得のあるなしによって、いわゆる所得制限を設けるというのは、ある種二重の所得の再配分を行おうとしているのではないか、そういうところに受益者負担の考え方からして、少し不公平感があるのではないかという一方の思い、その思いが通じ始めたからこそ、私は当初は所得制限があっての「子どもすこやか助成」だったものに所得制限がなくなってきたんだ。","respondent":"高橋区長","answer":"議会からももう少し何とかならないかというご要望もいただきました。うちも６割から８割、８割から９割というふうに所得制限の撤廃をしてまいりました。１割程度ならば認めていただけるんじゃないだろうか、こういうふうな考え方で実施をしてまいりました。","id":"exchange-125"},{"speaker":"田中委員","kind":"質問・要望","question":"強いご決意といいますか、お考え、よくわかりました。その他、大井倉田にも、また各児童センターにもありますが、インターネットで２４時間やっております。それは子育てには、我々男性もかかわってきますので、いつでもアクセスできるようなインターネット、そういった意味で活用できるんではないかという思いがありますので、最後、ちょっと時間がありませんが、一言お聞かせいただきたいと思います。","respondent":"辻田児童課長","answer":"開設から約２年かかっております。その中で、今までの実績を踏まえた上で、その辺について検討していきたいというぐあいに考えております。","id":"exchange-126"},{"speaker":"沢田委員","kind":"提案","question":"私ども、１０年前から８回にわたる条例提案を行ってきて、今度の改正はほんとうに区長の勇断だと思いますし歓迎するものです。ありがとうございました。それで、今の受益者負担の問題の考え方でちょっとお尋ねしたいんですが、受益者負担制度がいいか悪いかというのはちょっとこっちに置いておいて、子育てをするというのは、本人の家族と子どものためだけじゃなくて、受益を受けるのは社会全体なんだ。","respondent":"高橋区長","answer":"社会が受益者じゃないか。だから、当然国が負担すべきだということですが、それは国が負担するから無料化になるわけでして、ですから、社会が受益者ですから、その受益者である国民一人ひとりが負担をしても、私はよろしいんじゃないかと考えています。","id":"exchange-127"},{"speaker":"沢田委員","kind":"意見","question":"時間がないので簡単に言わせてもらいたいと思います。それからもう一つ、私が言った少子化を支援する、少子化を克服することは、その子どもと家族じゃなくて、受益者は社会全体だから少子化に取り組む、そこに財政を注ぎ込むということは、むしろ積極的な面なんだ、そのことの考えを聞いたんですけども、時間がありませんので、そのことだけ述べて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"私は１１８ページ、高齢福祉費についてお聞きいたします。２０００年度に始まりました国の介護保険制度は、法律で施行５年後の２００５年度に見直すことになっております。介護保険サービスは特別養護老人ホーム、介護老人保健施設、介護療養型医療施設の３施設からなる施設サービスと居宅サービスに大別されます。約３１％も増加しております。","respondent":"高橋介護保険担当課長","answer":"今後のスケジュール的なものにつきましては、こうしたものがこの１１月後半に制度改正のものの取りまとめとして、目途にまとめられまして、平成１７年１月に部会報告がまとめられまして、法案として２月の通常国会に提出されるという予定になってあります。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"大体今の段階でどのような案というんですが、出ているんでしょうか。わかる範囲で結構なんですけど。","respondent":"新美福祉高齢事業部長","answer":"今、介護保険担当課長が答弁申し上げましたように、９月から１０月、 １１月、４回の部会の中で議論するということで、９月の部会では新たな意見というよりは、今後の向こう３回の論点整理がなされたのみというふうに聞いておりますので。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"ですから、今の段階では明確な指針というか、そういう方向性というのはまだ出ていないという報告をお聞きいたしました。そして次に、品川区の介護保険特別会計を見ますと、歳出は平成１２年度のおよそ８７億円だったのが、平成１５年にはおよそ１３０億円にも達しています。そして、それに対する対応策、どういうことを今区のほうで考えているのか、それもあわせてお聞かせください。","respondent":"早津高齢福祉課長","answer":"私どももこの構造自体は介護保険制度というものの中で出ていることですので、この法制度の改正の中である程度の抑制というようなことも議論されるというふうに聞いておりますので、この議論の流れを注視していきたいというふうに考えております。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"今、法制度の中でというお話だったんですけど、例えば区のほうとして、今動きとしては先ほどもお話が出ていましたけど、介護予防という案も一つ出ているということなんですけど、やはりそちらのほうにますますシフトするというような方向でしょうか。","respondent":"早津高齢福祉課長","answer":"制度見直しの中でも、大きな三本柱かありますが、そのうちの一つが予防へのシフトということでございまして、ご指摘のとおりだというふうに考えます。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"ここでちょっと別の角度からお聞きしたいんですけど、介護保険の財政の圧迫などの理由は、５００を超える自治体が痴呆高齢者が共同生活するグループホームの設置を実質的に規制しているというお話を聞いたんですけど、ちょっとお聞きしたいんですけど、区内に介護が必要な、そういうグループホーム等が増えると、どうして区の財政が圧迫されるのか、ちょっと簡単な質問だと思うんですけど、お答えください。","respondent":"早津高齢福祉課長","answer":"そういう面で、グループホームがこれは先ほどの話と重なりますが、土地の値段、それから建設費とかとかかわるものですから、地方によってはかなり乱立気味の自治体というのが現にあります。そういったところでは、財政の圧迫の原因の一つになっているということだと考えます。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"できれば、先ほどもお話が出ていましたけど、本来もっとグループホームというのはつくっていかなきゃいけない。ですから、まだそう財政は圧迫してこないということなんでしょうかと思うんですけど、では、ちょっとお聞きしたいんですけど、今介護予防に進まなきゃいけないということなんですけど、介護予防に今現在どれだけの予算を費やしているんでしょうか。わかる範囲でいいんですけど。","respondent":"早津高齢福祉課長","answer":"私ども直接には身近でリハビリの事業なんかが典型になりますし、また筋力向上トレーニングというような事業が対象になるんですが、金額はちょっと今すぐには出ません。申しわけございません。","id":"exchange-134","title":"町会・自治会支援"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみませんでした。ですから、ちょっとそれをお聞きしたかったんで。それはまた、わかるんですか。じゃあ、後で結構です。筋力トレーニングも大切だと思うんですけど、こういうふうなライフサポーターというんですか、このような方というか、こういう流れというんですか、こういうものも介護予防に非常に大切で重要な要素だと思うんですね。その辺についてちょっと見解をお聞かせください。","respondent":"早津高齢福祉課長","answer":"気になるおひとり暮らし等で閉じこもりの方については、デイサービスセンターに通ったりとか、そういうのをきっかけにして、自宅から外に出るというようなことを今後も続けていきたいというふうに考えてあります。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"今そこに来てくれとか、来てもらったら、行けるなら全然問題ないわけですから、ただ、現状はやはり歩くのがおっくうになって、それでやはり出にくくなると。じゃあ、だれかライフサポーターがいれば一緒に行けると、２人いれば何とか行ける、そういうような状態のことを今私申し上げていたんで、ぜひご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"南委員","kind":"質問・要望","question":"１２４ページの認証保育所について伺います。この決算書には認証保育所の運営助成で１億３３０万円、そして施設整備助成で４８５万円が計上されていますが、Ａ型、Ｂ型、何園分になるんでしょうか、お知らせいただきたいと思います。そして、先ほどの認証保育所のご質疑の中で、今年度は８カ所だというふうに答弁がありましたが、一緒に今年度のＡ型、Ｂ型の保育園数も、数で結構ですから教えてください。","respondent":"金子保育課長","answer":"認証保育所の運営助成につきましては、何回かお答えしているとおり、これらに通っている区民の分、また区外の認証保育所に対して通っている区民の子どもの分をそれぞれ東京都と区で２分の１ずつ助成しているというものです。","id":"exchange-137"},{"speaker":"南委員","kind":"質問","question":"そういうことで承知しておりますけれども、Ｂ型のところというのは、０歳から２歳までということで、３歳になると幼稚園に行かれる方もおいででしょうけども、どちらかのできたら公立保育園に入りたいという方もいらっしゃるでしょうし、そういうふうに考えたときに、区の認識として補完的な役割もあるのかというふうにとらえていらっしゃるのかどうか、ちょっとその辺の認識を伺いたいと思うんです。","respondent":"金子保育課長","answer":"一方、Ａ型につきましては、これは都市型の保育施設ということで、経営主体が株式会社も含めて多様な経営主体を可能としているもの、それから先ほど申し上げたとおり、駅から５分以内のところに設置すれば、改修費が出るというふうな形で駅前に。","id":"exchange-138"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、補完的な役割を果たしているＢ型の認証保育所がさらにこれから区民の期待に応え、品川区の保育行政に応えて、豊かな子どもを育てていくという、そういう施設で存続を安定的な経営をしていくためには、何らかのこういう他区に学んだ財政的な支援、助成を拡大していく必要があるんじゃないかなというふうに思っていますけど、そのあたりの見解をちょっと伺いたいと思います。","respondent":"金子保育課長","answer":"少なくとも、先ほど申し上げたとおり、Ａ型、Ｂ型含めて多様な経営主体が経営しているというところから、これらの運営についてはそれぞれの経営主体がそれなりに工夫して努力すべきものというふうに考えておりますので、私どもとしては再三申し上げるとおり。","id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"そして１日何時間預けるかということでも違っているんです。そして、経営者が経営上非常に安定できないから不安に思っていると、こういう実態があるわけですから、ここのところは東京都とよく相談されて、３分の１のところでやっているわけですから、ぜひ実施をするべきだというふうに思います。ここの見解についてどういうふうに考えていられるのか、最後に聞いて終わりにしたいと思います。","respondent":"金子保育課長","answer":"先ほども申し上げましたが、私どもとしてはこの制度を平成１３年度からスタートして、まだまだ実績を積み上げている過程で、そういう意味では経営的な安定というのは難しい部分もあるかとは思いますが、先ほど申し上げたとおり。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひこれからも検討していただきたいということを最後に終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"築舘委員","kind":"質問・要望","question":"先ほども出ましたけど、１１７ページの痴呆性高齢者グループホームに関してと、それに関連してデイサービス事業ということで、痴呆に関してお聞きしたいと思います。それで、そこに入るにおいて、先ほどちょっとケアマネジャーの相談のもとという話がありましたけど、どの程度の人たちが要望して、そして今何人入っているかという現状を教えてください。","respondent":"早津高齢福祉課長","answer":"グループホーム温々は６人の定員でございまして、現在６人が入居されておりまして、３月オープンいたしまして、グループホームというのは家庭的な雰囲気を新しいメンバーでつくりあげていくということで、その初動がなかなか難しいそうなんですが。","id":"exchange-142"},{"speaker":"築舘委員","kind":"質問","question":"ですから、グループホームの場合も、ある程度デイサービス事業をやっていらっしゃって、それである程度家族との対話をしているわけですよね。初期の時期なら痴呆がまだそんなに進んではいないんだけれども、グループホームというのはどうなんですか、ずっと住むんでしょう。ちょっとそこら辺の定義を教えてください。そこのところをちょっと聞かせてください。","respondent":"早津高齢福祉課長","answer":"しかしながら、アルツハイマーが典型になりますが、病状として進行していきますと、どうしても医療の必要が出てくる場合があろうかと思います。その場合はグループホームではなくて、やはり病院のほうに医療的な看護が必要になるんではないかというふうに考えております。","id":"exchange-143"},{"speaker":"築舘委員","kind":"質問","question":"それだったら、在宅をもっと充実させて、そして在宅で家族がしっかり見て、家族が疲れた分、デイサービスでいやすというか、そのほうがかなり進歩的というか、考え方としてはいいと思うんですけど、どうでしょうか。","respondent":"早津高齢福祉課長","answer":"グループホームと在宅サービスとしての痴呆デイサービスですけれども、これは片方があれば、片方は要らないというものではなく、やはり一定の症状の進みぐあい、それから家族としての介護力の度合いというようなものがいろいろ複雑に絡まりますので。","id":"exchange-144"},{"speaker":"築舘委員","kind":"意見","question":"まあ、そうなんですけどね。ただ、そういう心配をやっぱりしていかなければいけない。要するに、民間に任せて、それでいいですよという状況でもないだろうということですよね。現在、痴呆の専門医の協力を得て、その二つをやっているんですけど、その現状と、それから家族の相談をやっていますけど、家族の相談で、どういうふうな意見が出ているのか、これをお聞かせください。","respondent":"早津高齢福祉課長","answer":"その場でのご家族の、やはり専門のお医者さまの意見というよりも、どういうケアをしたらいいのかというようなことをお尋ねになる機会が多うございまして、個々のお尋ねに対して、専門ドクターのほうからアドバイス等が行われるという。","id":"exchange-145"},{"speaker":"築舘委員","kind":"意見","question":"しっかりとそれはデータが出ているはずなんですよね。だから、どういうことが特徴で、どういうふうな意見がありますというのは、やっぱりある程度言ってもらわないと困るなと思いますよ。それはやっぱり、常に二つのことというのは、要するにデイサービスというのは、新しいことをやっているんだから。それで、これからグループホームだって、どうするか。もう一回お願いします。","respondent":"早津高齢福祉課長","answer":"私聞き違えていたのかもしれませんが、家族の方と専門医の間でどういうことかということかと思ったんですが、そうではなく……違いましたでしょうか。失礼しました。","id":"exchange-146"},{"speaker":"築舘委員","kind":"質問","question":"じゃあ、わかりました。要するに痴呆の専門医がいるでしょう。いますよね。それから、家族で相談しているじゃないですか、いつも家族相談をやっているでしょう。その家族の状況の意見というの、それが出てくるじゃないですか。その内容の、お互いいろいろあるでしょうけど、どこが一番困っているかということをちょっと言ってくださいという話をしているんですよ。","respondent":"早津高齢福祉課長","answer":"そうすると、先ほどのと重なってしまうかもしれませんが、家族の相談というのは、痴呆の進行に対する不安というのが基本にありますので、そういったことの相談であり、アドバイスがなされているです。","id":"exchange-147"},{"speaker":"築舘委員","kind":"質問・要望","question":"じゃあ、いいですよ。要するにデータが上がってきたものをしっかり分析して、次に対処してくださいと、こういう要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"川西委員","kind":"質問","question":"初めに、成果報告書１１８ページ、有償在宅福祉サービス等の再構築の事業実績について伺います。そこで、今事業所委託ということで派遣をされていますけれども、おわかりになったら平均年齢、それから１年間、この平成１５年度の間にホームヘルパーを実際にされている方々の研修活動というのはされたのかどうか伺います。行けるときには銭湯をかなり利用していた。そこで改めて１点目について質問をします。","respondent":"福島福祉高齢事業部副参事、早津高齢福祉課長、蓼沼高齢事業課長","answer":"主な内容としましては、さわやかサービスで行いました入退院時サポート等の事業を行っているところです。２０名定員で行っているところです。そういう意味では、私どもとしては、そういう地域の公衆浴場の振興を兼ねまして、出会いの湯事業等を実施しています。","id":"exchange-149"},{"speaker":"川西委員","kind":"質問・要望","question":"しながわ出会いの湯に昔やっていた入浴券の交付事業が変わりまして、こういうふうになりました。書いてあります、ここにね。ですから、月額働くのに、この仕事になろうかという、給料の面だけでされる方もいらっしゃるんですね。最初に有償在宅福祉サービスをお聞きしたのは、今二つ申し上げたような内容を社会福祉協議会の中でも検討していただきたいというのが私の希望ですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"三上委員","kind":"質問・要望","question":"最初に日常生活の支援についてちょっとお伺いしたいと思います。これに関して、私も準備していたものですから少し質問させていただこうと考えています。１１万５,０００円定価ですると、こういうふうになっていますけれども、この日常生活用具に加えられたことによって、その障害をお持ちの方はどれくらいの価格を負担すれば入手できるのか、ここらあたり、ちょっとお教えいただきたいと思います。","respondent":"西島障害者福祉課長","answer":"前年度の所得税の非課税世帯で、均等割のみの課税世帯が４,５００円、所得割の課税世帯ですと５,８００円、以下、前年の所得税に応じましてランクがずっと載っておりますので、ちょっとここで読み上げるのはとめますので、よろしくお願いいたします。","id":"exchange-151"},{"speaker":"三上委員","kind":"提案","question":"このＳＰコードについては、私どもの会派の前議員が平成１４年第３回定例会でこれについて質問し、ぜひ導入すべきであると提案しておいたわけです。そこのところで、現実にＳＰコードというものはどういうものなのかということを知らないと普及しませんよね。ここにいらっしゃる課長にお聞きしちゃうと大変失礼かと思うんですけども、どういうものなんですか、このＳＰコード。","respondent":"西島障害者福祉課長","answer":"ちょっと言葉であらわすのは難しいんですけと、ソフトそのものは開発された会社がインターネットを通じてオープンにいたしまして、ワードからとれば、その情報はそのまま使えるようになってあります。","id":"exchange-152"},{"speaker":"三上委員","kind":"質問","question":"それから１０月４日付の読売新聞の夕刊記事に載っておりましたけども、ご承知でしょうか。世界的な動きの件で。","respondent":"西島障害者福祉課長","answer":"申しわけございません、１０月４日の新聞はまだ拝見してございません。","id":"exchange-153"},{"speaker":"三上委員","kind":"質問・要望","question":"条約案は障害を理由とするいかなる種類の差別も禁止すると明記した上、教育、雇用、公共施設の利用などに関する障害者の権利を確保するため、過度な負担を生じない範囲での合理的な配慮を締結国に求めている。関係国は２００５年秋か２００６年の条約採択を目指している。これについての取り組みについて、簡単でいいですから、どこがやってどうするか、お考えをお聞かせいただきたい。","respondent":"西島障害者福祉課長","answer":"今読み上げましたように、障害者の自立と社会参加というのが大きな世界の流れです。ご指摘の内容につきましては、障害者福祉課のほうで庁内について周知をしてまいりたいというふうに考えてあります。","id":"exchange-154"},{"speaker":"三上委員","kind":"質問・要望","question":"これはぜひ早急にそういうふうな取り組みに向けていっていただきたいと思います。既に障害をお持ちの方について、こういうものがありますというお知らせを当然すべきです。用具があって初めてわかるものであって、そういう部分について、しっかりと取り組んでいっていただきたいと、これはお願いしておきます。これは企画のほうもぜひお願いしておきたい。企画部長、どうでしょう。","respondent":"中尾根企画部長","answer":"企画は事業部の支援をする部署ですので、今後の施策について十分支援していきたいと考えています。","id":"exchange-155"},{"speaker":"三上委員","kind":"提案","question":"それで、この件に関しての今年の第１回定例会の中で、私はこの医療費助成制度そのものがいろいろ取り組む中から、幼児期から小学校まで広がった機会をとらえて、子どもの一貫した健康管理を図るために事業に必要な医療証にＩＣカードなどを活用して、健康診断記録や治療医療記録などを記録し、健康増進、健康管理に活用することを提案するものであると提案しておりました。","respondent":"辻田児童課長","answer":"というのは、この制度は来年の４月から何とか２３区の中ですべて使えるような形でやっていこうということで進めていたところ、台東区が発表いたしましたので、台東区、それからもう一区の区が強力に２３区での現物支給ができる制度に乗せていこうということで現在やっております。","id":"exchange-156"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう答弁が返ってくるだろうと思っていたんです。ですから、厚生労働省のそういった検討が始まったという、その動向についてどうなっているんですかとお聞きしたわけですよね。わかっているからそういうふうにお聞きしたわけです。厚生労働省のほうは、どういうふうな今動きになっているか、おわかりか教えていただきたい。","respondent":"田中健康課長","answer":"その推移を少し見ながら、この間の一般質問のご提案等も検討していきたいという内容です。","id":"exchange-157"},{"speaker":"三上委員","kind":"質問・要望","question":"ぜひ情報を、とにかくアンテナを張って、品川区でこういう方向性であるということが先に取り組んでいかれるように、ぜひ取り組んでいっていただきたいとお願いしておきます。これについてどのような印象を持っていられるか。その施設が現状どうなっていらっしゃるんでしょうか。","respondent":"金子保育課長、蓼沼高齢事業課長","answer":"入園予約を実施するためには、４月からこの部分の枠をあけておかなければならないということで、この枠を拡大するのはちょっと困難かなと考えていますので、そういう意味では、いろいろなサービスをご案内する中で。西五反田の施設利用ですけれども、１階はシルバー人材センターが入っております。２階、３階が今あいているという状況です。","id":"exchange-158"},{"speaker":"三上委員","kind":"質問・要望","question":"それだけに、この申し込んだときにどういうふうに、期待して申し込むわけですよ。早く申し込んで、産まれる前から申し込めば入れる、予約ができるんだという制度ですから。それだけに、この制度をどういうふうに、不公平感のないように、どういうふうに運用していくかということは大変な問題だと思いますよね。どのようにお使いになろうと考えていらっしゃるんですか。","respondent":"金子保育課長、鷹倉経理課長","answer":"入園予約の制度のこの現状で、不公平感があるのではないかというお尋ねですけれども、私どもとしましても、入園予約の選考基準については、やはり絶えず申込者のニーズを調査して、できる限り不公平感がないように努めてまいりますし。不動前の空き施設の今後の活用ですけれども、今特に検討をこれからしていくという状況ですけれども、今後検討して、またご報告していきたいと思います。","id":"exchange-159"},{"speaker":"三上委員","kind":"質問","question":"どうやったって希望に応えられない。応えていくということは、当初１年間空けておかなきゃならないわけですから。そこについてもう少し、ほんとうに真剣になって検討をお願いしたいと思います。改装した時点でしっかりとやっているわけですから、人が生活できる施設になっているわけですよ。そういう人たちに活用することだって考えたっていいと思いますが、いかがでしょうか。","respondent":"鷹倉経理課長","answer":"大変失礼いたしました。今の当該の場所につきましては、上大崎の第二支援センターという形で、今年の３月末までは使用していたです。その後のことについては先ほど申し上げたとおりです。","id":"exchange-160"},{"speaker":"三上委員","kind":"質問","question":"いつまで使っていたかどうかって、現実に今空いているわけですから、それに対してどうするのかと。住宅あっせんだって品川区は手を引いたじゃないですか。そのことについてどう改善していくかということについて、こういうふうに空いている施設があれば、今喜ぶ人が何人もいるじゃありませんか。そこのところに対応するということを考えていかなきゃおかしいじゃありませんか、助役、どうですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"},{"speaker":"原委員","kind":"質問・要望","question":"生活保護のほうですが、ここのところ平成１３年から３億円、５億円というぐらいに毎年毎年伸び率が急上昇していますが、特に平成１５年は一般財源でも１７億円を使って対応して、国のほうは６３億円出しているわけですけれども、生活保護の決定で生活保護基準額というものは毎年変化を、要するに見直されてきているわけですが、判断基準というところで。","respondent":"志村生活福祉課長、早津高齢福祉課長","answer":"委員の質問にありましたとおり、平成１５年度に初めて基準改定ということで、減額というんですか、前年の基準改定に比べて初めて、この制度が始まって以来初めての減額ということになったところです。例えば、民間企業がグループホームを建設するのに、従来ですと東京都が４分の１、これは先ほどの議論にもありました「温々」が受けていた補助率と同じなんですが、これが指定を受けることで。","id":"exchange-162"},{"speaker":"原委員","kind":"質問","question":"判断基準はここ何年も変わっていないということは、どのぐらい変わっていないんでしょうかね。そして一方では、今緊急整備事業の中では、民間業者の場合は４分の１の２分の１を都が補てんしますよということで、行政のほうは主体に考えていて、今民間のほうは「温々」が１社頑張っているようですけども、そういった中での民間の参入ということについてはどう考えていらっしゃいますでしょうか。","respondent":"志村生活福祉課長、早津高齢福祉課長","answer":"生活保護の基準の件についてお答え申し上げます。私、ちょっと先ほど説明いたしましたとおり生活保護法は昭和２５年に制定されて以来、基本的な原理ですとか原則、これは変わっていないと、こういうことです。ただし、民間企業の場合ですと、グループホームの経営というのは、経営的にも難しいですし、提供されるケアの質というものがかなり高度なものということで、手を挙げればだれでもいいだろうというふうには考えておりませんで。","id":"exchange-163"},{"speaker":"原委員","kind":"意見","question":"そこはやはり、持っていき方が非常に難しいんではないかなというふうに思うんですが、そこのところ、お考えがあったら聞かせてください。それから、グループホームのほうですけれども、それじゃあ「温々」は非常に今１社だけということで頑張っているということなんですが、その基準を満たした形の中で参入できたということだろうと思うので、そこのところだけちょっとお話を聞かせてください。","respondent":"志村生活福祉課長、早津高齢福祉課長、林（和）委員長","answer":"ですので、大変難しい課題ではありますけれども、引き続き取り組んでいきたいと、かように考えてあります。株式会社恵愛につきましては、長期の訪問介護事業者としての実績のほかに、大井におきまして。以上をもちまして、本日予定の審査はすべて終了いたしました。次の会議は明日午前１０時から開きます。本日はこれをもって閉会をいたします。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/180055?Template=document&Id=1232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":120282,"voices":374}}]);
